INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10111656844', 'Protetor de Ouvido Moulded Earplug Speedo Transparente', 'Protetor de Ouvido Moulded Earplug Speedo Não deixe que a água em seus ouvidos impeça seu desempenho nas piscinas. Feito em Silicone, o Protetor de Ouvido Speedo Moulded Earplug se encaixa perfeitamente, oferecendo total conforto. Nome: Protetor de Ouvido Speedo Moulded Earplug Gênero: Unissex Indicado para: Praticante Tipo: Protetores Material: Silicone Composição: 100% Silicone. Itens inclusos: 01 par de protetores e 01 caixa protetora Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 45.0, 45.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/face90b7384136962c413cb39ed77af8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F10111656844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23026956001', 'Cueca Descartável Tena Pants Men P/M 16 Unidades', 'TENA Pants MEN é uma roupa íntima descartável que veste como cueca, desenvolvida especialmente para homens com incontinência urinária moderada que buscam conforto, discrição, segurança contra vazamentos e manter o cuidado com a pele. Possui neutralizador de odor e uma zona de absorção segura, formato anatômico que se ajusta perfeitamente ao corpo proporcionando conforto, facilidade de uso e discrição. A segurança deve-se especialmente à uma zona de absorção frontal que absorve rapidamente a urina, mantendo-a longe da pele e assim, deixando-a seca, auxiliando a reduzir o risco de irritações ou infecções cutâneas. TENA Pants MEN é ideal para homens ativos, discreto como uma cueca, com controle de odor e alta absorção. Zona de absorção segura - Centro de absorção frontal para maior segurança contra vazamentos; Masculino e Discreto - na cor azul marinho e modelagem masculina; Neutralizador de odores - Para extra confiança; Melhor ajuste - Material flexível, macio e respirável; Toque extra suave - Material semelhante ao tecido que garante mais maciez ao produto, sem o ruído típico de plástico, proporcionando maior conforto; Elásticos suaves em volta da cintura permitindo uma adaptação perfeita ao corpo; Elásticos duplos nas pernas para um melhor conforto e segurança contra vazamentos; Costuras laterais removíveis para retirar o produto com maior facilidade.', 98.09, 98.09, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-23020-pgw1mkc7bwnva1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819145905%2F23026956001', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692493091', 'Esm Dailus Base Antifungica Livrai Me 1068', 'Com óleo de melaleuca na composição, que tem propriedades antissépticas e antifúngicas, a base também possui uma ação reconstrutora, ideal para unhas fracas, desidratadas e amareladas. A concentração é leve, o que permite o uso frequente. Com secagem rápida e acabamento brilhante, esse tem tudo para ser um queridinho na preparação das suas unhas. Modo de uso: Aplique uma camada antes do esmalte e as suas unhas estão protegidas. Para quem teme a coloração amarelada das unhas, vale usar a base para devolver a cor original. #html-body [data-pb-style="646BA657BB699"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA657BB6AE"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 22.49, 22.49, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbn5-lmg1yj1fo85n5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22692493091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14880299152', 'Halter 2kg PVC Emborrachado Rythmoon - Preto ( 01 unidade )', 'Halter fabricado em ferro cinzento com revestimento em borracha plastissol PVC. Com indicador de peso gravado no ferro garante que a peça não perca o numero de seu peso. Resistente à água, óleos, fungos, ataque químico, anti-chama, dielétrico e intemperismo,alem da maciez para manipulação. OBS.: Vendidos em Unidade ( 1 peça ). Este halteres dispensa o uso de barras, pois tem o design moderno que facilita a prática dos exercícios e pode ser usado em casa ou na academia. Ideal para quem quer trabalhar os membros superiores e prático para quem gosta de se exercitar a qualquer momento. Conteúdo da Embalagem: 01 un. Halter 2kg PVC Emborrachado Rythmoon Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 40.0, 40.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/34c9216047010597bc3ffba028789049', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F14880299152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593858125', 'Regata Feminina Alças Largas Marialícia Cinza', 'A Regata Feminina Alças Largas Marialícia é peça-chave para compor looks práticos e cheios de estilo para o dia a dia! Confeccionada em ribana, possui modelagem justa, valorizando a silhueta. O decote arredondado, as alças largas e a sua textura diferenciada proporcionam conforto e elegância para o visual, tornando o look a escolha ideal para diversas ocasiões: para um passeio, combine com shorts e rasteiras. Para um visual mais sofisticado, combine com saia e acessórios. Modelo veste P Medidas da modelo: 89cm de busto; 97cm de quadril; e 69cm de cintura', 84.9, 84.9, NULL, 'Women Clothes > Tops > Tanks & Camisoles', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mr1t443klgqpa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23593858125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
