INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599147376', 'Kit Amortecedor Dianteiro. Escort Xr3 2.0 1993 A 1996', 'Este anúncio contém os seguintes produtos: Par de amortecedores dianteiros, lado esquerdo e direito; Par de kits amortecedores dianteiros composto por: coxim, rolamento, batente e coifa. Fabricante dos amortecedores dianteiros: Monroe Fabricante dos kits dianteiros: Expedibor Produtos novos, com 2 anos de garantia para os amortecedores e 3 meses para os demais itens. Este produto se aplica a esses veículos: Veiculo: Escort; Motores: 1.6, 1.8, 2.0; Anos de fabricação: 1993, 1994, 1995, 1996; Veiculo: Escort Xr3; Motores: 2.0; Anos de fabricação: 1993, 1994, 1995, 1996; Veiculo: Verona; Motores: 1.6, 1.8, 2.0; Anos de fabricação: 1992, 1993, 1994, 1995, 1996; Veiculo: Logus; Motores: 1.8, 2.0; Anos de fabricação: 1993, 1994, 1995, 1996; Veiculo: Pointer; Motores: 1.8, 2.0; Anos de fabricação: 1994, 1995, 1996; Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há duas décadas, nosso estoque conta com uma variedade de aproximadamente 45.000 itens. Nossa equipe de Pós-Vendas é altamente capacitada, resultando na excelência no atendimento e na busca constante pela satisfação dos clientes. Navegue pela loja virtual e fique à vontade!', 891.0, 891.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-821f0-mgjlp1j3hqmjd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397705076%2F23599147376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799452751', 'KIT 6 PARES MEIA ESPORTIVA INVISÍVEL', 'O Kit com 6 Pares de Meias Esportivas Invisíveis da Mash é ideal para quem busca conforto, praticidade e discrição durante o dia a dia ou atividades físicas. Com modelagem invisível, as meias ficam discretas nos pés, sendo perfeitas para uso com tênis. Produzidas com materiais de alta qualidade, oferecem toque macio, boa respirabilidade e excelente ajuste, proporcionando mais conforto durante o uso. Atenção: este kit é enviado montado de fábrica conforme a composição de cores apresentada nas fotos do produto, não sendo possível realizar alterações. Características do Produto Ocasião de uso: Training Material: Misto Composição 69% algodão 29% poliamida 2% elastano Sobre a Mash Há mais de 50 anos presente no dia a dia do homem brasileiro, a Mash é referência em moda íntima masculina. A marca combina tradição, qualidade e design diferenciado, investindo constantemente em inovação, tecnologia têxtil e desenvolvimento de produtos que proporcionam conforto, durabilidade e estilo para todas as ocasiões.', 39.79, 39.79, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-820md-mnn6e0nwlywza0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764761342%2F22799452751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699841967', 'Protetor Solar Prata Parabrisa Dobrável | Proteção Prática Contra Sol e Conservar o Painel do Carro', 'PROTETOR SOLAR PRATA PARABRISA DOBRAVEL; O Para-Sol Luxcar é confeccionado com materiais de alta qualidade; foi desenvolvido para proteger o interior do seu carro; Protetor Solar para Caminhonetes, Pick-ups e Suvs; TAMANHO 1.40M X 70CM; Bem-vindo à Cornélio Autopeças no Shopee! Somos referência em autopeças, oferecendo produtos de alta qualidade para manter seu veículo em perfeito funcionamento. 🔧 O que você encontra aqui? Peças das melhores marcas para diversas montadoras e modelos Acessórios automotivos com o melhor custo-benefício Frete rápido e seguro para todo o Brasil Atendimento especializado para tirar suas dúvidas 👉 Acesse já e garanta os melhores produtos para o seu carro! 🚗💨 ITENS INCLUSOS: 1 Protetor Solar Parabrisa - 7195; DESCRIÇÃO: Para-Sol 1 unidade - 1,40 m x 70 cm O Para-Sol Luxcar é confeccionado com materiais de alta qualidade, foi desenvolvido para proteger o interior do seu carro, bloqueando até 90% dos raios solares. Possui superfície refletiva e tamanho universal, adaptável na maioria dos carros nacionais e importados. Vantagens: - Produto antitérmico - Bloqueia os raios solares em até 90%. - Protege o interior do veículo. - Fácil de guardar, dobrável. Modo de usar: 1.Desenrole os elásticos, desdobre e localize as ventosas que estão dentro das dobras do Para-Sol. 2.Encaixe a base das ventosas aos furos nos cantos do Para-Sol. 3.Fixe as ventosas na parte superior do seu para-brisa, de forma que o seu Para-Sol fique bem esticado. Validade Indeterminada. Especificações Técnicas: Para-Sol 1 unidade - 1,40 m x 70 cm DADOS TÉCNICOS: PROTETOR SOLAR PRATA PARABRISA DOBRAVEL; O Para-Sol Luxcar é confeccionado com materiais de alta qualidade; foi desenvolvido para proteger o interior do seu carro; TAMANHO 1.40M X 70CM; GARANTIA: 3 meses Não deixe seu carro esperando – compre agora na Shopee e garanta desempenho e durabilidade com a confiança Cornélio Autopeças! 🛒 Aproveite nossas ofertas e compre com segurança! Cornélio Autopeças – Qualidade que Move o Seu Veículo! 🚗💨', 48.9, 48.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Sun Shade', 'https://cf.shopee.com.br/file/sg-11134201-8261w-mmhl8fxzurybcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1556768667%2F19699841967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40862971325', 'Carabina de Pressão Rossi GásRam Dione 5G Polímero ou Madeira 5,5mm +300 Chumbinhos+01Luneta 4x20+01Capa+01Bandoleira', 'LOJA CORDILHEIRA SPORT! Carabina de Pressão Rossi Dione 5G 5,5mm Poímero ou Madeira + 300 Chumbinhos Fortis 5,5mm + 01 Luneta 4x20 + 01 Capa para carabina + 01 Bandoleira com Porta chumbinho + 01 Óleo de Silicone + 10 Alvos Rossi Descrição: Descubra a nova Dione 5G da Rossi, a carabina que vai revolucionar sua experiência de tiro! Com tecnologia avançada para evitar disparos acidentais e um gatilho ajustável para precisão total, você terá controle absoluto sobre cada tiro. Seu design robusto em metal e polímero oferece durabilidade e conforto, enquanto sua mira ajustável com fibra óptica garante precisão imbatível. Com uma velocidade incrível de até 245 m/s e uma energia poderosa de 23 joules, cada disparo será uma emoção única. Perfeita para tiros de precisão, impacto e diversão, a Dione 5G é a escolha definitiva para quem busca excelente desempenho e confiabilidade. CARACTERÍSTICAS: Marca - ROSSI Modelo - DIONE 5G GR MADEIRA Calibre - 5,5MM (.22) Modo de disparo - MANUAL MONOTIRO Tipo de ação - MOLA PNEUMÁTICA Engatilhamento - QUEBRA CANO Sistema antidisparo - POSSUI Regulagem de gatilho - POSSUI Munição utilizada - CHUMBINHO Velocidade máxima (m/s) - 245 M/S ou 803 FPS Peso munição referência velocidade (g) - 0,80 G Energia (joule) - 24,0 JOULE Peso do produto - 3080 G Comprimento do produto - 1158 MM Material do produto - METAL Cano (comprimento) - 480 MM Cano (acabamento) - METAL Capacidade de munição - MONOTIRO Trava de segurança - MANUAL Alça de mira - REGULAVEL Fibra óptica - ALÇA E MASSA DE MIRA Massa de mira - FIXA COM TÚNEL Coronha (material) - MADEIRA Coronha (acabamento) - RECARTILHADA Coronha (empunhadura) - AMBIDESTRA Coronha (