INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28229210345', 'Razão e Sensibilidade - Edição de Luxo Almofadada', '"Razão e Sensibilidade," de Jane Austen, conta a história das irmãs Elinor e Marianne Dashwood, que enfrentam as adversidades da vida após a morte de seu pai e a perda de sua herança. Elinor, a irmã mais velha, representa a razão e o autocontrole, enquanto Marianne personifica a sensibilidade e a paixão. Através de suas experiências amorosas e sociais, Austen explora os contrastes entre a racionalidade e a emoção, bem como as limitações impostas às mulheres na sociedade inglesa do século XIX. Esta edição de luxo da Série Ouro da Editora Garnier enriquece a leitura com suas bordas douradas, Capa Almofadada almofadada com hotstamping, e fitilho de seda, tornando-a um deleite visual e literário. DESCRIÇÃO Editora: Editora Garnier Edição: 1, 2025 Autor: Jane Austen Idioma: Português Páginas: 224 Dimensões:A 23 x L 15,1 x E 2 Encadernação: Capa Almofadada ISBN: 9786584956674', 69.0, 39.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-m7837l71ywyga9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F28229210345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997972184', 'Kit Pano De Boca Bordados Papi Prendedor Carros - 3 Peças', 'Kit Pano De Boca Bordados Papi Prendedor Carros - 3 Peças O Kit Pano de Boca Bordados Papi é um conjunto encantador e funcional, ideal para os cuidados diários com o seu bebê. Composto por 3 unidades, cada pano de boca é confeccionado em tecido 100% algodão, garantindo suavidade ao toque e conforto para a pele sensível do bebê. O viés de malha conta com um prático prendedor de chupeta, proporcionando praticidade e evitando que a chupeta se perca. O detalhe de faixa estampada e o bordado personalizado adicionam um toque charmoso e personalizado a cada peça. Além de sua função tradicional para higiene, os panos de boca podem ser utilizados como itens decorativos no enxoval do bebê. O prendedor de chupeta integrado é uma solução conveniente para manter a chupeta sempre à mão durante os passeios. Informações Adicionais:Tamanho: Único Cor: Azul Referência: 4928-3999 Medidas aproximadas: 40cm x 40cm Marca: Bordados Papi', 36.8, 36.8, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-m1ijs0t2jwdj92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22997972184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
