INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593896806', 'Halteres Emborrachado De 6kg á 10kg Peso Academia Dumbell Sextavado Para Treino Musculação', 'O Halter Sextavado Emborrachado MegaGym Equipamentos, é o halter ideal para o seu treino. Sendo o mesmo elaborado em ferro fundido e com revestimento em borracha, o halter sextavado se destaca por sua qualidade e resistência, pois sua borracha impede a sua oxidação, e ainda proporciona a sensação de antiderrapante que traz uma maior segurança ao seu treino e também um alto conforto. Além disto o seu formato anatômico garante que o seu treino seja mais efetivo e funcional e muito mais eficiente. Benefícios: — Promove uma Atividade Motora Complexa; — Equilíbrio Simetria da Força Muscular; — Definição de Músculos; — Aumento de Massa Muscular; — Melhora a Postura; — Melhora o condicionamento cardiorrespiratório; Características Do Produto: • Material Do Produto: Ferro Fundido; • Revestimento Do Produto: Borracha; • Modelo De Pegada: Anatômica; • Modelo Do Produto: Halter Sextavado Emborrachado; Item Incluso — 1 Unidade Halter Emborrachado; Exercícios: — Supino Reto com Halteres; — Supino Inclinado com Halteres; — Crucifixo Reto com Halteres; — Desenvolvimento com Halteres; — Elevação Lateral;', 211.59, 150.95, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m86lqkckxq1dcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867949056%2F22593896806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
