INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18836866890', 'Chinelo Masculino Spin Rider - 11772', 'O chinelo masculino Spin Rider é ideal para acomodar os pés e os deixar livres de incômodo. Esse modelo é feito com material sintético e borracha, os solados são emborrachados e as palmilhas oferecem o conforto necessário aos pés. Permita que esse modelo esteja presente em sua rotina, seus pés vão amar esse conforto.. MODELO: A3291772 REFERENCIA: 11772 MARCA: Rider GÊNERO: Male GRUPO DE IDADE: Adult MATERIAL DO SAPATO: Borracha/Sintético MATERIAL DA SOLA: Borracha ACABAMENTO: Vulcanizado MATERIAL DA PALMILHA: EVA', 90.99, 90.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/b105dae459f71632b4b0c8512663913a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F18836866890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798838485', 'Kit 2 Driver JBL D409TI 150W Rms 8 Ohms Titânio', 'O Driver JBL Selenium D409TI foi desenvolvido para entregar máxima eficiência nas médias e altas frequências, com diafragma em titânio que garante resposta estendida e som limpo. Sua tampa injetada em alumínio proporciona excelente dissipação de calor, além de acabamento premium com usinagem diamantada e envernizado. Este anúncio refere-se ao par de drivers (2 unidades), ideal para sonorização em caixas de reforço de som (PA) e trios elétricos, unindo potência, durabilidade e performance. CARACTERÍSTICAS: • Marca: JBL • Modelo: D409TI • Potência RMS: 150W cada (300W o par) • Impedância: 8 Ohms • Sensibilidade: 111 dB • Resposta de Frequência: 300 Hz – 16.000 Hz • Diafragma: Titânio • Garganta: 50 mm (2") – acoplamento em cornetas compatíveis • Diâmetro: 20 cm • Profundidade: 9,1 cm • Peso: 8,1 kg cada CONTEÚDO DA EMBALAGEM: • 02 Drivers JBL D409TI • 02 Manuais de instruções', 2558.99, 1949.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdw19bs82yo062', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F22798838485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22691814513', 'VISEIRA CRISTAL - THUNDER OPEN (2,00MM)', 'Viseira Polivisor injetada 2mm - Com tratamento resistente a risco. - Viseira compatível com capacetes do tamanho 56, 58 e 60 - Super resistente - Alta transparência - Alta durabilidade - Boa vedação e funcionalidade no capacete - Proteção contra raios UV Aplicação: Capacete EBF Thunder Open: Solid Classic Mandala Force X New Summer City Line New Shield New City Com mais de 20 anos de experiência no mercado a Polivisor é amaior fabricante de viseiras para capacetes no Brasil.Produzindo viseiras de alta qualidade, com investimentos constantesem tecnologia para o desenvolvimento de novo produtos. Instruções de uso: - Limpe somente com sabão neutro e água corrente - Não aplicar solvente químico, gasolina ou produtos abrasivos - Não aplicar vernizes ou adesivos - Troque sua viseira regularmente THUNDER OPEN ATE 2010 (2,00MM)', 47.11, 47.11, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugs53bwvh6452', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F22691814513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23102188212', 'Cremáscara Salon Line 2X1 S.O.S Cachos Nutritivo 1Kg', 'A Salon Line apresenta seu mais novo lançamento a Cremáscara 2x1 S.O.S Cachos Nutritivo, uma máscara de tratamento cosmético finalizadora 2 em 1, que além de ser uma máscara super nutritiva, funciona também como um incrível creme para pentear com alto poder de definição. Cremáscara Salon Line 2X1 S.O.S Cachos Nutritivo é tudo o que você queria para deixar seus cachos ainda mais lindos e cheios de vida. Sua poderosa fórmula possui a incrível ação reparadora da Proteína do Trigo, e alto poder nutritivo do Óleo de Moringa, que fortifica, hidrata e ajuda a recuperar os fios danificados. O resultado são cachos hidratados, nutridos e com um brilho maravilhoso. Aproveita que aqui você encontra só definição e hidratação. Modo de usar: Como Máscara: Com os cabelos limpos e úmidos, aplique a Cremáscara Salon Line 2X1 S.O.S Cachos Nutritivo mecha por mecha, massageando no sentido da raiz para as pontas. Deixe agir por 5 minutos. Enxágue. Como Creme Para Pentear: Após lavar os cabelos, retire o excesso de água e aplique a Cremáscara Salon Line 2X1 S.O.S Cachos Nutritivo mecha a mecha. Desembarace os fios com os dedos ou pente de dentes largos e, em seguida, retire o excesso de creme com uma toalha, amassando os fios de baixo para cima. Repita o movimento quantas vezes forem necessárias, irá auxiliar na formação dos cachos. Dica: Para cabelos ondulados, utilize apenas na extensão do fio e pontas. Não aplique a Cremáscara 2x1 próximo da raiz, pois poderá pesar. Sobre a marca: A Salon Line, uma das maiores fabricantes de cosméticos do Brasil, há mais de 15 anos acompanha a evolução da mulher brasileira. Toda essa vivência fez da empresa uma profunda conhecedora do universo feminino. A empresa está sempre investindo em novas tecnologias e produtos, para oferecer aos clientes, consumidores e profissionais da área o que há de melhor no segmento cosmético mundial. Empresa 100% Nacional, que tem como objetivo especializar-se na beleza das mulheres brasileiras. Sempre desenvolvendo produtos de alta tecnologia, a Salon Line faz do seu slogan a sua realidade: Valorizando todas as belezas.', 58.04, 58.04, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-82584-mqhx8jahhuz18d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23102188212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
