INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199197040', 'Engate Reboque Fixo I-30 2013 a 2017 700 Kg - Brucke HY1009', 'Engate Reboque Hyundai I-30 2013 a 2017 Fixo 700 Kg Marca: Brucke Modelo: HY1009 - Compatibilidade: Hyundai I-30 2013 Hyundai I-30 2014 Hyundai I-30 2015 Hyundai I-30 2016 Hyundai I-30 2017 O Engate Reboque para o Hyundai I-30 de 2013 a 2017 Fixo da marca Brucke é a solução ideal para quem busca robustez e confiabilidade. Com uma capacidade de reboque de até 700 Kg, este modelo com ponteira Fixo tem resistência testada e garantida, garantindo que você possa transportar cargas pesadas com segurança! É compatível com carretinhas, trailers, transbikes. - Atributos do Produto: Tipo de ponteira: Fixo Medidas: 26 x 43 x 92 cm, 11kg. Capacidade de reboque tração: Até 700 Kg Capacidade de peso sobre a bola: Até 40 kg Material: Fabricado em Aço carbono Pintura: Acabamento em pintura eletrostática a pó na cor preta Homologação: Produto homologado pelo INMETRO (012587/2022) e regularizado conforme a resolução nº 197 do Contran. Acompanha bola de engate, tomada e acabamento (quando necessário) como nas imagens. Código interno: 804 Instalação: Instalação simples nas furações originais do veículo, sem necessidade de furos ou adaptações. A instalação deve ser feita por um profissional.', 618.24, 556.42, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-8226t-mhjlz9s59a1015', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1625011375%2F23199197040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
