INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593396602', 'Adoçante Sucralose Culinário Linea 120g', 'Linea Adoçante Culinário Sucralose é um edulcorante derivado da cana-de-açúcar, 100% eliminado pelo organismo e pode ser consumido por toda a família. Para portadores de diabetes, não eleva o açúcar no sangue. Contém 4kcal por colher e possui 20x menos calorias que o açúcar. Mantém o poder de adoçante em altas temperaturas, é aerado na medida certa para entregar a maior redução calórica e a mesma facilidade de uso do açúcar nas receitas (1 xícara de Linea Adoçante Culinário = 1 xícara de açúcar). INGREDIENTES Maltodextrina, edulcorantes: sucralose e acesulfame de potássio. NÃO CONTÉM GLÚTEN.', 32.99, 31.34, NULL, 'Food & Beverages > Cooking Essentials > Sweetener', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meop86q9boxv6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23593396602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
