INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28029757827', 'Flamavet 0,2 Mg - C/10 Comprimidos - Gatos', 'Flamavet 0,2mg -C/10 Comprimidos O Anti-Inflamatório Agener União Flamavet para Gatos é um anti-inflamatório não esteroidal COX-2 seletivo e analgésico para gatos. Confere maior segurança no trato gastrointestinal e aos rins. Indicações: O Flamavet é o único Anti-Inflamatório não esteroidal (Aine) com apresentação exclusiva para gatos. Indicado para a analgesia pós cirúrgica, além de inflamações agudas decorrentes de contusões, traumas e para processos inflamatórios crônicos presentes principalmente nas osteoartroses de gatos e cães - Indicado para gatos; - Anti-inflamatório não esteroidal; - Ideal para o controle das dores pós-operatórias, feridas e lacerações cutâneas; - Comprimidos palatáveis, - A embalagem contém 10 comprimidos. Posologia: Gatos: 0,2 mg: 0,1 mg / kg / VO / no primeiro dia; após 0,05 mg / kg / VO / a cada 24 horas por até 21 dias*. Benefícios: - Altamente palatável; - Fácil administração; - Concede maior segurança no trato gastrointestinal do pet. Especificações: Pet: Gatos Uso: Oral Apresentação: Disponível em embalagem com 10 comprimidos Tipo: Anti-inflamatório, Analgésico e Antitérmico', 29.9, 19.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7rd6a-m7dswfrscvqh10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F28029757827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
