INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798032277', 'Pedal de Freio Gp7 Moto Honda Bros 150 2003 em Diante', 'PEDAL FREIO GP7 MOTO HONDA BROS 150 2003 Complete o conjunto de freio da sua moto com o Pedal de Freio GP. Trazendo ainda mais segurança durante a pilotagem. Esta é uma peça produzida em liga metálica inoxidável, ou seja, possui alta qualidade e excelente performance. Compatíve: - HONDA NXR 150 BROS - 2003 EM DIANTE Peças de excelente qualidade, e ótimo custo benefício. Ouse Sempre Com O Melhor Para A Sua Moto! >ATENÇÃO Garantia de 3 Meses. Imagens Meramente Ilustrativas. Recomendamos que a instalação seja feita por profissional especializado. Não nos responsabilizamos pelo mau uso ou aplicação do produto.', 133.76, 127.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6sgljvk4fhje2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F937893879%2F21798032277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
