INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299440778', 'Sapólio Radium Cremoso Cloro Bombril', 'Sapólio Radium Cremoso Cloro limpa e renova o brilho sem riscar, ideal para diversas superfícies como esmaltadas, cromadas, fórmicas e panelas. Com cloro ativo, oferece ação desengordurante e auxilia na remoção de manchas, além de branquear as superfícies. Ideal para uso em cozinhas (pia, cuba, torneira e balcão) e banheiros (louças sanitárias, box e banheira). Aplique com pano macio e úmido ou com o lado macio da esponja, esfregue e remova completamente.', 14.79, 14.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqnem5enhwy304', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555102%2F23299440778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
