INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992048112', 'Jogo Esponja Abrasiva Bosch EXPERT S471 69x26x97mm', 'A esponja abrasiva EXPERT S471 oferece manuseamento fácil no polimento manual de diversas áreas planas e bordas. Está disponível em cores diferentes para identificação das lixas que devem ser utilizadas nos passos de desbaste, preparação e polimento final. A forma de bloco da esponja dobra e adapta-se perfeitamente à peça trabalhada para remover material de forma eficaz. Pode ser lavada e reutilizada várias vezes e possui pontas de esponja fortes para lixar bordas. Além disso, é revestida nos quatro lados com grão abrasivo resistente à perda de grão. A esponja abrasiva EXPERT S471 é ideal para polimento em madeira e tinta. Conta com a tecnologia Surface Structure da Bosch e dura até 5 vezes mais que a lixa C420. É adequada para texturizar madeira, plástico e metal na preparação para a tinta e para o polimento intermediário de vernizes e tintas. Indicado para polimento manual. Garantia 6 meses Bosch.- Dura até 5 vezes mais que a lixa C420 da Bosch- Forte e flexível com a tecnologia Surface Structure da Bosch.- Manuseamento fácil para polimento manual de perfis- Cores diferentes para identificação das lixas para os passos de desbaste, reparação e polimento finalItens inclusos: 3 Esponjas Abrasivas EXPERT S471 69x26x97mm (Médio/ Fino/ Superfino)Especificações técnicas: - Dimensões em mm: 69x97x26- Grau: Médio/ Fino/ Superfino- Cor do produto: Laranja/ Amarelo/ Verde- Dura até 5 vezes mais que a lixa C420 da Bosch- Forte e flexível com a tecnologia Surface Structure da Bosch.- Manuseamento fácil para polimento manual de perfis- Cores diferentes para identificação das lixas para os passos de desbaste, reparação e polimento final', 41.77, 41.77, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvf4-lk8cp8kpovtedf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22992048112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399673600', 'Sandália Brizza Arezzo Thong Slim Marrocos Preto - Feminino', 'Estilo e conforto para todas as ocasiões! Sandália Brizza Arezzo Thong Slim Marrocos Preto - Feminino Ficha Técnica: Marca: Brizza Arezzo Cor: Preto Indicação: Dia a dia e momentos de lazer Gênero: Feminino Material: EVA com imitação de cordão torcido Fechamento: Fivela metálica lateral Palmilha: Preta com inscrição da marca Detalhes: Tiras finas delicadas que contornam o tornozelo e oferecem suporte exibindo todo o pé Quem nunca sofreu com sandálias desconfortáveis que deixam os pés cansados ao longo do dia? A Sandália Brizza Arezzo Thong Slim Marrocos foi desenvolvida para evitar esse problema. Por que investir nesse modelo? Seu design leve e minimalista permite liberdade total para os pés, enquanto as tiras ajustáveis garantem um encaixe seguro. Feita em EVA macio, proporciona bem-estar e suavidade em cada passo. O modelo ideal para quem quer conforto sem abrir mão do estilo. Conteúdo da embalagem: 1 par de Sandália Brizza Arezzo Thong Slim Marrocos Preto - Feminino', 159.99, 124.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7req9-m85gqli172qvc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F20399673600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52505411716', 'Tênis Actvitta Gaspea Knit Energy Bege - Feminino', 'Mais energia, leveza e estilo para a sua rotina! Tênis Actvitta Gaspea Knit Energy Bege - Feminino Parte superior do formulário Ficha Técnica: Marca: Actvitta Cor: Bege Gênero: Feminino Indicado: Academia e caminhada Cabedal: Têxtil respirável com estrutura reforçada Palmilha: EVA com forro têxtil macio Sola: EVA leve com amortecimento Altura da Sola Robusta: 5 cm Lingueta: Fina e integrada com puxador para facilitar o calce Fechamento: Cadarço Amortecimento: Leve Estabilidade: Neutro Tecnologias: Estrutura respirável e solado em EVA de alta absorção de impacto Entressola: EVA expandido e texturizado, para conforto durante o uso prolongado Detalhes: Design com o nome da marca na lateral, puxador traseiro, modelo moderno e respirável Combinando conforto, estilo e praticidade, o Tênis Actvitta Gaspea Knit Energy foi feito para mulheres que vivem em movimento. Porque investir: Seu cabedal têxtil com estrutura reforçada garante respirabilidade e durabilidade, enquanto a entressola de EVA texturizado proporciona leve amortecimento com sensação de suavidade a cada passo. O design moderno e o nome da marca na lateral, além do puxador traseiro que facilita o calce. Ideal para treinos leves, caminhadas ou um dia cheio na cidade. Conteúdo da embalagem: 1 par de Tênis Actvitta Gaspea Knit Energy Bege - FemininoParte superior do formulárioParte superior do formulário Parte superior do formulário', 249.99, 149.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82628-mku9qyl8jif5cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F52505411716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255471541', 'Tênis Kolosh Upper Feminino C1404B', 'Produto marca Kolosh. O Tênis Kolosh Upper é a escolha definitiva para mulheres que não abrem mão de estar na moda sem perder a praticidade. Com um design que une tendência e versatilidade, este modelo destaca-se pelo mix de materiais e recortes diferenciados, criando um jogo de cores sofisticado e feminino. Os detalhes metalizados, como o pin lateral e os ilhoses brilhantes, conferem um toque de glow e elegância, transformando qualquer look casual em uma produção cheia de estilo para o dia a dia ou momentos de lazer. Desenvolvido para acompanhar o ritmo da mulher moderna, o Kolosh Upper conta com o sistema de Calce Fácil, utilizando elásticos sobre o pé que garantem um ajuste perfeito e agilidade na rotina, além de ser leve, pesando 0,636 kg. a experiência de bem-estar é elevada pela Palmilha K-soft, produzida com espuma triturada sustentável que se adapta ao formato do pé, somada aos microfuros laterais que asseguram a respirabilidade necessária para manter seus pés frescos e secos durante todo o uso. Sinta a sensação de caminhar nas nuvens com a exclusiva sola Upper em EVAfit de 3 cm na parte frontal. Esta tecnologia de ponta oferece uma extrema leveza e alta absorção de impactos, protegendo suas articulações a cada pisada. Com um salto de 5,55 cm que proporciona aquela altura desejada com total estabilidade, este tênis é o investimento inteligente para quem busca durabilidade, conforto superior e um visual impecável em uma única peça. Peso: 0,636 kg Altura da sola: 5,55 cm Altura do salto: 3,0 cm', 298.9, 259.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82608-mkwuqzhpngg39d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58255471541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13278359185', 'Jogo de Pontas Para Aparafusar e Chaves de Catraca 27 Peças - BOSCH', 'Os Kits de Pontas e Soquetes Bosch Extra Hard são ideais para aplicações universais de parafusamento e fixação. As Pontas e Soquetes são fabricados com aço de alta qualidade com processo de tratamento térmico que traz alta resistência e permite um alto desempenho nas aplicações. A zona de torção cônica das pontas absorve a força e vibração durante as aplicações executando todos os parafusamentos com facilidade. O portfólio Bosch Extra Hard é completo e possui Pontas Philips (PH), Pozidriv (PZ), Torx (T), Fenda (S) e soquetes em diferentes diâmetros com encaixe hexagonal 1/4". São indicados para utilização em furadeiras e parafusadeiras. Características: - Ideais para diferentes aplicações de parafusamento e fixação - Alto desempenho nas aplicações - Mais desempenho para sua ferramenta. Acessórios Profissionais Bosch. - Kit com grande variedade de pontas e soquetes para diversas aplicações de parafusamento e fixação - A zona de torção cônica das pontas absorve a força e vibração durante as aplicações executando todos os parafusamentos com facilidade - Encaixe hexagonal de 1/4" compatível com furadeiras e parafusadeiras Componentes: - 19 pontas 25mm: PH1, 2x PH2, PH3, PZ1, PZ2, PZ3, S4, S5, S6, T10, T15, T20, T25, T30, HEX Ø3/4/5/6mm - 5 Soquetes Sextavados Ø6/7/8/10/13mm - 1 adaptador universal magnético - 1 adaptador para soquetes - 1 chave de catraca.', 141.13, 141.13, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134201-820lt-mqx971g5rtok4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F13278359185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494846222', 'Bota Dakota de Cano Curto Feminina D2184', 'Produto marca Dakota. A Bota Dakota de Cano Curto é o equilíbrio perfeito entre a sofisticação urbana e o conforto indispensável para o seu dia a dia. Com um design monocolor, ela se destaca pelo acabamento em matelassê, uma tendência atemporal que confere um volume moderno e textura exclusiva ao material sintético de alta qualidade. o salto baixo de 2,80 cm oferece a estabilidade necessária para quem não para, garantindo que você transite do trabalho ao lazer com a confiança de quem está impecável. Sinta a praticidade do fechamento em zíper lateral, desenhado para um calce rápido e ajuste seguro no tornozelo. Mais do que um calçado, esta bota é um investimento no seu estilo de vida, adaptando-se facilmente a looks casuais com jeans ou composições mais elaboradas com vestidos e meias calças. o solado em TR proporciona aderência e durabilidade, enquanto a leveza do modelo evita o cansaço excessivo, permitindo que você aproveite cada momento com máxima elegância. Eleve seu guarda-roupa com um item versátil que une a estética despojada ao toque clássico do cano curto de 15 cm de altura e 19 cm de circunferência. Seja para encarar a rotina produtiva ou para um passeio relaxante no fim de semana, a Dakota entrega a resistência que você precisa e o visual que você deseja, além de ser leve, pesando 0,704 kg. Garanta uma peça-chave que traduz personalidade em cada passo e não abra mão do bem-estar que só uma marca especialista em moda feminina pode oferecer. Peso: 0,704 kg Altura da sola: 2,80 cm Altura do cano: 15,0 cm Circunferência do cano: 19,0 cm', 229.9, 199.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-82610-mkwuuuqzqo7852', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23494846222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398739142', 'Caixa Sanfonada Para Ferramentas com 7 Gavetas - Tramontina', 'A Caixa Sanfonada para Ferramentas Tramontina com 7 gavetas e Alças Fixas possui pintura eletrostática, garantindo um acabamento excelente e maior resistência à corrosão. A pintura forma uma película protetiva tornando o produto ainda mais durável. Devido a sua construção, ela é muito prática e de fácil movimentação. Além disso, proporciona o armazenamento e transporte de ferramentas manuais, peças e acessórios. Com a Tramontina, suas ferramentas ficarão no lugar certo! - Estrutura em chapas de aço conformadas. - Possibilita o uso de cadeado. - Possui sete gavetas. - Alças fixas na parte superior. - Pintura eletrostática. Especificações técnicas: - Código de fábrica: 43800/007 - Dimensões CxLxA: 50,2 19,6 x 27cm - Peso: 5,340 Kg - Estrutura em chapas de aço conformadas. - Possibilita o uso de cadeado. - Possui sete gavetas. - Alças fixas na parte superior. - Pintura eletrostática.', 230.5, 230.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvg8-ljd4jjgnu01t48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F18398739142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698033472', 'Sandália Mississipi de Salto Bloco Metalizada MC263', 'Produto marca Mississipi. Deslumbrante e versátil, a Sandália Mississipi de Salto Bloco da coleção Primavera/Verão 2024 é a peça-chave que faltava no seu closet e está disponível nas cor bronze. Com design moderno e atemporal, ela combina perfeitamente com diversas ocasiões, do trabalho à balada. o salto bloco de 7cm proporciona conforto e elegância, enquanto as tiras finas e delicadas envolvem seus pés com leveza e sofisticação. Já os detalhes em brilho e a textura sofisticada adicionam um toque de glamour e feminilidade, tornando-a a escolha perfeita para mulheres que buscam um visual impecável. Sinta-se segura e confiante com o fechamento em fivela que garante um ajuste perfeito e personalizado. Seja para um evento especial ou para o dia a dia, essa sandália irá te acompanhar com estilo e conforto. Invista em um calçado que alia moda e qualidade e transforme seus looks em momentos inesquecíveis. Peso: 0,681 kg Altura da sola: 7,00 cm', 159.9, 149.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-82620-mlwg7p371yis5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23698033472', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
