INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997672555', 'Kit Suporte De Prateleira - Cantoneira - 30 X 35 Cm 47,0005 (Com 2 Unidades) - Nord', 'O Kit Suporte De Prateleira - Cantoneira - 30 X 35 Cm 47,0005 (Com 2 Unidades) - Nord, é um conjunto específicos para sustentar prateleiras em paredes. Transforme seu ambiente com um toque de organização e praticidade com o Kit Suporte de Prateleira Cantoneira. Ideal para quem busca uma solução robusta e elegante para instalar prateleiras de forma segura e eficiente, este kit é perfeito para qualquer ambiente, desde salas de estar e cozinhas até escritórios e armários. - Especificações Técnicas: • Especificação: 12''''x 14'''' / 10x12,5 cm • Espessura: 0,8 - 0,9 mm • Largura: 45 mm • Profun. Vinco: 20 mm • Capacidade de Carga (por par): 40 kg • Acabamento: Pintura Branca (epóxil) • Contém 2 Unidades. Referência: 47,0005. Marca: Nord.', 17.06, 17.06, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/br-11134201-820ll-mqy708jjadxh25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23997672555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192523591', 'Cabo micro USB Nylon Preto 1,5m EUAB15NP Intelbras', 'Cabo micro USB Nylon Preto 1,5m EUAB15NP - Intelbras O cabo USB para Micro USB EUAB 15NP permite a conexão de seus dispositivos para alimentação de energia e transferência de dados. Projetado e testado para garantir o melhor desempenho e durabilidade, tem 1,5 m de comprimento para oferecer maior comodidade no uso com smartphones, tablets, computadores, fones de ouvido sem fio, controles de videogame e outros dispositivos compatíveis. O revestimento em nylon trançado garante maior resistência diante das exigências do dia a dia. Detalhes: - Conector 1: USB Type-A - Conector 2: USB Micro-B - Bitola do cabo: 24AWG energia / 30AWG dados - Corrente máxima: 3,0 A - Velocidade de transferência de dados: até 480 Mbps (em conformidade com o padrão USB 2.0) - Revestimento externo do cabo: nylon trançado - Capa dos conectores: alumínio - Dimensão: 3,4 × 1.500 mm', 32.28, 32.28, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-lmnnz96zp2cjab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22192523591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205157646', 'Eudora Siàge Volume Imediato Máscara Capilar 250g', 'A Máscara Capilar Siàge Volume Imediato oferece uma reconstrução profunda para cabelos fragilizados pelo afinamento. Ela atua na reposição de massa capilar, recuperando a densidade perdida devido a agressões externas ou procedimentos químicos, garantindo um visual mais volumoso. Conheça as características desse produto que vão fazer você se apaixonar: • Reduz a quebra dos fios em 10x; • Deixa os cabelos 10x mais macios; • Recupera 83% do afinamento causado por stress capilar. Sua fórmula rica em Filler System e Arginina promove fios mais encorpados e cheios, entregando tratamento de salão sem pesar no resultado final. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 73.99, 73.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260u-mkmtiebp2ltydf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58205157646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997983507', 'Facão Para Mato Com Cabo Preto em Polipropileno 10'''' (26600/110) - Tramontina', 'O Facão Para Mato Com Cabo Preto em Polipropileno 10'''' (26600/110) - Tramontina, foi desenvolvido para o corte de mato e capim, ele lhe garante maior resistência e poder de corte, pois possui lâmina em aço carbono com tratamento térmico e revestimento protetivo de verniz. Seu cabo é em polipropileno com formato ergonômico e rebites de alumínio, características que juntas, o tornam um item robusto e de manuseio muito mais confortável e seguro. Descrição do Produto: • Lâmina de aço carbono com tratamento térmico especial que proporciona maior dureza, resistência do fio e maior poder de corte. • Lâmina com aplicação de uma camada de verniz como revestimento protetivo, a qual possui a função de proteção durante as etapas de transporte, armazenamento e primeiros usos. • Cabo de polipropileno rebitado que garante maior segurança, ergonomia perfeita e conforto no manuseio. • Lâmina com espessura de 2mm. Referência: 26600/110. Cód. de Fábrica: 26600/110. Marca: Tramontina.', 30.28, 30.28, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reox-m2cfnm90l8df39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F21997983507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
