INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19333161493', 'Verniz Premium Filtro Solar Brilhante Gl 3,6L Tripla Proteção - Suvinil', 'Nome : Verniz Premium Filtro Solar Brilhante 3,6L Tripla Proteção Suvinil Marca: Suvinil Modelo: Verniz Tripla Proteção Tipo: Verniz Volume: 3,6L Rendimento Acabado: 18m² Acabamento: Brilhante Superficie: Madeira Antimofo: Não Base: Solvente Aerosol: Não Ambiente: Interno e Externo Verniz Suvinil Proteção Tripla Brilhante Base Solvente deixa as superfícies resistentes a maresia, sol e chuva. Verniz para proteger madeira de dentro e fora de casa. Não importa o ambiente, o Suvinil Verniz Tripla Proteção protege a madeira com pigmentos, resinas e aditivos que protegem contra umidade da maresia e chuva e radiação solar. Três camadas de proteção para garantir o bom acabamento da sua casa. Benefícios Sua maderia linda e protegida Tripla Proteção UV Proteção contra sol, chuva e maresia 5 anos de garantia depois de pintar Demãos 2 a 3 demãos Acabamento Brilhante Diluição 10% com solvente Secagem Ao toque: 4 a 6 horas Entre demãos: 12 horas Final: 24 horas Marca Suvinil Dimensões 3.6 L: 16.8cm x 18.8cm x 16.8cm Peso 3.6 L: 3.312kg', 227.61, 225.34, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rcel-m6ckj5yfxd944e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F19333161493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099130495', 'Lixeira Pedal 12l Inox Reforçada Balde Removível Tramontina Loop', 'Lixeira Tramontina Loop Inox com Pedal — 5 L / 12 L Qualidade Tramontina Muito Resistente e Durável ! Ao pegar no material sente a diferenca de qualidade para as que existem no mercado , Inox de Alta qualidade e Muito mais resistente a amassados. Elegância, resistência e praticidade em um só produto. A Lixeira Tramontina Loop com Pedal une design moderno, durabilidade e higiene para manter qualquer ambiente limpo e organizado. Fabricada em aço inox AISI 430 com acabamento polido, oferece visual sofisticado e fácil limpeza, ideal para cozinhas, banheiros, lavabos e escritórios. Com balde interno removível, o descarte e a higienização se tornam mais práticos. O sistema de abertura por pedal evita o contato manual com a tampa, garantindo mais higiene no dia a dia. Além disso, a tampa com fechamento suave (soft close) evita ruídos e impactos, enquanto a base antiderrapante protege o piso e dá estabilidade. Disponível em versões de 5 litros (compacta) e 12 litros (média), adapta-se perfeitamente a qualquer espaço. ✅ Diferenciais: Estrutura em aço inox AISI 430 com espessura reforçada Tampa soft close: fechamento suave e silencioso Abertura por pedal: mais higiene e praticidade Balde interno removível com alça (em PP) Base plástica antiderrapante que protege o piso Acabamento polido, fácil de limpar e resistente à oxidação 📏 Especificações Técnicas: CapacidadeAlturaLarguraProfundidadePeso aproximado5 L33,1 cm18,6 cm18,6 cm1,2 kg12 L37,2 cm24,8 cm24,8 cm— Material: Aço Inox AISI 430 / Balde interno em PP Cor: Inox Polido Origem: Importado sob controle de qualidade Tramontina Garantia: 12 meses contra defeitos de fabricação 💡 Ideal para quem busca: Sofisticação e higiene em ambientes internos Praticidade na limpeza e descarte de resíduos Design moderno com a qualidade reconhecida da Tramontina', 199.9, 179.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-82588-mgchxrpwqkuie9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F23099130495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
