INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22827785856', 'Kit 6 Potes Creme De Massagem Corporal Dagua Natural Neutro 650g Sem Perfume Hidratação', 'Kit contendo 6 unidades do Creme de Massagem Neutro Dagua Natural 650g Desenvolvido para facilitar os movimentos da massagem, oferece um excelente deslizamento e maciez à pele. Produto neutro por não conter ativos e nem fragrância, este creme oferece também a possibilidade de se adicionar óleos essenciais, perfumes e outros componentes, conforme a preferência ou a necessidade de cada cliente. Com ação desodorante. Ativos: Sem ativos e sem perfume Modo de usar: Utilizar quantidade suficiente e aplicar nas regiões desejadas, com movimentos indicados para cada tipo de massagem. Precauções / cuidados: Em caso de irritação, suspender o uso imediatamente e procurar orientação médica. O produto não deve ser utilizado por pessoas hipersensíveis a qualquer componente da fórmula. Não aplicar se a pele estiver irritada ou lesionada. Manter ao abrigo da luz e calor excessivos. Manter fora do alcance de crianças. Uso externo. Validade: 36 meses Composição: Aqua, Paraffinum Liquidum, Cetearyl / Sodium Lauryl Sulfate, Propylene Glycol, Imidazolidinyl Urea, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Methylparaben, Propylparaben, Sodium Hydroxide, Triclosan, BHT, Disodium EDTA. Anvisa: 25351140829/2011-56', 362.45, 329.9, NULL, 'Beauty > Bath & Body Care > Massage Oil', 'https://cf.shopee.com.br/file/sg-11134201-23020-gp2vasm812nv21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F959567682%2F22827785856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
