INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394294066', 'Escapamento Cb 450 Modelo Original Fortuna- Moto Honda (par)', 'HB Moto Peças e Acessórios é a loja online de produtos da Fortuna, produtos de qualidade e melhor preço do mercado. ATENÇÃO! COMPATÍVEL APENAS COM AS MOTOS: Moto Honda CB 450. COMPATÍVEL APENAS COM OS ANOS: 1965 a 1990 O produto é Pronto para Instalação conforme o modelo da Moto, e encaixa-se Perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação. ACOMPANHA O ITEM: 1 — PAR de Ponteiras Honda CB 450 Modelo Original Fortuna. DESCRIÇÃO DO PRODUTO: MARCA: Fortuna. CÓDIGO: AF08 COR: Cromado MATERIAL: Aço Carbono MODELO: Original LINHA: Honda. CONDIÇÕES: Novo . Cliente em primeiro lugar! . Produto de Alta Qualidade e Ótimo Custo Benefício. . Compra 100% segura e Garantida! . Produto disponível para envio! A Fortuna Escapamentos é uma empresa que trabalha com o que há de melhor e mais moderno no segmento de escapamento e acessórios para motos. Produtos inovadores, qualidade, tecnologia e segurança. Estamos preparados para o melhor atendimento…', 399.99, 380.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rdww-md268b0r8wyu9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229024585%2F22394294066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
