INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697547592', 'Fita Dupla Face Adere Fita Forte XT100 Transparente 9mm x 20m', 'Características Principais: Marca: Adere Cor: Transparente Material: Polietileno Largura: 9mm Tamanho: 20m Informações Adicionais: Espessura: 1,0 mm ± 0,10 mm Densidade da espuma: 990 kg/m³ Liner de proteção: Polietileno Verde Temperatura mínima de aplicação: 15ºC Temperatura de trabalho: -10 a 90ºC Aplicações: Ideal para superfícies como vidros, acrílicos, paredes, madeiras, metais e revestimentos (porcelanato e azulejo). Não indicada para colagem de espelhos. Instruções de uso: Confirmar que o objeto não tenha saliências que impeçam o contato total da fita com a superfície. Aguardar 24 horas após a aplicação para que o adesivo atinja a eficiência desejada, utilizando um calço se possível. Evitar o uso em superfícies irregulares, porosas, úmidas ou contaminadas (pó, graxa, óleo, cera, etc.), com pintura recente ou que se desprendam facilmente (reboco soltando, pintura descascando ou papel de parede). Não usar para pendurar prateleiras ou colar uma fita sobre a outra para aumentar a espessura. Fornecedor: Adere', 34.66, 34.66, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-824im-mpiadrpgl3b591', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23697547592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
