INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200862673', 'Carrinho Maisto Volvo Carregadeira L25H 15364B', 'Detalhes do Produto: Réplicas detalhadas de tratores e modelos Volvo, com acabamento realista e estrutura resistente. Ideais para colecionar ou brincar com estilo e autenticidade. Perfeitas para colecionar ou brincar, as miniaturas agrícolas e de construção trazem o realismo das grandes máquinas em tamanho reduzido. Produzidas em metal e plásticos de alta qualidade, possuem acabamento detalhado, sistema de roda livre e design fiel, garantindo durabilidade e diversão segura para crianças acima de 3 anos. Com fabricação por molde de injeção, cada modelo conta com estrutura robusta e pintura realista, representando tratores, escavadeiras e carregadeiras com perfeição. Ideais para estimular a imaginação e o interesse por veículos e máquinas, são peças que unem resistência, beleza e alto valor colecionável. Características Principais do Produto: Marca: Maisto Cor: Amarelo EAN: 90159057574 Informações Adicionais: Escala Compacta, Réplica Detalhada Feita em Metal e Plásticos Resistentes (ABS, GP, PP, PVC) Sistema de Roda Livre para Movimentos Realistas Fabricada por Molde por Injeção com Acabamento Preciso Idade Recomendada: A Partir de 3 Anos (Não Indicado para Menores por Conter Peças Pequenas) Dimensões da embalagem: Comprimento 10,8 Altura 10,8 Dimensões do produto: Comprimento 7,3 cm Largura 2,75 cm Altura 3,75 cm Fornecedor: May Cheong Toy Pr Fty.Ltd &&Mm', 32.5, 32.5, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/sg-11134201-824i0-mpia7ymvn9qmf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F58200862673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
