INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693128149', 'Serra Tico-Tico GST 750 Bosch 520W Profissional', 'Serra tico tico GST 750 520W Bosch Vantagens: - A serra tico tico Bosch GST 750 possui motor eficiente de 520W que oferece maior capacidade de corte. Tem mais precisão e 4 níveis de velocidade pendular, além de seleção de até 6 níveis de velocidade para trabalho com diferentes tipos de materiais; - A serra corta facilmente madeira, metal e outros materiais; ela pode cortar curvas e formas redondas com a mesma facilidade que linhas retas; - O seu design robusto conta com proteção anti-lascas, punho ergonômico com borracha para mais conforto do usuário, base de alumínio para mais resistência, sapata para proteção da peça de corte e encaixe de lâmina SDS; - Equipada com uma saída para extração de pó integrada e adaptabilidade com aspiradores de pó; - Uso com 12 meses de garantia Bosch. Características: - Equipamento Bosch Professional; - Tipo de embalagem: Caixa de papelão; - Uso indicado: Madeira; - Acabamento da ferramenta: Poliamida, metal e elastômero; - Acabamento do cabo: Borracha e cobre; - Possui velocidade variável (6 vel.); - Não possui controle de torque; - Público Alvo: Instaladores (cozinha armário, pavimentação), Carpinteiros, Madeireiro, Marceneiro, Eletricista, Renovadores, Decorador de interiores. Dados Técnicos: - Tensão: 110V ou 220V (não é bivolt); - Potência da ferramenta: 520 W; - Serra, comprimento do curso: 20 mm; - Nº de cursos em vazio: 800 – 3.200 c.p.m; - Ângulo mínimo e máximo de corte: 0-45º; - Comprimento do cabo: 2 m; - Dimensões do produto (AxLxP): 26,4 x 21,35 x 7,5 cm; - Peso: 2,3 Kg. Profundidade de corte: - Profundidade de corte em madeira: 75 mm; - Profundidade de corte em alumínio: 15 mm; - Profundidade de corte em aço: 15 mm; - Profundidade de corte em aço não ligado: 15 mm. Valores totais de vibração (Serrar madeira): - Valor de emissão de vibrações ah: 6,7 m/s²; - Incerteza K: 1,5 m/s². Valores totais de vibração (Serrar chapa de metal): - Valor de emissão de vibrações ah: 4,7 m/s²; - Incerteza K: 1,5 m/s². Informações sobre ruídos/vibrações: - Nível de pressão sonora: 87 dB(A); - Nível de potência sonora: 95 dB(A); - Incerteza K: 5 dB. Componentes incluídos na embalagem: - 1 Serra tico tico GST 750; - 1 lâmina para corte em madeira T 111C; - 1 sapata; - 1 proteção de farpas; - 1x proteção contra pó.', 969.0, 678.3, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxcy3h0uprr32b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F23693128149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
