INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7190954656', 'Martelo Bola 300g MTX com Cabo de Fibra de Vidro', 'Martelo Bola 300g Cabo De Fibra Mtx Descrição: - Cabeça da ferramenta é polida e com as extremidades lixadas e é firmemente fixado ao cabo por meio de um adesivo epóxi especial. É realizado o endurecimento seletivo, o que fornece força e impede a deformação das suas faces. O cabo de fibra de vidro com emborrachamento confere firmeza e conforto na utilização do produto. Dados Técnicos: - Peso do martelo: 300g - Comprimento total aproximado do martelo (cabeça + cabo): 325,0 mm - Material do cabo do martelo: Fibra - Material da cabeça do martelo: Aço forjado - Acabamento da cabeça do martelo: Polido Acompanha: - 1 unidade: Martelo bola 300g Cabo de Fibra MTX', 57.0, 38.19, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcweophjj4fm32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F7190954656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
