INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13309121106', 'Kit 4 Desodorantes Rexona Motionsense Antitranspirante Aerossol Powder Dry 150ml', 'O Kit contém: 4 Desodorantes Antitranspirantes Rexona Feminino Powder Dry com 150ml cada. • O Desodorante Aerosol Feminino Rexona Powder Dry possui nova fórmula com 72 horas de proteção contra a transpiração e o mau odor, ativada pelo movimento • Sua fórmula não contém álcool etílico e a fragrância desse antitranspirante contém uma combinação única de jasmim e baunilha, garantindo a sensação de frescor durante o dia inteiro • Agite antes de usar. Aplicar o Desodorante Feminino Rexona Powder Dry somente nas axilas a não menos de 15 cm da pele • O novo desodorante feminino Rexona responde diretamente ao seu movimento, mantendo você seca, fresca e protegida como nunca • Este desodorante aerosol não afeta a camada de ozônio, possui lata em alumínio 100% reciclável e é feito com energia elétrica 100% renovável • Antitranspirante aerosol que mantém você seca, fresca e protegida a cada novo movimento e por muito mais tempo. Rexona não te abandona', 98.02, 98.02, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rced-lt5dbxn8loes75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F13309121106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198582094', 'Kit 4 Pneus 265/70R16 112H Forza HT F1', 'Pneu Forza HT F1 – Segurança, Conforto e Desempenho para Estradas O Forza HT F1 foi projetado para oferecer segurança excepcional, aderência superior e estabilidade incomparável em qualquer condição de estrada. Com alta durabilidade e um rodar suave, é a escolha ideal para quem busca eficiência e conforto ao dirigir. -Excelente aderência em pistas secas e molhadas. -Condução confortável e silenciosa, ideal para viagens longas. -Menor risco de aquaplanagem, proporcionando mais segurança em dias chuvosos. -Alta durabilidade, garantindo maior vida útil do pneu. Kit 4 Pneus 265/70R16 112H Forza HT F1 Marca: Xbri Modelo: Forza HT F1 Aro: 16 Índice de peso (por pneu): 112 - 1120kg Índice de velocidade: H - 210km/h Construção: Radial Tipo: Uso sem câmara Aplicação: Vias pavimentadas Tipo de desenho: Simétrico Lateral: Letras pretas Se você valoriza qualidade e desempenho ao dirigir, o Forza HT F1 é a escolha perfeita!', 3047.64, 3047.64, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7ravl-mass6qwiuzpsb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F23198582094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45201775750', 'Tênis Infantil Casual Star Fox Calce Fácil Elastico e Ziper 750', 'Sapatênis Infantil Star Fox – Conforto, Autonomia e Estilo para o Dia a Dia das Crianças O Sapatênis Infantil Star Fox foi desenvolvido para oferecer o equilíbrio perfeito entre conforto, praticidade e segurança. Pensado para facilitar a rotina das crianças, o modelo conta com fechamento em zíper lateral e ajuste em elástico, permitindo que elas calcem o tênis sozinhas com mais autonomia, confiança e satisfação. Seu cabedal em material vegano e o forro em cacharrel espumado proporcionam maciez, proteção e mantêm os pés na temperatura ideal durante todo o dia. O design versátil conta com opções de cores neutras — preto e café — perfeitas para a escola e para o dia a dia, além de versões coloridas que garantem um visual moderno e descontraído para passeios, festas e momentos de diversão. O solado em TR emborrachado oferece excelente aderência a diferentes tipos de piso, garantindo pisada firme, segurança e estabilidade em cada passo. Combina perfeitamente com bermudas, calça jeans e camisetas básicas, criando looks confortáveis e estilosos para qualquer ocasião. Nossos produtos são fabricados com tecnologia de ponta, passando por rigorosos processos de seleção de materiais, acabamento e testes de resistência. Cada detalhe é pensado para entregar durabilidade, qualidade e conforto, sempre respeitando critérios ambientais e de segurança. Especificações Técnicas Material do Cabedal: Sintético (vegano) Acabamento: Fosco Material Interno: Têxtil (forro em cacharrel espumado) Solado: TR bicolor emborrachado Palmilha: EVA', 89.9, 64.73, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81zu4-mkmfhszfbgn4ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F294355829%2F45201775750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899298119', 'Cômoda Infantil Aconchego 2 Gavetas', 'Descrição: O(a) Cômoda Infantil Aconchego 2 Gavetas Branco - Completa Móveis é produzido em MDP na escala de brilho Fosco, e possui um grau de dificuldade de montagem: Médio. Seu revestimento/acabamento é: Finish Foil. Infelizmente a Loja não oferece serviço de montagem, deixamos essa informação bem clara em todas as nossas páginas de produto. Onde especificamos que os móveis chegarão desmontados, e que a montagem fica por conta do cliente. Como não oferecemos esse serviço não embutimos o mesmo no preço dos produtos, ou seja, maior economia para você! Todos os nossos móveis também acompanham o manual de montagem, e caso você queira, pode realizar a montagem você mesmo, sempre especificamos os graus de montagem dos produtos. Nos casos de grau baixo e médio, com pouco ou nenhum conhecimento, você mesmo pode efetuar a montagem, e fazer essa economia. Apenas nos graus de montagem alto, recomendamos a contratação de um montador com experiência, visto que são montagens mais complicadas. A montagem é feita com Parafusos, Cavilhas e Minifix. Este móvel é indicado para que seja utilizado no(a) Quarto, dando um toque especial no cômodo de sua casa. Para que você mantenha seu produto sempre em ótimo estado, recomendamos que use apenas um pano seco ou levemente umedecido, sem o uso de quaisquer produtos abrasivos. A Loja garante aos clientes, 90 dias de garantia nos produtos, porém, recomendamos que entre em contato com o fornecedor/marca do produto, pois o mesmo(a), pode garantir um prazo maior de garantia. Lembrando ainda que: quaisquer objetos decorativos que aparecem nas imagens, não acompanham o produto. Características: - Peso Suportado nos Nichos: 5 - Acompanha Manual de Montagem: Sim - Possui Pés?: Não - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - É frágil?: Sim - Possui Ripamento?: Não - Possui Borda de PVC nas Bordas?: Não - Possui Nicho?: Não - Material do Puxador: Plástico - Pés com regulagem de altura?: Não - Montagem Invertida?: Não Pode ser Montado Invertido - Peso Suportado nas Gavetas (kg): 3 - Material das Corrediças: Metálica - Quantidade de Puxadores: 2 - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Necessita de Montagem: Sim - Sistema de Montagem: Parafusos, Cavilhas e Minifix - Indicação de Uso: Quarto - Acompanha: Kit Ferragem + Manual - Possui Sapatas?: Não - Material das Dobradiças: Não Possui - Possui Rodízios?: Não - Garantia (dias): 90 - Grau de Dificuldade da Montagem: Médio - Recomendação de Manutenção: Usar pano seco ou levemente umedecido, não usar quaisquer produtos abrasivos. - Peso Suportado nas Gavetas (Kg): 3 Kg - Revestimento /Acabamento: Finish Foil - Possui Vidro?: Não - Possui Espelho?: Não - Quantidade de Nichos: 1 - Material do Puxador: Plástico - Espessura da Estrutura: 15 mm - Possui Gavetas?: Sim - Quantidade de Gavetas: 2 - Possui Portas?: Não - Tipo de móvel: Cômoda - Possui Puxadores?: Sim - Material das Corrediças: Metálica - Tipo da Corrediça: Telescópica - Possui Prateleiras?: Não - Material da Estrutura: MDP - Escala de Brilho: Fosco', 277.9, 254.63, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lwf3w53fiqag4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F580791382%2F18899298119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22591829685', 'Filtro de Óleo do Motor Tempra 2.0 16v HLX Ouro 1993 1994 1995 1996 1997 1998 1999', 'Numero Referencia: WO-460 Observação: NÃO SERVE NO MODELO 8 Valvulas Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 42.71, 42.71, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134201-7qukw-ljenql9aph8f4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F22591829685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199272428', 'Energético Monster Zero Ultra Fiesta Mango', 'Monster Ultra Fiesta Mango é um energético zero açúcar e zero calorias com sabor de manga. Com a clássica fórmula Monster Energy, é perfeito para te dar energia durante a festa toda! Ingredientes: * Água gaseificada * Taurina * Cafeína * Vitaminas B3, B5, B6 e B12 * Extrato de guaraná', 10.49, 7.99, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8258w-mqnekbtnfvgrcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F22199272428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198045612', 'Reparo Bico Injetor Fiat Strada 2011 a 2018 - 810620 - 1243', 'Reparo Bico Injetor Fiat Strada 2011 a 2018 810620 1243 1.4 8v Flex - (Multi Point) (4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 38.84, 38.84, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7ren7-m2iaasuq1nz716', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22198045612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49357091815', 'Manto Flamengo Fan Masculina Jogo 1 Adidas 2026 + Kit Patchs CAMPÉON Libertadores 2025', 'Versão com Kit Patchs CAMPÉON Libertadores 2025 (Patch de Campeão + Patch de Participação + Patch N4) A camiseta de malha é confeccionada com a inovadora tecnologia CLIMACOOL da Adidas que absorve e dispersa o suor para que você tenha um desempenho fresco, seco e sem distrações. O escudo bordado ajuda a turbinar a sua paixão pelo time. Este produto é feito com materiais 100% reciclados. Ao reutilizar materiais que já foram criados, ajudamos a reduzir o desperdício e a nossa dependência de recursos não renováveis, além de reduzir a pegada dos produtos que fabricamos. Modelagem justa Decote em V Malha dupla 100% poliéster reciclado Escudo do CR Flamengo em silk Barra traseira alongada Medidas Aproximadas (Comprimento x Largura) P – 76 cm x 47 cm M – 77 cm x 51 cm G – 79 cm x 55 cm GG – 81 cm x 60 cm 2GG – 84 cm x 66 cm 3GG – 87 cm x 73 cm Instruções de Lavagem: - Não alvejar - Não lava a seco - Lava a máquina com água fria - Não utilizar secadora - Passa em baixa temperatura Informações adicionais sobre cuidados: - Não utilizar amaciantes - Lavar e passar do lado avesso - Secar no varal - Se a sua camisa for personalizada, priorizar a lavagem à mão Produto Oficial Licenciado do Flamengo. Ao comprar um produto oficial você fortalece seu clube que recebe royalties com a venda de cada produto.', 499.99, 499.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/br-11134207-820lf-mqoxpa4bndohce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467774639%2F49357091815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299240587', 'Regulador Pressão Ford Ecosport 2004 a 2012 - 133757 - 1193', 'Regulador Pressão Ford Ecosport 2004 a 2012 133757 1193 Motor 2.0 16v Flex Duratec - (Pressão - 3,8 Bar) O sistema de injeção eletrônica de combustível tem por objetivo proporcionar ao motor um melhor rendimento com mais economia, em todos os regimes de funcionamento, fornecendo uma dosagem de combustível mais precisa com resposta mais rápida. Ele tem como função ajustar a pressão em toda a linha de combustível, desde a saída da bomba até os bicos injetores. O Regulador de Pressão pode estar montado em três posições. A localização depende do sistema de injeção eletrônica utilizado.', 90.98, 90.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lufadts3toakec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20299240587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699296347', 'Aditivo Radiador G12 Original Volkswagen 1 Litro', 'GJZW012R2 Aditivo Radiador G12 Original Volkswagen 1 Litro. Bem vindo ao Grupo CAMVEL, sua loja oficial VW em Balneário Camboriú / Santa Catarina. Antes de fechar a sua compra, nos envie o número do chassi para confirmação da aplicação da peça. Horário de atendimento: De segunda sexta das 8h ás 12h e das 13h30 as 18h Sábado das 8h as 12h.', 157.94, 157.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-mburuhl377ks3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1653974679%2F23699296347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
