INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097668472', 'Kit Inf. Modulo Combustivel Vw Kombi 2006 a 2015 - 173524 - 1327', 'Kit Inf. Modulo Combustivel Vw Kombi 2006 a 2015 173524 1327 MOTOR 1.4 TOTALFLEX - (Sistema Bosch) O pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 72.58, 72.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd3v-lukqk673wo4b53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20097668472', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892568610', 'Termo-Interruptor (Cebolão) Fiat Uno 1986 a 1997 - 128660 - 17278892', 'Termo-Interruptor (Cebolão) Fiat Uno 1986 a 1997 128660 17278892 1.0/1.3/1.5 8v - Com Ar - 88°/92º - Cabo Curto No trânsito é importante o acionamento da ventoinha do radiador. A peça responsável por isso é o Interruptor Térmico. São comutadores (Liga-Desliga) que acionam diversos produtos no sistema de arrefecimento em função da temperatura. Localizado no radiador, aciona a ventoinha quando a temperatura ultrapassa a temperatura ideal de trabalho, evitando assim o superaquecimento do motor.', 114.4, 114.4, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rau6-maikt9g727gx3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22892568610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094339890', 'Piscina Estruturada Mor 1000l em Pvc Azul', 'A Piscina Estruturada Mor foi especialmente desenvolvida para garantir o bem-estar e diversão de crianças e adultos. Com estrutura metálica, a piscina tem capacidade para 1000 litros, possui peças plásticas em polipropileno com sistema de encaixe que facilita a sua montagem. Sua lona em PVC é leve e resistente, mas a piscina não deve ser transportada com água em seu interior, por isso, conta com prática válvula de deságue. A Piscina Mor tem dimensões aproximadas de 42x126x189cm (A x L x C).Dicas de PreservaçãoProteja sempre o piso para evitar objetos pontiagudos que possam perfurar o material.', 249.99, 249.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-825af-mqhrq6bjlamk99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23094339890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
