INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27337152904', 'Tubo Água HR 2005/2012 - 31668 - VC634A', 'Tubo Água HR 2005/2012 Motor 2.5 TCI/TD O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 91.24, 91.24, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7ratt-maitburra0s62e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F27337152904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
