INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46856834350', 'Camiseta Masculina Essentials Natural Flow', 'A Camiseta Essentials Natural Flow da Brunx Ind. é confeccionada em malha Natural Flow, uma composição de 48% algodão, 47% viscose e 5% elastano com gramatura de 220 g/m². A peça oferece um toque suave, fluidez e elasticidade, com gola do próprio tecido de 1,5 cm, reforço no centro das costas e barras fechadas em anel, garantindo resistência e um caimento elegante. Atenção: As cores podem sofrer variações conforme iluminação e dispositivo. Pequenas diferenças podem ocorrer entre os tamanhos. Produto no formato BLANKS, sem etiqueta fixada nas costas. Informações Técnicas: Composição:48% Algodão, 47% Viscose, 5% Elastano Gramatura: 220 g/m² Encolhimento: Zero Gola: do próprio tecido com 1,5 cm, com fechamento 2,5 cm para trás a partir do fechamento do ombro esquerdo. Reforço no centro das costas de 3 cm (B.C) pronto com 1 cm. Barras fechadas em anel com bainha de 2,5 cm e cobertura de 2 agulhas. Etiquetas: Interna de composição e tamanho Etiquetas de tamanho localizada no ombro.', 109.99, 99.0, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134207-820lm-mlgonyvkov7r29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F656490260%2F46856834350', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12410597197', 'Disco de Corte Diamantado Turbo 110 X 20 MM Corte à Seco MTX', 'Disco de Corte Diamantado Turbo 110 X 20 MM Corte à Seco Turbo MTX O Disco de Corte Diamantado Turbo MTX é produzido com materiais de alta qualidade contendo em seu disco grãos de diamante e liga metálica proporcionando maior resistência, durabilidade e um corte preciso; É indicado para cortes em concreto, pedra e tijolo. -Corte a seco; -Medidas: 110x20,2mm; -Diâmetro: 110mm; -Furo central: 20mm. -Indicado para uso em Serra Mármore *Imagens meramente ilustrativas', 35.9, 33.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/919cc222f2e2949626b52ae5730ce781', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F12410597197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293974825', 'Torneira Mesa Bica Móvel Purificador Lagune Vitalité Cromado - Viqua', 'A Torneira de Mesa Lagune Vitalité Viqua une design moderno, funcionalidade e saúde em um único produto. Com acabamento cromado de alto brilho e bica móvel, ela oferece praticidade no uso diário, ideal para pias de cozinha ou áreas gourmet. Integrado à torneira, o purificador de água Lagune Vitalité garante água limpa, livre de impurezas, odores e sabores indesejáveis, promovendo mais saúde e qualidade de vida para você e sua família. Com fácil substituição do refil, seu sistema de purificação é eficiente e durável. Vantagens: Design moderno com acabamento cromado de alta durabilidade Bica móvel: mais praticidade para direcionar o jato de água Purificador integrado: filtra impurezas, cloro, gosto e odores da água Refil de fácil substituição, sem necessidade de ferramentas Economia e sustentabilidade com água filtrada direto da torneira Dados Técnicos: Marca: Viqua Modelo: Lagune Vitalité Tipo: Torneira de mesa com purificador integrado Bica: Móvel, ideal para pias amplas Cor/Acabamento: Cromado Instalação: Mesa (1/2") Vazão: Aproximadamente 0,75 a 1,5 L/min (pode variar com pressão da rede) Pressão de funcionamento: 5 a 40 m.c.a. Filtragem: Redução de cloro livre, partículas e melhoria do sabor e odor da água Refil compatível: Refil Viqua Vitalité (troca recomendada a cada 6 meses ou 2.000 L) A Lagune Vitalité Viqua é a escolha perfeita para quem busca beleza, praticidade e saúde em um só produto, com a confiança de uma marca referência em purificação de água.', 209.9, 128.5, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rfgi-m9q6m5daq5cyaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23293974825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18730154793', 'Chave De Fenda Ponta Chata 3/16x3 Tramontina', 'Chave de Fenda Ponta Chata Tramontina 3/16x3 Pol. Niquelada é uma ferramenta essencial para quem busca precisão e durabilidade em serviços de montagem e manutenção. Com uma haste confeccionada em aço especial temperado, esta chave oferece resistência superior e longa vida útil. Seu acabamento niquelado previne corrosão, garantindo que a ferramenta mantenha seu desempenho ao longo do tempo. A empunhadura é feita de polipropileno injetado, proporcionando conforto e firmeza durante o uso, ideal para diversas aplicações. Seu comprimento de 3 polegadas permite fácil acesso a locais mais difíceis, tornando-a uma escolha versátil para profissionais e entusiastas de bricolagem. Vantagens: Haste fabricada em aço especial temperado Acabamento niquelado para prevenção de corrosão Ponta chata ideal para parafusos com fenda Empunhadura ergonômica em polipropileno injetado Comprimento de 3 polegadas para maior alcance TChave de Fenda Ponta Chata Tramontina 3/16x3 Pol. Niquelada é uma ferramenta essencial para quem busca precisão e durabilidade em serviços de montagem e manutenção. Com uma haste confeccionada em aço especial temperado, esta chave oferece resistência superior e longa vida útil. Seu acabamento niquelado previne corrosão, garantindo que a ferramenta mantenha seu desempenho ao longo do tempo. A empunhadura é feita de polipropileno injetado, proporcionando conforto e firmeza durante o uso, ideal para diversas aplicações. Seu comprimento de 3 polegadas permite fácil acesso a locais mais difíceis, tornando-a uma escolha versátil para profissionais e entusiastas de bricolagem. Vantagens: Haste fabricada em aço especial temperado Acabamento niquelado para prevenção de corrosão Ponta chata ideal para parafusos com fenda E