INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798751125', 'Kit Wafer Morango Zero Açúcar Vitao 90G - 4 Unidades', 'Feito com massa integral e vegana no sabor morango, o Wafer Vitao é um snack saudável, prático e muito crocante, com 4 camadas de recheio delicioso. E o melhor de tudo: Zero açúcares! Cada embalagem contém 90g de pura delícia! Com sua textura crocante e sabor irresistível, ele é a opção perfeita para quem quer manter um estilo de vida saudável sem abrir mão do prazer de um lanche delicioso. Seja no trabalho, na academia ou em casa, o Wafer Vitao Morango é a escolha ideal para uma alimentação equilibrada e saborosa. Experimente agora e deixe seu dia a dia ainda mais gostoso! INGREDIENTES: Recheio sabor morango (gordura vegetal, fibra de polidextrose, edulcorantes maltitol e sucralose, emulsificante lecitina de soja, acidulante INS 330, corante artificial INS 129, estabilizante INS 476 e aroma), farinha de trigo integral, farinha de trigo enriquecida com ferro e ácido fólico, sal, gordura vegetal, emulsificante lecitina de soja e fermento químico bicarbonato de sódio. ALÉRGICOS: CONTÉM DERIVADOS DE TRIGO E SOJA E PODE CONTER AMÊNDOA, CASTANHA-DE-CAJU, AVELÃ, AVEIA, CENTEIO, CEVADA, LEITE, AMENDOIM, PECÃ E OVO. CONTÉM GLÚTEN. INTEGRAL, ZERO ADIÇÃO DE AÇÚCARES, VEGANO, FONTE DE FIBRAS.', 49.89, 49.89, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj7525bd9szq24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F23798751125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092602434', 'Paralama de Bike MTB Downhill 280x270mm Dianteiro Mud no More RSD Absolute', 'Pedalar na lama é sempre uma missão complicada. A Boa notícia é que temos a linha completa de paralamas RSD para sua MTB ou Downhill! Sua principal função é proteger o curso da suspensão contra água, lama, pedras e etc. Logo após vem o benefício de proteção para o ciclista. Além das bikes Mtb e Downhill, é um acessório muito usado nas bicicletas de passeio e urbanas, sendo perfeitos para proteger o ciclista em um dia de chuva para ir até o trabalho e outros deslocamentos. CARACTERISTÍCAS DO PRODUTO: - Evita sujar o rosto com lama, pedriscos e outras sujeiras; - É fácil de ser instalado, com fixação simples, diretamente no garfo dianteiro ou na suspensão dianteira; - É fácil de remover caso não haja mais necessidade de usá-lo; - Compatibilidade com qualquer modalidade, tipo de bicicleta ou tamanho de aro. ESPECIFICAÇÕES TÉCNICAS: - Marca: RSD - Modelo: Absolute - Cores: Preto / Branco / Amarelo / Verde / Rosa / Vermelho - Fixação: Abraçadeira de Nylon - Posição: Dianteiro - Tamanho: 280x270mm - Material: Polímero Termoplástico - Peso: 35g CONTEÚDO DA EMBALAGEM: - 1 Paralama Dianteiro - 4 Abraçadeiras de Nylon GARANTIA: - 3 Meses diretamente com o fabricante.', 23.1, 23.1, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-7r98p-lmqd3564q3w704', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22092602434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
