INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298445483', 'Filtro Óleo Hyundai Galloper 1998 a 1999 - 1356823 - JFO0H01', 'Filtro Óleo Hyundai Galloper 1998 a 1999 1356823 JFO0H01 (Luxo / Super Luxo) - 3.0 V6 24V - Gasolina - Mecânico - (Blindado) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 34.79, 34.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfh7-m95lqj9r99qp38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23298445483', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
