INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259661539', 'Café em Cápsula Mogiana Paulista 3 Corações', 'Desfrute de um café espresso de alta qualidade com as cápsulas 3 Corações Mogiana Paulista. Este blend, preparado com grãos arábica cultivados na Alta Mogiana Paulista, oferece um aroma adocicado, acidez cítrica média e corpo aveludado, ideal para quem busca um café equilibrado e sofisticado. Com notas de chocolate amargo e caramelo, este café é perfeito para ser apreciado individualmente. Cada cápsula é compatível com máquinas Nespresso, garantindo praticidade e a qualidade do grupo 3 Corações, que há mais de 60 anos produz cafés de qualidade para os brasileiros.', 26.79, 26.79, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvy-mmkdznajkb2aa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F58259661539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
