INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092570707', 'Mangueira Filtro Ar Fiat Siena 2003 a 2011 - 202170 - TR510', 'Mangueira Filtro Ar Fiat Siena 2003 a 2011 202170 TR510 Tomada Ar 1.0/1.3 8V FIRE FLEX A mangueira ou duto de ar é responsável pelo envio de ar admitido para o coletor de admissão. É importante manter a peça em bom estado, sem furos ou cortes que permitam a entrada de ar impuro para admissão pós filtro, o que pode causar variação na pressão do ar admitido causando interferências na eficiência do motor quanto a queima de combustível.', 45.76, 45.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbk5-lmz66nxg6u4lbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22092570707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49560764625', 'Toalhas Umedecidas Pet Clean Caes Gatos 50un', 'As toalhas umedecidas Pet Clean foram desenvolvidas para auxiliar na higiene diária de cães e gatos com praticidade e suavidade. Ideais para limpeza rápida entre os banhos, ajudam na remoção de sujeiras das patas, pelos e região do focinho. Sua fórmula suave proporciona limpeza eficiente sem agredir a pele do animal, sendo indicada para uso cotidiano. O formato prático facilita o transporte e o uso em diferentes momentos da rotina, como passeios, viagens ou após brincadeiras. Indicadas para manter o pet limpo e confortável de maneira rápida e conveniente. FICHA TÉCNICA • Indicação: Higiene diária para cães e gatos • Finalidade: Limpeza rápida e prática • Tipo de produto: Toalhas umedecidas • Composição: Fibras umedecidas com agentes de limpeza suaves • Forma de apresentação: Pacote • Quantidade: 50 unidades • Público alvo: Cães e gatos CUIDADOS COM O PRODUTO Uso externo Evitar contato direto com os olhos Manter a embalagem bem fechada após o uso Armazenar em local fresco e seco Manter fora do alcance de crianças', 29.9, 15.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-822wi-moeggqep105l0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F49560764625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
