INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598067689', 'H''maston MS05 Mouse Luminoso Sem Fio 2.4Ghz Mouse Bluetooth 5.2 Mac Ergonômico', 'FIO, 1600 DPI, USB 2.0 Fio MS05 é uma excelente opção para quem busca praticidade e comodidade na hora de utilizar o computador. Sua conexão USB plug and play permite que você o conecte rapidamente ao seu computador, sem precisar de drivers ou softwares adicionais. Isso significa que você poderá começar a usá-lo imediatamente, sem qualquer complicação. 1600 DPI PARA UMA NAVEGAÇÃO PRECISA E SUAVE O Mouse MS05 sem Fio MDR-0104-B possui uma resolução de 1600 DPI, o que significa que ele é capaz de captar até mesmo os movimentos mais sutis do seu pulso. Isso garante uma navegação suave e precisa, aumentando sua produtividade e eficiência na hora de utilizar o computador. DESIGN MODERNO E CONFORTÁVEL PARA USO PROLONGADO sem Fio MS05 possui um design moderno e elegante, que combina perfeitamente com qualquer ambiente de trabalho. Além disso, sua forma anatômica e ergonômica garante um conforto excepcional, permitindo que você o utilize por horas a fio sem sentir cansaço nas mãos. Especificação: - Marca: H''maston - Modelo: MS05 - Compatível: Windows e Mac - Resolução: 800-1200-1600DPI - Conexão: USB e Sem fio - Quantidade de botão: 4 Botões - Distância: 10m Tamanho: 10.35x6.55x5.5cm Peso: 68g+-5g - Fonte de alimentação:Bateria não recarregável', 99.0, 42.99, NULL, 'Computers & Accessories > Keyboards & Mice > Mice', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3ft0tfbq8mwe0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1155571749%2F23598067689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
