INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205168525', 'Farol Milha Auxiliar Ka 2008 2009 2010 2011 Fiesta 07 08 09', 'Código do Produto: 000003 Farol De Milha Ka 2008 2009 2010 2011 Fiesta 2007 2008 2009 Os faróis de milha contribuem para uma iluminação mais distantes que o farol convencional. São apropriados especialmente para estradas e ambientes noturnos, que não possuem nenhum tipo de iluminação além da provida pelos próprios automóveis. Nossos farols de milha contém componentes de alta qualidade, resistência e um acabamento impecável. DIFERENCIAL: - Visão até 50% maior - Auxilia em até 50% em caso de neblina - Encaixe 100% Original - Produto com Garantia Compatível com: Ford - Ka 2008 - Ka 2009 - Ka 2010 - Ka 2011 - Fiesta 2007 - Fiesta 2008 - Fiesta 2009 ESPECIFICAÇÕES TÉCNICAS: - Tecnologia da Lâmpada: Halógena - Encaixe da lâmpada: HB4 - Material da Lente: Acrílico - Material da carcaça: Plástio - Regulagem: Manual IMPORTANTE O valor anunciado é referente a unidade Garantia de 90 dias contra defeitos de fabricação. Não nos responsabilizamos pelo mal uso ou má instalação do produto. Procure um profissional especializado. Garantia do vendedor: 3 meses', 38.49, 38.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mkmyr8fygk5h45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310462644%2F58205168525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
