INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53860854805', 'Kit 4 Pneus Carro Golden Crown RP68 205/50R17 93V', 'O Golden Crown RP68 foi desenvolvido para motoristas que procuram conforto, estabilidade e segurança no uso diário. Seu desenho da banda de rodagem proporciona boa aderência, desgaste uniforme e rodagem silenciosa, garantindo uma condução mais confortável tanto em trajetos urbanos quanto rodoviários. Com construção radial e tecnologia sem câmara (TL), o modelo oferece maior durabilidade, estabilidade em curvas e desempenho equilibrado em pisos secos e molhados. O kit com 4 pneus é ideal para a troca completa do veículo, proporcionando melhor equilíbrio, segurança e desempenho na condução. Diferenciais Boa estabilidade e dirigibilidade Excelente aderência em piso seco e molhado Rodagem mais silenciosa Desgaste uniforme da banda de rodagem Ótimo custo-benefício Compatibilidade Compatível com veículos que utilizam medida 205/50R17, como: Honda Civic Nissan Sentra Fiat Linea Fiat Punto Volkswagen Polo Volkswagen Virtus Ford EcoSport Peugeot 307 Entre outros modelos compatíveis. Conteúdo da Embalagem 4 Pneus 205/50R17 93V TL Golden Crown RP68', 1491.9, 1491.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-823ox-moh02ppq7totdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F53860854805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
