INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997616492', 'Mini Veículos Die Cast Garagem S.A. - Caminhonete Vermelha', 'A Garagem S.A. apresenta a coleção de mini veículos Die Cast, uma linha de modelos incríveis na escala 1:58 para os entusiastas e colecionadores. Com 24 modelos diferentes e uma variedade de cores, você terá a oportunidade de construir uma coleção única e diversificada. Cada mini veículo Die Cast é meticulosamente detalhado, capturando a essência e o estilo dos carros em escala reduzida. Os detalhes realistas, a pintura precisa e as cores vibrantes garantem uma experiência visual impressionante. Esses mini veículos são perfeitos para colecionadores e entusiastas de todas as idades. Eles são ótimos para exibição em estantes, dioramas ou simplesmente para se divertir em brincadeiras imaginativas. Entre no mundo emocionante dos mini veículos Die Cast da Garagem S.A. e comece sua jornada de colecionador. Explore os 24 modelos disponíveis, escolha suas cores favoritas e comece a construir uma coleção incrível.', 18.99, 18.99, NULL, 'Hobbies & Collections > Collectible Items > Vehicle Models & Diecast', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-lupltdtga9nadd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F21997616492', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41530360929', 'Pré Venda - My Mini Baby Disney', 'Prepare-se para se apaixonar pela coleção que une o realismo impressionante dos mini bebês ao universo fantástico da Disney. O My Mini Baby Disney Série 1 traz uma experiência única de ternura e descoberta. Cada cápsula revela um bebê de silicone ultra-realista, com pele macia ao toque e detalhes delicadamente pintados à mão, feitos para caber perfeitamente na palma da sua mão. A magia acontece em cada unboxing: ao abrir a cápsula surpresa, você descobre um mundo temático inspirado nos personagens mais amados de todos os tempos. Imagine encontrar um berço divertido do Stitch, o carrinho de aventuras da Moana ou o cadeirão fofinho do Ursinho Pooh. Com seis modelos diferentes para colecionar, você pode montar um berçário completo e cheio de detalhes mágicos. Cada unidade é um kit completo de cuidado e diversão, incluindo o mini bebê, um playset exclusivo, acessórios temáticos e até uma certidão de nascimento para oficializar sua nova coleção. É o presente perfeito tanto para crianças que amam brincadeiras afetivas quanto para fãs da Disney que buscam miniaturas exclusivas e de alta qualidade. Traga a doçura e o encanto dos seus personagens favoritos para o mundo real com o My Mini Baby Disney!', 169.99, 169.99, NULL, 'Hobbies & Collections > Collectible Items > Idol Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-823rc-moi87yv9vsp80c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F41530360929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56253012703', 'Caixa Supresa Stranger Things Chibi 5cm', 'A Caixa Surpresa Stranger Things Chibi 5cm traz mini-figuras estilizadas dos personagens mais icônicos da série. Cada caixa contém uma figura exclusiva com um estilo único, ideal para quem adora reviver as aventuras do Mundo Invertido. A revelação surpresa torna cada momento ainda mais emocionante, oferecendo figuras perfeitas para exibição. A Candide Brinquedos é sua escolha número um para diversão e aprendizado. Com mais de 55 anos de experiência, somos a referência no mercado de brinquedos. Nossos produtos inovadores estimulam a imaginação e o desenvolvimento infantil. Como distribuidores exclusivos de marcas populares, oferecemos qualidade e diversão incomparáveis.', 99.99, 99.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-822x5-mi6dulub4buo22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F56253012703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
