INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260907549', 'SANITIZANTE VINTEX FRESH - VINTEX', 'Sanitizante Fresh foi desenvolvido com quaternário de amônio especial, que age na eliminação de fungos e bactérias do interior do veículo ou ambiente, auxiliando na redução de doenças causadas por esses microorganismos e eliminando maus odores. Além disso, o produto também promove agradável aroma no interior do veículo ou ambiente. TAMANHO: 1,5L', 46.53, 46.53, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-822zg-moehjiy8prm1e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552415726%2F58260907549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258829448', 'REMOVEX 5L', 'Removex é um desengraxante e limpador de chassi de alto poder de ação, desenvolvido para remover sujeiras pesadas como óleo, graxa, barro, lama, matéria orgânica de chassi, carrocerias de ferro e madeira. Modo de usar: 1. Para limpeza pesada, pulverizar o produto diluído na proporção de 1L para 10L de água na superfície a ser aplicada 2. Aguardar entre 1 a 3 minutos e sem seguida enxaguar completamente com um jato d''água 3. Em caso de limpeza mais leve, o produto deve ser diluído em maior proporção', 83.87, 83.87, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-81ztu-mn1ukn0vjsw3b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552415726%2F58258829448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
