INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198562621', 'Kit Pantene Queratina Shampoo + Condicionador + Creme + Máscara Hidratação + Óleo Milagroso Queratina', 'Kit Pantene Queratina Shampoo + Condicionador + Creme + Máscara Hidratação + Óleo Milagroso Queratina O kit contém: 1- Máscara Capilar De Tratamento Pantene Hidratação 270ml 1- Kit Pantene Shampoo 300ml + Condicionador 150ml Queratina 1- Óleo Capilar Pantene Milagroso Queratina 95ml 1- Creme Para Pentear Pantene Queratina Preenche & Blinda 240g Benefícios:Hidratação Profunda e Duradoura Reposição deQueratina Reconstrução e Blindagem dos FiosRedução da Quebra e Pontas DuplasMaciez e Brilho IntensoAção Anti-Frizz e Alinhamento dos FiosDesembaraço Fácil e Cuidado DiárioProteção Térmica e Finalização Perfeita Sobre a marca: O nome de Pantene se refere a origem do produto, o Panthenol, nome científico da Vitamina B5. Na década de 40, a companhia suíça Hoffman-La Roche descobriu que o Panthenol era extremamente hidratante e melhorava a saúde do cabelo quando combinado com outros ingredientes. Pantene confere cabelos bem cuidados, macios, cheios de brilhos com uma aparência solta e saudável, é o cartão de visita de qualquer bela mulher em quase todas as partes do mundo.', 143.05, 106.96, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mr1s5hfrl91c0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23198562621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597504355', 'Livro Infantil Conte Uma História Fazendinha do Seu Lobato Viver no Campo', 'Todo mundo gostaria de morar na Fazendinha do Seu Lobato. Muita natureza, ar puro, animais vivendo em harmonia e a simpatia de sempre do Seu Lobato deixam esse cantinho com uma sensação de aconchego. Nesse livro nós vamos saber como cada um faz a sua refeição do almoço e como passam as tardes. Vamos ver os porquinhos, galinhas, vacas, abelhas e cavalos tendo a sua rotina de alimentação com suas famílias.', 13.9, 13.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-820ln-moqtt2e5q0w38b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F23597504355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197692599', 'GA.MA ITALY Modelador Duo Spirale Lichia Bivolt', 'Brilho e nutrição para o seu cabelo! O tubo do modelador Duo Spirale Lichia é feito com a exclusiva tecnologia Essential Oil, ativada com o calor do produto, que nesta versão traz o óleo de Lichia: rico em vitamina C, auxilia na manutenção da nutrição e fortalecimento dos fios. A lichia também contém antioxidantes que contribuem para a proteção dos fios contra a agressão dos produtos químicos. Já a tecnologia Antifrizz é produzida pela alta emissão de íons negativos, que ajudam a manter a umidade natural ao mesmo tempo em que fecha a cutícula capilar; resultando em cabelos mais saudáveis, sedosos e com menos frizz. Com o modelador Duo Spirale Lichia, você tem a opção de cachos com dois diferentes diâmetros: 19mm e 32mm, em apenas uma só ferramenta. Ele atinge 180°C de temperatura, possui o tubo modelador com o guia de modelagem para fazer os cachos, cabo giratório e ponta com isolamento térmico, para você fazer cachos da maneira mais prática possível.', 179.9, 179.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-lyaz091k4iua3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F964602453%2F22197692599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
