INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211264206', 'Tênis Olympikus Corre Vento 3 - Unissex', 'O Corre Vento 3 chega com um design inédito e uma nova seleção de tecnologias, pronto para acompanhar você desde as primeiras voltas nas pistas. Um novo tênis. Conheça as tecnologias do Olympikus Corre Vento 3 ELEVA PRO 2.0 Tecnologia que aumenta os índices de resiliência, conforto e responsividade. CADARÇO Desenvolvido para garantir um ajuste perfeito e uma amarração firme, entregando segurança em todos os movimentos. Solado antiderrapante, feito para proporcionar maior durabilidade e tração. OXIFLEX Cabedal confeccionado com fios TPU e TPE, para oferecer mais resistência, toque macio e leveza. DROP 8mm Uma Uma combinação de resposta e conforto, feito para correr com quem está começando e quem já sabe até onde quer chegar.Combinação de resposta e conforto, feito para correr com quem está começando e quem já sabe até onde quer chegar.', 599.99, 599.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-823rh-mp5faufy7wu9d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509687760%2F58211264206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
