INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259446739', 'Président Manteiga Extra com Sal Gastronomique', 'A Manteiga Président passa por um processo diferenciado de produção para chegar à original receita francesa, sendo a número 1 na França e a preferida dos chefs! Indispensável para passar no pão ou para preparar receitas doces e salgadas. A manteiga Président possui um toque especial, com notas amendoadas e textura cremosa. Perfeita para pratos sofisticados e saborosos. Mantenha resfriado de 2°C a 8°C.', 16.99, 16.99, NULL, 'Food & Beverages > Dairy & Eggs > Butter & Margarine', 'https://cf.shopee.com.br/file/sg-11134201-825a7-mqnelgt0foy769', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259446739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
