INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12781697419', 'Refil para Escova Elétrica Philips Colgate SonicPro Limpeza Profunda com 2 unidades', 'Remove até 7x mais placa* do que uma escova manual. *Estudo clínico de 2 semanas com 138 participantes (Estados Unidos - 2010). Cerdas macias que limpam em lugares difíceis de alcançar. Utilize em modelos que possuem lembrete de troca para desbloquear os recursos inteligentes: a cabeça rastreia a frequência de escovação para notificar o momento de substituição. Refil compatível com qualquer escova de dentes elétrica Philips Colgate. Contém: 2 Refis Limpeza Profunda Philips Colgate.', 134.29, 134.29, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/7fd956464f814768ec9bc9c38427dc5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12781697419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18062871268', 'Kit 5 Tabletes 4 em 1 Cif Para Máquina de Lavar Louças 315g', 'O Kit contém 5 Tabletes 4 em 1 Cif Para Máquina de Lavar Louças com 315g cada. Limpa Com Alta Eficiência Protege e Cuida Remove a Gordura Difícil Seca e Dá Brilho Rende 18 Máquinas Detergente para Máquina de Lavar Louças. CIF Tabletes 4 em 1 para Máquina de Lavar Louças é o seu mais novo aliado para utilizar em sua máquina, e ter suas louças sempre limpas e brilhantes como você nunca viu antes. Sua fórmula foi desenvolvida na França e oferece uma limpeza com alta eficiência, desengordura e remove manchas mais difíceis, seca e da brilho impecável aos copos, além de proteger e cuidar. CIF Tabletes 4 em 1 possui uma solução completa em um único tablete, pois ele não necessita que você faça uma pré lavagem, pode ser usado em ciclos curtos da lava louças e já possui o secante abrilhantador. O novo CIF tablete 4 em 1 foi feito para usar na máquina de lavar louças, rendendo até 18 máquinas. Além disso, possui a tecnologia SUN, filme biodegradável e é livre de fosfato. Por isso, CIF Tabletes é mais do que apenas um sabão para lava louça, CIF tabletes é poderoso na limpeza e imbatível no cuidado. CIF oferece uma linha completa de produtos para o cuidado das louças, pois sabemos a importância de um bom produto para quem ama a praticidade de uma lava louça. Para os que se importam com uma limpeza poderosa, CIF traz mais essa novidade que é super completa e perfeita para usar na lavadora de louça. CIF não é apenas mais um sabão para lava louça, mas sim um produto especialmente desenvolvido para o cuidado com a sua casa. Novo CIF. Poderoso na Limpeza e Imbatível no Cuidado. Formulado com ingredientes que ajudam a proteger as louças de vidro e evita a formação de limo em sua máquina. Leite queimado, carne, gema de ovo, arroz, chá, entre outras manchas.', 308.89, 308.89, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-22110-7aw95nxtl2jvca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F18062871268', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18160217478', 'Carga para Aparelho de Depilar Gillette Venus Spa 4 Unidades', 'Carga para Aparelho de Depilar Gillette Venus Spa 4 Unidades "Você quer a melhor depilação de Vênus? As recargas do Gillette Venus Spa são ideais para você. Apresentam 3 lâminas e barras de gel flexíveis integrados que se adaptam às curvas do seu corpo para uma depilação suave e rente, proporcionando uma experiência inimaginável. Basta molhar o aparelho para ativar o gel lubrificante e voila! Você terá uma depilação suave, fácil e rápida. Revele a deusa em você. Para melhorar a experiência de depilar, use o Gel de Depilar SatinCare. - Com barras de gel integradas que se ativam com a água para uma depilação sem necessidade de usar sabão; - Três (3) lâminas para uma depilação suave; - Fragrância de chá branco; - Suaviza e lubrifica para uma pele suave com apenas uma passagem; - Todas as recargas Venus podem ser utilizadas em qualquer aparelho de depilar Venus, exceto descartáveis; - Recargas fáceis de substituir" - Compre produtos Gillette', 111.09, 99.06, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/92e6d541af0e67790f930f7db48d90ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F18160217478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
