INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499178144', 'Fantasia Cowgirl Infantil Vestido Festa Junina Com Cinto E Chapéu', 'A fantasia cowgirl infantil é a escolha ideal para festas temáticas country ou juninas. Cheia de estilo, ela une conforto e visual autêntico para a pequena se divertir à vontade. Ideal para apresentações escolares, rodeios infantis e eventos temáticos, a fantasia inclui vestido com recorte de colete em padrão de vaca marrom e branco, saia rodada bege e faixa com estrela dourada. O chapéu marrom completa o look típico de cowgirl. Diferenciais: - Acompanha chapéu country infantil - Detalhes com franjas e estampa cow print - Confeccionada com tecido leve e confortável Indicações de tamanho de acordo com numeração de roupa da criança: P 3 - 4 / M 6 - 8 / G 10 - 12. Garantia: 30 Dias Genero: Menina Codigo do Produto: 938331 Tamanhos: P 3|4 M 6|8 G 10|12 Anos Descrição: Fantasia Cowgirl Infantil Feminina - Festa Junina Composição de Tecido: Vestido: 100% poliéster. PERSONAGEM: Cowgirl Infantil Itens Inclusos: 01 Vestido com Colete, 01 Cinto e 01 Chapéu', 159.99, 159.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Others', 'https://cf.shopee.com.br/file/sg-11134201-820of-mnvilg7fyxaa95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F19499178144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
