INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294062573', 'Colchão Airtech 150 D45 – Solteiro (78x188x18)', 'Colchão Airtech 1.5.0 D45 Solteiro (78x188x18) O Colchão Ortobom Airtech 1.5.0 D45 é ideal para quem prefere um conforto mais firme e apoio estável durante o sono. Produzido com espuma D45 Pró Aditivada de Alta Performance, proporciona excelente sustentação e resistência, preservando a forma do colchão por muito mais tempo. A base conta com placa de EPS, que reforça a estrutura. O tampo em malha com bordado matelassê oferece toque suave e visual sofisticado, elevando o padrão de conforto. Além disso, o modelo possui proteção contra ácaros e agentes alérgicos, promovendo noites tranquilas, higiênicas e um descanso verdadeiramente revigorante.', 580.9, 511.19, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-825zt-mk9oc9r52sy059', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F22294062573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
