INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594296881', 'Lava Autos Vintex 1,5l Concentrado Neutro Shampoo Automotivo', 'O Lava Autos Vintex 1,5l Concentrado Neutro Shampoo Automotivo é o produto ideal para quem busca limpeza e proteção para o seu veículo. Com sua fórmula concentrada, este shampoo automotivo oferece uma limpeza profunda, removendo sujeiras e impurezas sem danificar a pintura. Além disso, sua composição neutra conserva a lataria, mantendo o brilho e a cor do seu carro por mais tempo. Com um volume de 1,5L, o Lava Autos Vintex proporciona um excelente rendimento, sendo uma opção econômica para a manutenção do seu veículo. Proteja e conserve a beleza do seu carro com o Lava Autos Vintex 1,5l Concentrado Neutro Shampoo Automotivo.', 27.29, 27.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mlrvfqu395og9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F22594296881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
