INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493879166', 'Lava-Louças Limpol Gel Concentrado Cristal 400g', 'Lava-Louças Limpol Gel Concentrado Cristal, embalagem contendo 400 gramas, oferece o máximo de rendimento e eficiência com tensoativos biodegradáveis, removendo até as gorduras mais difíceis com facilidade. É testado dermatologicamente e possui hidratante em sua fórmula deixando as mãos livres de ressecamento. Possui tecnologia anti-odor eliminando cheiros que costumam ficar nos utensílios. Modo de uso: Aplique 1/3 da quantidade habitual sobre uma esponja úmida e esfregue sobre a superfície a ser limpa.', 16.68, 15.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7reqp-m83ygx7ly2lj2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1506316714%2F22493879166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
