INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209713183', 'Chiclete Trident XGamers Citrus Maracujá e Limão', 'Trident X Gamers Citrus Mix é o chiclete ideal para quem busca foco e energia durante os jogos ou no dia a dia. Com sabor refrescante de maracujá e limão, este chiclete sem açúcar oferece uma experiência única e duradoura. A embalagem em pote é perfeita para levar sempre com você.', 15.79, 14.2, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-82597-mqnel5v4uznx3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F58209713183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19577230752', 'Jogo da Vida - Estrela', 'Jogo da Vida - EstrelaExplore diferentes profissões, ganhe dinheiro, case, tenha filhos e até invista na bolsa de valores. O Jogo da Vida - Estrela é a simulação perfeita para momentos de sorte e azar, onde cada escolha pode mudar o rumo da sua vida. Desenvolva habilidades, tome decisões estratégicas e embarque nessa jornada em busca do sucesso. Com suporte para 2 a 8 jogadores, é ideal para reunir a família e os amigos em momentos de entretenimento. Idade recomendada: A partir de 7 anos. Selo Inmetro: CE-BRI/IQB AJ001 NM 300/2002. Diferenciais:Clássico e tradicional: um jogo atemporal que diverte gerações há décadas. Interação e diversão em grupo: crie momentos memoráveis com quem você mais gosta. Educativo: estimula o pensamento estratégico, simulação de situações e tomada de decisões. Mais sobre o Produto:O Jogo da Vida traz uma divertida simulação da vida real, repleta de possibilidades, desafios e diferentes caminhos para seguir. A cada jogada, os participantes são convidados a tomar decisões importantes, testar estratégias e encarar situações que tornam a experiência envolvente e surpreendente. Ideal para meninas e meninos de 7 a mais de 14 anos, o jogo estimula o raciocínio e a tomada de decisões, trazendo um estilo de brincar que desafia os jogadores a pensar além e buscar o melhor resultado. Para deixar a partida ainda mais dinâmica, é possível baixar o aplicativo complementar, que adiciona interações e deixa tudo ainda mais emocionante. Dicas de Uso:Incentive a criatividade e a comunicação entre os jogadores. Explore diferentes estratégias e caminhos para alcançar o sucesso. Divirta-se e aproveite para ensinar sobre planejamento financeiro de forma lúdica. Ficha Técnica:Marca: Estrela; Nome do produto: Jogo da Vida; Idade recomendada: A partir de 7 anos; Selo Inmetro: ?CE-BRI/IQB AJ001 NM 300/2002; Contém: 1 tabuleiro, 6 carrinhos, 32 pinos azuis, 32 pinos rosas, 24 cartões de riqueza, 24 apólices de seguro, 360 notas, 8 certificados de ações, 21 notas promissórias, 1 roleta e 1 manual de instruções.', 164.99, 164.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-8261i-ml5ixsbocg0231', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19577230752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
