INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44051554196', 'Sapatilha Infantil Menina Bailarina Fivela Confortável Kidy Soft Brilho Delicada Boneca Jeans Preto', 'A sapatilha infantil Kidy Bailarina une conforto, qualidade e um toque moderno. Feita em jeans com apliques brilhantes, traz charme para qualquer look. Com palmilha anatômica e solado antiderrapante, garante segurança a cada passo. A tecnologia Respitec mantém os pés secos e livres de odores, proporcionando bem-estar o dia todo. Perfeita para as pequenas arrasarem com estilo e conforto! Tamanhos: do 23 ao 32 Fechamento: Fivela Cabedal: Napa/Napa Metal Forro: Têxtil Absorvente Palmilha: Anatômica Respitec Sola: TR Antiderrapante', 139.99, 119.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Flats', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9zvw2eea03m38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F44051554196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
