INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192849606', 'Calça Jeans Masculina Reta Hering', 'Calça jeans masculina reta, a clássica indispensável no guarda-roupa. Elaborada em jeans com elastano, possui modelagem reta com caimento perfeito.Esta peça faz parte da nossa linha de básicos. São itens essenciais e versáteis que podem ser coordenados entre si e combinam com todo o seu guarda-roupa.Detalhes da peça:Em jeansModelagem retaFive pocketsCós com passantesFechamento com zíper e botão', 199.99, 199.99, NULL, 'Men Clothes > Jeans', 'https://cf.shopee.com.br/file/sg-11134201-7rcf7-lrivxrwfa0uv85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F22192849606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098002531', 'Conjunto de 6 Pratos Rasos 26 cm Oxford Páscoa', 'Descubra toda a magia de um bosque encantado com a coleção Fábula de Páscoa. Inspirada na poesia da natureza, cada peça celebra a suavidade dos tons neutros e o encanto das ilustrações delicadas. Com um coelhinho ilustrado entre folhas e flores, a coleção evoca a serenidade de um refúgio na floresta, onde o aconchego e a harmonia preenchem o ambiente. Perfeita para quem deseja transformar a mesa de Páscoa em um cenário encantador e cheio de afeto. O conjunto é composto por 6 pratos rasos com 26 cm de diâmetro. Conteúdo da embalagem: 06 Pratos Rasos 26 cm (diâmetro). - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Modelo: Raso - Unidades por kit: 6 - Forma: Redonda - Linha/Decoração: Páscoa - Tipo de prato de louça: Raso - Utilizações seguras: Lava-louças e Micro-ondas - Condição do item: Novo - Cor: Multicor - Diâmetro: 26 cm - Formato de venda: Kit - É apto para lava-louças: Sim - É kit: Sim - Material: Cerâmica - Tipo da embalagem: Papelão pardo ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 219.89, 219.89, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqxjlrzqob2dcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F21098002531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993250659', 'Protetor Solar Retrátil Black - Safety 1 St', 'Fixação fácil por ventosas e com botão de retração rápida. Acessório essencial para proteger a criança do sol enquanto viaja de carro. Dias quentes e ensolarados são um convite para passeios, mas ao transportar as crianças no carro, precisamos ter toda atenção e cuidado com todos os detalhes. Para isso o Protetor Solar Retrátil da Safety 1st é um acessório indispensável. Fácil de instalar, basta pressionar as ventosas no vidro e com seu botão para retração rápida, recolha quando quiser, sem precisar desinstalar o produto. Para proteção da incidência direta dos raios solares ou mesmo para reduzir o excesso de luminosidade durante aquela agradável soneca, o Protetor Solar Retrátil Safety 1st estará sempre à mão. Características: • Fácil instalação • Fixação por ventosas • Equipado com botão para recolher, sem a necessidade de desinstalar o produto • Barra a luz solar e diminui a luminosidade nos veículos', 69.9, 69.9, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-lzusp5weo2lo54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F23993250659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193274872', 'Moisés Dreamy Beige - Safety 1 St', 'Moisés portátil com função de balanço, cobertura com tela, colchonete macio e fechamento compacto com bolsa de transporte. Pés curvos com funções fixa e de balanço e laterais com tela arejadas. Estrutura leve, resistente e compacto quando fechado, fácil de montar, transportar e armazenar para usar em qualquer situação. Pés curvos com funções fixa e de balanço e laterais com tela arejadas. &nbsp;Colchonete macio removível para limpeza, cobertura tipo mosquiteiro fácil de instalar e fechamento simplificado com botões laterais e bolsa para transportar. Características: Funções fixa e de balanço Fechamento compacto através de botões laterais Cobertura tipo mosquiteiro fácil de instalar Colchonete macio removível para limpeza Laterais com tela mais arejadas Inclui bolsa para transporte', 699.0, 699.0, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-lzusot3te3bua2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F22193274872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397612461', 'Peruca Curta Verde Amarela Brasil Para Torcida Copa Carnaval', 'Vista a torcida com estilo! A Peruca Chanel Verde/Amarela é o acessório ideal para entrar no clima da Copa, Carnaval e festas temáticas. Feita em fibras sintéticas macias, essa peruca tem modelagem curta e charmosa no estilo chanel, perfeita para destacar seu look em eventos patrióticos. Pode ser combinada com pintura facial e fantasias para um visual completo e alegre. Diferenciais: - Corte chanel moderno e divertido - Cores vibrantes do Brasil: verde e amarelo - Leve, confortável e fácil de usar Dicas de uso: - Combine com camisa da seleção; - Glitter facial e acessórios em verde e amarelo.. Garantia: 30 Dias Genero: Feminino Composição de Tecido: 100% Fio Sintética Codigo do Produto: 907681 Tamanhos: Único TIPO DE PRODUTO: Peruca MODELO: Curta - Chanel Descrição: Peruca Curta Verde e Amarelo do Brasil Itens Inclusos: 01 Peruca', 29.99, 29.99, NULL, 'Fashion Accessories > Hair Accessories > Wigs & Extensions', 'https://cf.shopee.com.br/file/sg-11134201-822yy-mofln3al4w09f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F18397612461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
