INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998821255', 'Tênis Infantil Bibi Fisioflex 5.0 Azul Marinho', 'Descubra o tênis Fisioflex 5.0 da Bibi, a escolha perfeita para crianças cheias de energia! Especialmente desenvolvido com um conceito fisiológico inovador, este calçado é o companheiro ideal para os primeiros passos dos pequenos, contando com a colaboração de médicos e especialistas. Veja por que o Fisioflex 5.0 se destaca: Solado flexível que facilita movimentos naturais. Biqueira resistente que protege os dedinhos e aumenta a durabilidade. Tecnologia Fisioflex que simula a liberdade de andar descalço, promovendo amortecimento eficaz e estimulando funções neurológicas. Fechamento em tira que facilita o calce e torna a rotina mais prática para pais e filhos. Design que permite a respiração dos pés, garantindo conforto contínuo. Produto livre de substâncias tóxicas, refletindo o compromisso da Bibi com o bem-estar dos pequenos. Proporcione ao seu filho o melhor em conforto e segurança. Adquira agora mesmo o tênis Fisioflex 5.0 e garanta o desenvolvimento saudável do seu pequeno!', 219.9, 219.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-mdkecxwtedqx42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F22998821255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899135443', 'Tênis Infantil Bibi Action Preto com Rosa', 'O tênis Action da Bibi chega agora com uma combinação queridinha pelas crianças: preto com rosa. Versátil, moderno e cheio de charme, ele combina com tudo, seja do uniforme escolar aos looks de passeio. O cabedal transpirável, o fechamento de contato e o conjunto Palmilha Fisioflex + Solado BPLUS garantem conforto e autonomia para as crianças brincarem sem parar. Por que escolher o Action preto com rosa? Palmilha Fisioflex que simula andar descalço e favorece o movimento natural dos pés; Solado BPLUS leve, estável e com amortecimento para passos macios; Fechamento em tiras para ajuste rápido e seguro (mais autonomia no dia a dia); Cabedal com materiais respiráveis, ajudando a manter os pés arejados e confortáveis; Paleta de cores super versáteis, fáceis de combinar com looks casuais e esportivos; Com o Action, cada passo ganha estilo, conforto e praticidade. Um parceiro perfeito para escola, parque e todas as aventuras!', 249.9, 249.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-821ew-mgi0ye7gcr2j0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F23899135443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
