INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18446567339', 'Desembaraçador de Pelos Pet Clean para Cães e Gatos 500 ml', 'A LeluPets nasceu de uma paixão e dedicação de aproximadamente 20 anos de experiência nessa área tão incrível. Desde o início de nossa história, já são mais de 100 mil clientes atendidos. Estamos aqui determinados em fazer a diferença, democratizando e simplificando o cuidado com o seu pet para oferecer a melhor experiência para você e seu amiguinho. Mantemos nossas orelhas em pé, atentos às novidades do mundo pet para trazê-las até você. Nós somos apaixonados por pets! O seu pet é também da nossa família! Desembaraçador de Pelos Pet Clean para Cães e Gatos 500 mL O Desembaraçador de pêlos Pet Clean é um poderoso desembaraçador que auxilia a escovação de pêlos e remoção de nós, promovendo um melhor deslizamento das rasqueadeiras, pentes e escovas. Sua fórmula balanceada para cães e gatos contém blend de silicones especiais que além de desembaraçar os pêlos firmam uma super proteção, causando a agradável sensação de maciez para o pet. Indicado para cães e gatos de pêlos longos. - Ideal para cachorros e gatos com pelo longos; - Contribui para a finalização da escovação, não necessita enxague; - Auxilia na escovação de pelos e remoção de nós; - Contém silicone que garante proteção e causam macie. - Disponivel em frasco de 500 ml', 29.9, 21.9, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/sg-11134201-22120-9yi79qp9r3kv2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F18446567339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298989655', 'Fantasia Sally Estranho Mundo de Jack Infantil de Halloween', 'Itens inclusos: 01 Vestido Tamanhos: P - Numeração de roupa 2 a 4, para crianças que tenham até 99 cm de altura, dos pés a cabeça. M - Numeração de roupa 5 a 8, para crianças que tenham de 100 a 119 cm de altura, dos pés a cabeça. G - Numeração de roupa 9 a 12, para crianças que tenham de 120 a 140 cm de altura, dos pés a cabeça. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações Técnicas Material: Fantasia 100% poliéster. Produto: Fantasia nova, na embalagem. Cor: Preto Produto a pronta entrega! Procurando por fantasia de Halloween? Chegou essa ótima opção! Essa linda fantasia é estampada com a roupa da personagem Sally de O Estranho Mundo de Jack, estampa em altíssima resolução e cores chamativas, na região das costas não possui estampa e contém amarração para melhor ajuste da fantasia no corpo. Fantasia confeccionada em material de ótima qualidade, sendo 100% poliéster, e que trás muito mais conforto na hora do uso e é ideal para Halloween, Dia das Bruxas, Festa a Fantasia e muito mais. Confira! Fantasia de Sally Não pinica Não esquenta Super confortável Secagem rápida', 49.9, 49.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-8262w-mlwhc8yx70n6fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F21298989655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497561609', 'Kit Cobre Leito Casal 3 Pçs Dupla Face Turin Percal 300 Fios Black', 'Um cobre leito com tecido 300 fios com toque acetinado. Turin foi feito pensando em pessoas exigentes. A sofisticação é certa com o acabamento acetinado e brilhante do Kit Colcha Turin. Além de belo, o conjunto, que é confeccionado em tecido mate cetim tinto, é extremamente macio, confortável, resistente e tem um excelente caimento na cama. Com porta-travesseiro com 03 abas, o acabamento micromatelado mate cetim configura charme e elegância ao ambiente. Inspire-se. Produto composto por: CASAL 01 Colcha 2,10 x 2,30m 02 Porta Travesseiro 50x70cm+5cm Composição: Tecido externo: 100% Poliéster Enchimento: 100% Poliéster Garantia do vendedor: 24 meses CASAL 01 Colcha 2,10 x 2,30m 02 Porta Travesseiro 50x70cm+5cm QUEEN 01 Colcha 2,30 x 2,50m 02 Porta Travesseiro 50x70cm+5cm KING 01 Colcha 2,70 x 2,50m 02 Porta Travesseiro 50x70cm+5cm', 179.9, 179.9, NULL, 'Home & Living > Bedding > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd4r-lwg3f6vz2too75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816024645%2F23497561609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
