INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499249161', 'Toalhas Microfibra Automotiva Js 40x40 500gsm Laser', 'OBS: A COR PODE ALTERAR EM RELAÇAO A FOTO > DESCRIÇÃO A toalha de microfibra auto corte laser é uma toalha de limpeza feita com microfibras de alta qualidade que foram cortadas usando tecnologia a laser para garantir bordas limpas e precisas. Essa técnica de corte a laser permite que as fibras da toalha sejam cortadas com precisão, evitando desfiamento e prolongando a vida útil da toalha. As toalhas de microfibra são populares por serem altamente absorventes e macias, tornando-as ideais para limpar superfícies delicadas, como vidros e superfícies sensíveis a arranhões. Elas também são duráveis e resistentes a produtos químicos, tornando-as uma opção popular para uso em indústrias de limpeza profissional. A toalha de microfibra auto corte laser é uma opção de alta qualidade para aqueles que buscam uma toalha de limpeza durável e eficaz. Além disso, a técnica de corte a laser permite que a toalha seja personalizada com designs e logotipos, tornando-a uma opção popular para empresas que desejam personalizar suas toalhas de limpeza para fins de marketing e promoção da marca. > CARACTERÍSTICAS Feita com microfibras de alta qualidade Cortada com tecnologia a laser para bordas limpas e precisas Altamente absorvente e macia Durável e resistente a produtos químicos Ideal para limpar superfícies delicadas, como vidros e superfícies sensíveis a arranhões > ESPECIFICAÇÕES Material: Microfibra de alta qualidade Tamanho: 40cm X 40cm Peso: 500GSM Densidade de fibras: Alta, para garantir a eficácia da limpeza Método de corte: Corte a laser, para bordas limpas e precisas', 16.9, 16.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv0tgvetw4nxe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410524587%2F21499249161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297510775', 'Desodorante Aerosol Dove Invisible Dry 150ml', 'Sua fórmula possui ¼ de creme hidratante, que garante proteção e cuidado com as axilas, deixando-as suaves e macias. Além disso, possui vitamina E, que auxilia na recuperação da irritação causada pela depilação. Com notas verde-florais amadeiradas, apresenta fragrância moderna e discreta.', 22.39, 22.39, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lvav6nrsh37949', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22297510775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
