INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699257608', 'Shampoo Kerium La Roche-Posay Anticaspa 200ml', 'O Kerium Anticaspal da La Roche-Posay é um shampoo anticaspa purificante para caspa e couro cabeludo oleoso. Favorece a eliminação da caspa do couro cabeludo oleoso, de forma precisa e visível. O shampoo anticaspa restaura o equilíbrio fisiológico do couro cabeludo graças ao complexo purificador, contra o reaparecimento da caspa. Desde a primeira utilização, a eficácia é visível, e o cabelo fica suave e brilhante.', 182.55, 182.55, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd6t-lvm83xpnhva22d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21699257608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22735641361', 'Kit 2 Desinfetantes Lysoform Uso Geral Odor Suave 5L', 'O Kit contém: 2 Desinfetantes Lysoform Uso Geral Odor Suave com 5L cada. Desinfecção: aplique o produto puro e deixe agir por, no mínimo, 10 minutos. Vasos sanitários: coloque Lysoform sobre a reborda interna e as paredes laterais do vaso sanitário. Lixeiras e ralos: coloque Lysoform e deixe agir. Desodorização: use puro como controlador de odores desagradáveis. Perfumação: aplique Lysoform diluído, use duas colheres de sopa (25ml) por litro d''água em pisos, azulejos e superfícies laváveis. Não é preciso enxaguar. Lavagem de roupas: utilize meio copo americano (90ml) de Lysoform no processo final de lavagem. Não é necessário enxaguar.', 150.99, 150.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7qvfx-lezp5crtyddba3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F22735641361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25846620521', 'Chuteira Topper Society Infantil Juvenil Cup VIII Futebol De Grama Sintética Original Topper', 'Chuteira Society Infantil Topper Cup VIII Modelo: TP0565 Descrição do Produto: A Chuteira Society Infantil Topper Cup VIII é ideal para os pequenos que estão começando no futebol e querem dar show nos campos de grama sintética. Com design clássico e funcional, o modelo oferece conforto, durabilidade e tração, acompanhando o desenvolvimento das habilidades dentro de campo. Seu cabedal em material sintético resistente proporciona excelente controle de bola e proteção contra desgastes. O forro interno acolchoado garante um ajuste confortável e seguro, enquanto a palmilha em EVA anatômica oferece amortecimento leve para maior comodidade durante as partidas. O solado em borracha com travas baixas foi desenvolvido especialmente para o society, oferecendo ótima aderência, estabilidade e segurança nos movimentos rápidos e mudanças de direção. Características do Produto: - Indicação: Futebol Society Infantil/Grama sintética; - Categoria: Infantil/Unissex; - Cabedal: Sintético durável, resistente e fácil de limpar; - Forro: Acolchoado com conforto no calce e melhor ajuste; - Palmilha: EVA leve, anatômica e com bom amortecimento; - Solado: Borracha com travas baixas, tração e estabilidade em campos society; - Fechamento: Cadarço tradicional; - Design: Clássico, esportivo e funcional; - hIdeal para: Crianças em treinos e jogos recreativos. A Chuteira Society Infantil Topper Cup VIII pode ser encontrada aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 299.99, 113.99, NULL, 'Sports & Outdoors > Sports Footwear > Kid''s Sport Shoes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh67u2ftdekg24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F25846620521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16745758797', 'GRUPO KIT MARCHA BIKE ARO 29 21V COM FREIO A DISCO E TRANSMISSÃO SHIMANO', '🚴 KIT COMPLETO PARA MONTAGEM OU UPGRADE DA SUA MTB O Grupo Kit Marcha 21 Velocidades com Freio a Disco e Transmissão Shimano foi desenvolvido para quem busca renovar ou montar uma bicicleta aro 29 com componentes confiáveis, duráveis e de excelente desempenho. Equipado com transmissão Shimano 21 velocidades, oferece trocas de marcha suaves e precisas para encarar subidas, retas e descidas com mais eficiência. O sistema de freio a disco proporciona maior segurança e controle nas frenagens, mesmo em terrenos irregulares e condições adversas. Ideal para bicicletas MTB utilizadas em trilhas leves, estradões, ciclovias e uso urbano. 🔧 PRINCIPAIS DIFERENCIAIS • Kit completo para montagem ou upgrade • Transmissão Shimano 21 velocidades • Trocas de marcha suaves e precisas • Sistema de freio a disco • Melhor controle e segurança nas frenagens • Excelente custo-benefício • Componentes resistentes e duráveis • Ideal para bicicletas aro 29 📌 ESPECIFICAÇÕES TÉCNICAS TRANSMISSÃO • Marca: Shimano • Sistema: 3x7 velocidades • Total de velocidades: 21V • Câmbio dianteiro incluso • Câmbio traseiro incluso • Alavancas de câmbio inclusas • Componentes conforme configuração do anúncio FREIOS • Sistema de freio a disco mecânico • Pinças e componentes conforme configuração do kit APLICAÇÃO • Mountain Bike (MTB) • Uso urbano • Passeios • Estradões 🔗 COMPATIBILIDADE ✔ Bicicletas aro 29 ✔ Bicicletas MTB ✔ Quadros compatíveis com freio a disco ✔ Sistemas de transmissão 21 velocidades ✔ Trilhas leves e uso urbano ⚠ Verifique a compatibilidade do quadro, cubos, rodas e componentes antes da compra. 📦 CONTEÚDO DA EMBALAGEM • Componentes da transmissão Shimano 21V • Componentes do sistema de freio a disco • Itens conforme configuração do anúncio ❗ INFORMAÇÕES IMPORTANTES • Produto novo e pronta entrega • Acompanha nota fiscal • Imagens meramente ilustrativas • Recomenda-se instalação e regulagem por profissional especializado ❓ FAQ – DÚVIDAS FREQUENTES O kit é Shimano? Sim. O anúncio contempla transmissão Shimano 21 velocidades. Acompanha freios a disco? Sim. O kit acompanha componentes do sistema de freio a disco conforme a configuração do anúncio. Serve para bicicleta aro 29? Sim. Foi desenvolvido para bicicletas MTB aro 29 compatíveis. Posso utilizar em trilhas? Sim. É indicado para trilhas leves, estradões e uso urbano. O kit é completo? Sim. Acompanha os principais componentes para transmissão e frenagem da bicicleta. Agradecemos por comprar na RM BIKES.', 359.9, 316.72, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/c992c82e67f3f2fc6e17afaef17fbe4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369650932%2F16745758797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
