INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098389927', 'Umidificador De Ar Ultrassônico G-life 3,2l Bivolt Ionizador', 'Melhore a qualidade do ar em sua casa ou escritório com o Umidificador de Ar Ultrassônico da G-Life. Este dispositivo eficiente eleva a umidade do ar para níveis saudáveis, ajudando a aliviar sintomas de ressecamento causados pelo ar condicionado ou aquecimento. Com capacidade de 3,2 litros e tecnologia ultrassônica, ele é silencioso e perfeito para uso contínuo, inclusive durante a noite. Tecnologia Ultrassônica: Produz uma névoa fina com rotação 360° que se dispersa rapidamente para umidificar o ambiente sem molhar superfícies. Grande Capacidade: Com um reservatório de 3,2 litros, oferece até 10 horas de operação contínua, ideal para uso prolongado sem necessidade de reabastecimento frequente. Operação Silenciosa: Seu funcionamento ultra silencioso o torna perfeito para quartos, escritórios ou qualquer espaço que requer um ambiente tranquilo. - Bivolt automático. - Evaporação máxima de 250 ml / hora. - Luz indicadora e Desligamento automático. Recomendações. Para garantir o funcionamento correto do seu umidificador e para manter um ambiente seguro e saudável, siga sempre as recomendações do fabricante e utilize apenas água limpa e potável no aparelho. Esses aparelhos são projetados para dispersar apenas água no ambiente para aumentar a umidade relativa do ar. É extremamente importante não utilizar essências ou qualquer outro produto que não seja água nos umidificadores de ar.', 279.0, 149.0, NULL, 'Home Appliances > Small Household Appliances > Air Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7wf3gabp7o147', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275933522%2F22098389927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
