INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998879917', 'Kit 3 Shampoo Seda Hidratação Diária 325ml', 'Shampoo Seda Hidratação Diária Dê ao seu cabelo o cuidado diário que ele precisa com o Shampoo Seda Hidrat ação Diária. Formulado com o inovador NIA-Nourish Complex, este shampoo não apenas limpa, mas também nutre o cabelo, deixando-o suave e cheio de vida. Sua fórmula contém niacinamida e ajudantes que combatem a caspa, garantindo um couro cabeludo saudável e cabelos livre de impurezas. Ideal para o uso diário, sua textura leve e refrescante proporciona uma experiência revigorante a cada lavagem. Desfrute de cabelos hidratados, soltos e irresistíveis. Faça do seu ritual de beleza uma prioridade e transforme seus cabelos! Experimente a diferença do Shampoo Seda e sinta a vitalidade em cada fio! Modo de usar: Pronta para fazer espuma? Coloque o shampoo nas mãos e aplique-o diretamente nos cabelos. Massageie bem e enxágue.', 41.97, 41.97, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-823pk-mojzw8l72cr324', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23998879917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
