INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23896261304', 'Quebra Cabeça Puzzle Alfabeto - Grow', 'Quebra Cabeça Puzzle Alfabeto - Grow Puzzle Alfabeto é um quebra-cabeça para a criança se divertir enquanto aprende! Possui 26 peças, cada uma composta por uma letra e uma palavra que começa com a mesma. A montagem pode ser feita tanto pela ordem alfabética, quanto pela imagem do fundo, que é contínua. Selo Inmetro: 7908010139426', 34.49, 34.49, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7qvfb-lj5wz3jgazv101', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23896261304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597306674', 'Armário de Cozinha Completa Suspenso 220cm Cinza Nice Madesa 04', 'O Armário de Cozinha Completa Nice da Madesa vai deixar sua cozinha ainda mais especial, com muita modernidade e praticidade. Composto por materiais resistentes e de qualidade superior, este conjunto conta com puxadores em alumínio, corrediças telescópicas para abertura total das gavetas e dobradiças metálicas nas portas. Um detalhe muito interessante é que esta cozinha é suspensa, o que proporciona um visual super atual e facilita a limpeza. Além disso, os módulos são avulsos, formando uma cozinha planejada e que se adapta às necessidades do seu ambiente. O balcão acompanha tampo em MDP, mas é possível remover para instalar uma pia de inox ou pedra, o que confere um toque de sofisticação ao ambiente. Por fim, o acabamento do móvel é cinza, feito em Pintura Poliéster ecológica, que oferece proteção contra a água e o calor. Medidas totais: - 220 cm de largura - 195 cm de altura - 52 cm de profundidade no balcão e na torre e 31 cm no aéreo Itens inclusos: - Um (1) Aéreo de 120 cm com duas (2) portas - Um (1) Balcão de Pia de 120 cm com uma (1) gaveta, três (3) portas e tampo - Um (1) Aéreo de 60 cm com uma (1) porta basculante - Um (1) Paneleiro de 40 cm com duas (2) portas Código do produto: GRNC2200043B Obs.: - Imagens meramente ilustrativas - A Madesa não disponibiliza serviço de montagem - O produto segue com manual e todas as ferragens necessárias para a instalação - A cozinha não acompanha pés, deve ser instalada de forma suspensa, com fixação na parede A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 1689.99, 1369.55, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rcee-lqtdve2lqjbae0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F22597306674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
