INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209786642', 'Chinelo Havaianas Top Bossa - Feminino - Creme', 'As sandálias Havaianas Bossa Feminino são a escolha perfeita para quem busca conforto e estilo durante a primavera e o verão. Feitas em borracha de alta qualidade, elas garantem durabilidade e leveza, permitindo que você caminhe com facilidade em qualquer ocasião. O design elegante e moderno se adapta a diferentes looks, desde os mais casuais até os mais sofisticados. Com uma sola também em borracha, essas sandálias proporcionam uma excelente aderência, tornando-as ideais para passeios na praia ou em ambientes urbanos. A Havaianas é uma marca reconhecida mundialmente por sua tradição e qualidade, e o modelo Bossa não é exceção. Experimente a sensação de conforto que só as Havaianas podem oferecer e adicione um toque especial ao seu guarda-roupa de verão.', 89.99, 89.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-820m3-mnltcusf2goy56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509687760%2F58209786642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598882165', 'Kit Pack 2 Carrinhos Infantil Caminhão Obras Betoneira Giratória e Caçamba Articulada P/ Crianças - Castela', 'DESCRIÇÃO DO PRODUTO Diversão garantida para os pequenos com esse incrível conjunto de 2 caminhões de obra! Os carrinhos possuem design robusto, cores vibrantes e rodas resistentes, perfeitos para criar cenários de construção cheios de imaginação. O que vem no pack: 1 Caminhão Betoneira (Caminhão de Cimento) 1 Caminhão Caçamba (Basculante) Presente perfeito para estimular a imaginação e proporcionar horas de diversão no dia a dia! CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Pak com dois Carrinhos Dimensões Aproximadas do Produto: 10cm x 7 cm x 14 cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 11 cm x 22 cm x 24 cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Plástico Idade Mínima Recomendada: A partir de 3 anos Participantes: A partir de 1 ou mais pessoas Alimentação: Não se aplica Marca: Castela Referência: CBS1223 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 36.99, 27.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820mc-mqyreilxo4xzf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F22598882165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18640716625', 'Escova Para Mamadeira E Bico Cinza 15294 - Buba', 'Escova Resistente De Lavar Mamadeira Com Limpador De Bico Buba A Escova da Buba é ideal para lavar garrafas e mamadeiras, pois atinge áreas difíceis de serem alcançadas. Possui cerdas resistentes e macias que promovem a higiene sem danificar o produto. Ao final de sua haste, a escova possui um limpador de bicos em borracha, um eficiente sistema para a limpeza da parte interna dos bicos de mamadeiras. Consiga uma limpeza profunda e completa com apenas 1 item. Dimensões da Aproximadas da Embalagem: 9 x 12 x 38cm (Altura x Largura x Comprimento/Profundidade)', 30.51, 30.51, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/163a1d52560a694065690a61cbd27505', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F18640716625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
