INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13704828383', 'Jogo Pizzaria Maluca 01283 - Grow', 'DESCRIÇÃO DO PRODUTO Pizzaria Maluca, arregace as mangas e prepare sua pizza o mais rápido possível! Neste divertido jogo, você vai se transformar em um verdadeiro pizzaiolo! Em cada fatia de pizza estão indicados quais os ingredientes necessários para prepará-la . Quem completar sua fatia de pizza primeiro vence o jogo. Mas tome cuidado, pois você pode perder todos os ingredientes! CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 1 tabuleiro, 30 ingredientes (3 de cada tipo), 6 fatias de pizza, 24 cartas de sorte ou azar, 1 peão, 1 dado, 1 regra Dimensões da Embalagem: 35,0 cm X 35,0 cm x 5,5 cm (Altura x Largura x Profundidade) Material: Papel Cartão, Papel, Poliestireno e Polipropileno Idade Mínima Recomendada: 6 Anos Alimentação: Não se aplica Marca: Grow Referência: 01283 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 76.99, 67.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/58feab90e46796abe966b7d0141e4855', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F13704828383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799021223', 'Boneco Elástico Smashers Heróis Laranja - Fun', 'DESCRIÇÃO DO PRODUTO O Smashers Boneco Elástico Heróis Marrom, fabricado pela renomada marca Fun Divirta-se, é um brinquedo inovador projetado para proporcionar horas de entretenimento. Elaborado com materiais elásticos de alta qualidade, garante durabilidade e segurança durante o uso. Com dimensões de aproximadamente 18cm de altura, 8cm de largura e 10cm de comprimento (referente à embalagem), e um peso de 1.21 kg, este boneco é ideal para mãos pequenas e grandes aventuras. Sua natureza elástica permite que as crianças explorem a criatividade, esticando-o de diversas formas e simulando superpoderes, tornando-o uma excelente adição para qualquer coleção de heróis. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Boneco que estica de 1KG Dimensões Aproximadas do Produto: 19 cm x 17 cm x 8 cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 21 cm x 19 cm x 10 cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Elastômero Termoplástico (TPE) Idade Mínima Recomendada: A partir de 3 anos Participantes: A partir de 1 pessoa Alimentação: Não se aplica Marca: Fun Divirta-se Referência: F0233-2 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 136.99, 130.14, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824gc-mfodvbi2f4sr11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F22799021223', NULL, NULL, '2026-07