INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697131539', 'Batom Liquido Bruna Tavares BT Lips Matte 4g', 'Descrição: O batom da linha Bruna Tavares é desenvolvido onde possui suas tendências em buscar cores únicas e em sintonia com a beleza da brasileira, ao mesmo tempo alinhada as tendências internacionais. Tem fórmula cremosa e com acabamento matte, vegana e cruelty free. Seus lábios lindos. Todos os nomes de batons são nomes de mulheres em homenagem as amigas e pessoas próximas. Informações: MODO DE USAR: 1 - Aplique uma camada na parte superior e inferior dos lábios. Espere alguns segundos para a secagem do produto. 2 - Se necessário, aplique uma nova camada, retocando ou intensificando a cor até atingir o efeito desejado. 3 - Para um acabamento perfeito não friccionar os lábios durante a aplicação. Precauções: USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 4ml. Composição: Isododecane, Cyclopentasiloxane, Pentaerythrityl Tetraisostearate, Talc, Silica, Ricinus Communis Seed Oil, Hydrogenated Polycyclopentadiene, VP/Eicosene Copolymer, Disteardimonium Hectorite, Trihydroxystearin, Trimethylsiloxysilicate, Propylene Carbonate, Polyethylene, Phenoxyethanol, Parfum, Cinnamal, Eugenol, Copernicia Cerifera Cera, Caprylyl Glycol, Tocopheryl Acetate, BHT, Tocopherol. Pode conter: Dimethicone/Vinyl Dimethicone Crosspolymer, Caprylic/Capric Triglyceride, Polyglyceryl-3 Diisostearate, Polyglyceryl-4 Isostearate, Lauryl PEG-10 Tris(Trimethylsiloxy)silylethyl Dimethicone, Calcium Sodium Borosilicate, Polyethylene Terephthalate, Synthetic Fluorphlogopite, Hydrogenated Polyisobutene, Palmitic Acid, Tin Oxide, CI 77891, CI 15850, CI77492, CI 77499, CI 77491, CI 77007, CI 77019, CI 42090, CI 15880, CI 77000, CI 47005, CI 12085, CI 45410, CI 45380." #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 39.9, 35.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7reo4-m8kl1z0smf8nb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F21697131539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
