INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19396954022', 'Anti-inflamatório Previcox 227mg 10 Comprimidos Firocoxib', 'A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele! ______________________________________ Composição: Firocoxib Indicações Cães: Anti-inflamatório não esteroide (AINE) indicado para alívio da dor e inflamação associada à osteoartrite ou à procedimentos pós operatórios de tecidos moles. Posologia Administração por via oral, na dose de 5mg/kg de Firocoxib, a cada 24 h. Exemplo: 1 cp de Previcox 57 mg para cada 10 kg de peso, uma vez ao dia 1 cp de Previcox 227 mg para cada 45 kg de peso, uma vez ao dia Observação: Não utilizar em gatos', 301.65, 227.64, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7qve0-lgy35knkfpyn74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F19396954022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798797037', 'Veggiedent Fresh 15 Tiras Caes Pequenos Virbac Saude Oral', 'A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele! ___________________________________ Seu exclusivo formato em Z foi especialment desenvolvido para facilitar a preensão e otimizar a ação mecânica de limpeza durante a mastigação. Modo de usar Recomenda-se oferecer uma tira mastigável ao cão diariamente ou de acordo com as recomendações do Médico Veterinário. Água fresca deve sempre estar disponível ao cão. Composição básica Cães de 5 a 10kg: Cada tira de 16 g contém: Eritritol: 0,112g; Inulina: 0,08g; Extrato de romã: 0,0056g; Veículo q.s.p. 16g Cães acima de 30kg: Cada tira de 35 g contém: Eritritol: 0,245g; Inulina: 0,175g; Extrato de romã: 0,01225g; Veículo q.s.p. 35g Conservação Conservar em local seco e fresco, entre 15º e 30ºC, ao abrigo da luz solar direta e fora do alcance de crianças e animais domésticos. Nestas condições, o produto é válido por 24 meses após a data de fabricação. Vantagens O uso regular de Veggiedent Fr3sh® auxilia na limpeza dos dentes dos cães. Para melhores resultados, recomenda-se oferecer uma tira mastigável ao cão nos dias em que a escovação dos dentes não for possível.', 171.71, 103.03, NULL, 'Pets > Pet Grooming > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7qvfv-ljykptwk88ay7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F18798797037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297313692', 'Boneco Coringa Imaginext Dc Super Friends - Mattel Hhh82', 'Os pequenos fãs de Batman™ podem levar suas batalhas de Super-Heróis contra Supervilões a proporções épicas com esta Fisher-Price® Imaginext® DC Super Friends™ A figura de ação Coringa articulada e extragrande da Imaginext da coleção DC Super Friends possui o icônico traje roxo e verde do personagem. Com o boneco Coringa extragrande de 25 cm de altura e pescoço, ombros, pernas e punhos totalmente articulados, as crianças podem criar suas próprias aventuras vilanescas em Gotham City™ e além! CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Boneco Coringa Imaginext Dc Super Friends Dimensões Aproximadas do Produto: 25 cm x 18,5 cm (Altura x Largura) Dimensões Aproximadas da Embalagem: 10 cm x 20 cm x 29 cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Plástico Idade Mínima Recomendada: A partir de 3 anos Participantes: A partir de 1 pessoa Alimentação: Não se aplica Marca: Mattel Referência: HHH82 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor.', 149.9, 99.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqwa1x1jz9xpe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F23297313692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494311132', 'Shampoo Intense One 24k Controle De Danos C.Kamura 300ml', 'Shampoo Intense One 24K Controle de Danos C.Kamura 300ml O Shampoo Intense One 24K Controle de Danos C.Kamura foi desenvolvido para cabelos danificados por processos químicos, uso de ferramentas térmicas ou agressões ambientais. Enriquecido com micropartículas de ouro 24K e tecnologia reparadora, limpa suavemente enquanto reconstrói a fibra capilar, prevenindo a quebra e restaurando o brilho intenso. Modo de Usar Com os cabelos molhados, aplique o shampoo massageando delicadamente o couro cabeludo até formar espuma. Espalhe por toda a extensão dos fios e deixe agir por 1 a 3 minutos para potencializar a ação reparadora. Enxágue completamente. Use de 2 a 3 vezes por semana ou conforme necessidade do seu nível de dano capilar. Resultado Cabelos mais fortes, com menos pontas duplas e quebra reduzida, sensação de maciez e um brilho radiante de salão. Conheça a Marca C.Kamura, criado pelo renomado hairstylist Celso Kamura, é referência em alta performance capilar. Suas fórmulas combinam ingredientes premium e tecnologia avançada para resultados profissionais no conforto da sua casa.', 62.9, 47.18, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdvo-mdb626ml41183c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577811878%2F22494311132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
