INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096741391', 'Óleo De Banana Beira Alta 90ml', 'Ideal para diluir e reaproveitar os esmaltes que foram ou ficaram abertos por muito tempo ficando mais endurecidos, pois devolve a viscosidade ideal para uso e mantém a perfomance do produto. Modo de uso: Aplicar algumas gotas e agitar bem o esmalte. #html-body [data-pb-style="646BA65529A18"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65529A2D"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 14.5, 14.5, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkzc6glgxpg8f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22096741391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799664776', 'Tênis Calce Fácil Preto: Conforto e Estilo para o Dia a Dia', 'Este tênis infantil da Pé com Pé é a escolha ideal para garantir conforto e estilo no dia a dia das crianças. Com um design moderno na cor preta, é versátil para qualquer ocasião, desde a escola até passeios. A presença de detalhes em rosa no puxador traz um toque de cor e diversão ao modelo. Feito com materiais de alta qualidade, possui uma tira de velcro que facilita o calce e garante ajuste perfeito aos pés pequenos. A sola é robusta e flexível, projetada para suportar a energia das brincadeiras mais animadas. *** ATENÇÃO *** Gentilmente solicitamos, sempre antes da compra, conferir as medidas na tabela abaixo conforme o comprimento do pé da criança. COMO MEDIR: Desenhe o pé da criança em uma folha, risque na posição do começo do calcanhar, e na frente do dedão e utilize a medida entre os dois. TABELA DE MEDIDAS 23 --- 15.0 cm 24 --- 15.8 cm 25 --- 16.2 cm 26 --- 17.1 cm 27 --- 17.7 cm 28 --- 18.3 cm', 119.9, 118.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7kvc5uv1e8221', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208200209%2F21799664776', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53055592752', 'Lixeira de Inox Línea 5L com Pedal Powermaid', 'A Lixeira de Inox Línea 5L da Powermaid é uma solução premium para o descarte de resíduos em banheiros e escritórios. Com design moderno e funcionalidade prática, esta lixeira possui um balde interno removível para facilitar a limpeza e manutenção da higiene. A aderência ventosa garante estabilidade, evitando movimentos indesejados. O pedal em inox proporciona uma operação suave e higiênica, elevando o padrão na gestão de resíduos. Lixeira De Inox Línea 5L Para Banheiro e Escritório A Lixeira Redonda de 5L em Aço Inox da Camesa é projetada para oferecer uma experiência premium na gestão de resíduos. Esta lixeira combina sofisticação com funcionalidade e apresenta um design contemporâneo que se destaca pela estética e eficiência. O balde interno removível facilita a limpeza e manutenção da higiene, proporcionando uma solução prática para o descarte de resíduos. A aderência ventosa incorporada assegura estabilidade, evitando movimentos indesejados e oferecendo confiança durante o uso. O pedal com base em inox adiciona durabilidade e proporciona uma operação suave e higiênica. Ideal para uso na cozinha, banheiro ou escritório, a Lixeira Redonda de 5L da Camesa é uma escolha elegante e funcional para a gestão inteligente de resíduos.', 199.0, 134.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2p1k0xukg04d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F53055592752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998506318', 'BIOFLEXIS COLÁGENO TIPO 2 40MG COM 60 CÁPSULAS', 'Bioflexis é utilizado para: - Ajudar na manutenção da função articular.', 76.13, 76.13, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rfh6-ma07g6zzwlfz35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23998506318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203197638', 'Amend Luxe Creations Blonde Care - Leave-in 180g Blz', 'Leave-in para cabelos loiros coloridos, descoloridos ou com mechas. Amend Luxe Creations Blonde Care Leave-in ajuda no fortalecimento enquanto suaviza o fio. Possui proteção solar e térmica, além de facilitar o pentear. O Leave-in Blonde Care Luxe Creations, da Amend, auxilia na reposição dos aminoácidos perdidos com as agressões químicas para recuperar a resistência e encorpar a fibra capilar. Diminui o aspecto ressecado e traz brilho e maciez ao cabelo. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 43.9, 43.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261a-mjypc3hqzymf07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58203197638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
