INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398203335', 'Cubo Roda Traseiro S/ ABS Peugeot 406 2.0 3.0 (1997 - 2003) Partner 1.8 (1996 - 1998) - IR18991', 'Especificações Técnicas: • Marca: IRB Automotive • Cód. OEM: 3748.43 / 3748.36 / 3748.28 • Posição: Roda Traseira • Para veículo com ABS: Não • Furação: 4 • Dentes / Estrias: • Cód. de similares: 713 6305 30 / AL-978 / AL-987 / B0175 / C11C978 / FWB0008 / HFCT24 / NKF8111 / R159.37 / VKBA 3477 Medidas: • Furo Rolamento (mm): 32 • Diâmetro Cubo (mm): 129 • Largura (mm): 59 Aplicações: - Peugeot 406 2.0 16V / 3.0 V6 24V (1997 – 2003) - Peugeot Partner 1.8 (1996 – 1998) O Cubo de Roda IRB é fabricado em aço forjado, o que significa alta capacidade de suportar cargas pesadas em condições ambientais diversificadas. E desenvolvidos para ter uma ótima performance em qualquer território nacional! IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! A IRB projeta cubos garantindo: - Uma instalação fácil e precisa; - Maior resistência; - Melhor integridade estrutural. Não esqueça de verificar ano, modelo, as quantidades de furos, medidas e se é aplicável em veículos com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 184.9, 174.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma332quedvll19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F18398203335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699889933', 'Usado: Edge 30 Fusion 256GB Preto Excelente - Trocafy - Motorola', 'Celular Seminovo Trocafy A Trocafy é especializada na venda de celulares Recondicionados (Seminovos). Aqui todos os aparelhos passam por revisão minuciosa de técnicos especializados e certificados pelos fabricantes para reparo. Condições: Excelente: Aparelhos com pouquíssimos sinais de uso, risco e/ou arranhões quase imperceptíveis tanto na tela quanto tampa traseira; Muito Bom: Aparelho com alguns sinais de uso como arranhões, riscos e/ou amassados na lateral perceptíveis, porém leves, tanto na tela quanto tampa traseira; Bom: Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Bom Bateria 70%:Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Mínimo da bateria é 70%. IMPORTANTE: - Trabalhamos apenas com PEÇAS ORIGINAIS. Não utilizamos peças alternativas ou paralelas; - Aparelhos DESBLOQUEADOS para todas as operadoras e homologados pela ANATEL; - IMEI verificado garantindo originalidade e procedência legal do aparelho; - Por serem usados, os aparelhos não são resistentes a água (IP68/IP67); - Não acompanha acessórios; - NOTA FISCAL - Emitida em nome do comprador; GARANTIA - Aceita devoluções por arrependimento em até sete (7) dias corridos após o recebimento do pedido. Oferece 90 dias de garantia contra defeitos técnicos. CONTEÚDO EMBALAGEM: Aparelho adquirido em uma caixa personalizada da Trocafy;', 1479.0, 1405.05, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mf02uj84t2x72a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.