INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255063649', 'Lente Retrovisor Convexo Clio Symbol 2000 a 2013 Sem Base', 'Lente Retrovisor Convexo Clio Symbol 2000 a 2013 Sem Base ***ATENÇÃO: SOMENTE A LENTE (VIDRO)*** • Não acompanha moldura plástica • Não acompanha motor elétrico • Deve ser fixado com fita dupla face ou adesivo de silicone neutro ESPECIFICAÇÕES TÉCNICAS: • Lado Direito e Esquerdo: Lente CONVEXA o Amplia o campo de visão, eliminando pontos cegos. COMPATIBILIDADE: • Renault Clio (Hatch e Sedan) 2000 a 2012 o Versões: Authentique, Expression, Dynamique, Privilège, Campus • Renault Symbol 2009 a 2013 ***NÃO SERVE*** • Não serve no Clio G1 (Anos 90) SELECIONE A VARIAÇÃO QUE DESEJA: • Lado Esquerdo (Motorista): Lente Convexa • Lado Direito (Passageiro): Lente Convexa • Par (Direito + Esquerdo) INSTALAÇÃO: 1. Retire o vidro antigo com cuidado 2. Limpe a base plástica com álcool 3. Recomendamos a fixação com Silicone Neutro 4. Centralize a lente e prenda com fiat por 24h até a secagem OBS: Não serve para colar por cima do vidro antigo _______________________________________________________________________ Não nos responsabilizamos pela má instalação ou mau uso do produto.', 39.73, 39.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-81ztn-mklalxtvorgh45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1254320229%2F58255063649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
