INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10601174108', 'Kit 3 Máscaras Para Cilios Multi Effect Preta Phállebeauty PH0306', 'A Máscara para Cílios Multi Effects da Phallebeauty é um incrível lançamento que vai deixar seus cílios bem definidos. São três pincéis diferentes que servem para dar volume, curvatura, alongamento e definição. A marca lançou três versões para ninguém colocar defeito. São elas: - Volume e Curvatura. - Alonga e Define. - Volume e Definição. - Volume e Definição: Proporciona máximo volume, aliado a difinição dos fios, permitindo cílios mais cheios e com maior destaque. - Alonga e Define: Define e alonga os seus cílios, alcança todos os fios desde a raiz. - Volume e Curvatura: Proporciona máximo volume, aliado a curvatura dos fios dos cílios, permitindo um cílios mais cheio e com maior destaque. Kit Contém 3 Máscaras Para Cílios Multi Effect Phállebeauty', 39.99, 39.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/8f6bb6c85adee067bec2063f5f7459c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F10601174108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
