INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19357608476', 'Aparador Buffet 4 portas Viena Multimóveis Branco/Natural', 'O Aparador Buffet 4 portas Viena Multimóveis é produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, facilidade na limpeza, além de um acabamento superior. Com 4 portas e puxadores em madeira, possui um excelente espaço interno para organizar seus pertences (as prateleiras internas suportam 5 Kg cada e o tampo 10 Kg). Seu design minimalista, torna o móvel muito versátil, podendo ser utilizado de diversas maneiras e em qualquer ambiente. Conteúdo da Embalagem: 1 (um) aparador 1 (um) kit com 4 puxadores Dimensões do produto montado: Altura: 69,5cm | Largura: 123cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. *Obrigatório fixar na parede. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 599.9, 459.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-o4krb4qg44ivf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19357608476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
