INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209457193', 'D''aucy Couve-Flor Congelada', 'A Couve-Flor Congelada D''aucy é perfeita para quem busca praticidade e saúde na cozinha. Já vem em floretes, pronta para usar em diversas receitas, desde sopas e purês até gratinados e acompanhamentos. * Produto congelado in natura. * Não contém glúten, aromatizantes ou corantes artificiais. * Serve até três pessoas. Conserve no freezer e aproveite a versatilidade da couve-flor em suas refeições!', 8.49, 8.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqnekmeudsld5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58209457193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
