INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21249990535', 'Kit Relacao Tracao Transmissao Nxr Bros 160 Xre 190 2015 2016 2017 2018 2019 2020 2021 2022 2023 Com Retentor Original Kmc', 'KIT RELACAO COMPLETO NXR BROS 160 / XRE 190 (COROA/PINHAO E CORRENTE COM RETENTOR) - OFERTA LANCAMENTO!!! NOVO NA CAIXA - ORIGINAL KMC PRINCIPAIS APLICACOES: MOTOS: HONDA NXR BROS 160 ANO: 2015 A 2022 MOTOS: HONDA XRE 190 ANO: 2015 A 2022 *Aco 1045 *Corrente 428HX128L (COM RETENTOR) *48 dentes da coroa *16 dentes do pinhao Funcao da Coroa e do Pinhao: A Coroa e o Pinhao juntamente com a corrente sao conhecidos como kit relacao, e sao fundamentais para uma pilotagem segura, sendo responsaveis por transmitir o movimento da saida da transmissao ate a roda traseira. Como detectar problemas? Verifique se ha desgastes nos dentes da coroa e do pinhao. Ao trocar verifique tambem: o ideal e realizar a troca do kit inteiro (coroa, pinhao e corrente com retentor) para garantir a durabilidade do conjunto, ruidos e folga na transmissao de forca. Diferenciais: Produzida em aco 1045 Endurecimento termico para aumentar a resistencia e durabilidade Numero de dentes conforme padrao original Dentes tratados termicamente ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 228.0, 176.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/8e281fd3e7e7fd83094a6bec677495fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445101258%2F21249990535', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
