INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44230419015', 'Pampers Condicionador de Glicerina 200ml', 'Condicionador de Glicerina desembaraça com facilidade os fios e condiciona de forma suave e segura! O Condicionador de Glicerina Pampers foi criado pensando em desembaraçar com facilidade os fios e condicionar de forma suave e segura. Sua composição não contém nenhum álcool etílico, fenoxietanol, parabenos e corantes, trazendo maior suavidade e mantendo os fios do seu neném macios. Benefícios: Seguro desde os primeiros dias. Condiciona com suavidade. Hipoalergênico. 97% de ingredientes naturais. Sem lágrimas. pH ideal para o cabelo do bebê. Perfumação suave, segura para recém-nascidos. Fórmula biodegradável, vegana e livre de crueldade animal. Para todos os tipos de cabelo, seguro até para pele sensível. Testado, aprovado e recomendado por pediatras e dermatologistas. Modo de Uso: Coloque um pouco do condicionador ao longo dos fios e espalhe pelo cabelinho molhado do seu bebê durante o banho. Desembarace com facilidade deixando agir por alguns minutos. Enxágue bem em seguida com água. Orientações ao Consumidor: Este produto foi formulado de maneira a minimizar possível surgimento de alergia. Evitar contato com os olhos. Deve ser aplicado por adulto ou sob sua supervisão. Não usar se o couro cabeludo estiver ferido ou irritado. Em caso de irritação, suspender o uso e procurar um médico. Caso o produto entre em contato com os olhos, lavar com água corrente em abundância e procurar um médico.', 25.43, 25.43, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-820m5-mnkforsz0idh3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F44230419015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11948040498', 'Kit 2 Desodorantes Dove Men+Care Antitranspirante Aerossol Sem Perfume 150ml', 'Kit 2 Desodorantes Dove Men+Care Antitranspirante Aerossol Sem Perfume 150ml Seu antitranspirante não precisa competir com seu perfume, contanto que combata o suor com eficiência e por bastante tempo. Pensando nisto foi lançado o Dove MEN+CARE Sem Perfume, que garante proteção avançada por 48 horas e não irrita a pele. Sua fórmula exclusiva não libera odor, deixando o trabalho para o perfume de sua preferência. A aplicação deve ser feita apenas nas axilas. Esqueça de vez os antitranspirantes comuns e fique com Dove MEN+CARE Sem Perfume! O Kit contém: 2 Desodorantes Dove Men+Care Antitranspirante Aerossol Sem Perfume 150ml cada. *Compre Produtos Dove.', 52.29, 43.72, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/66918f86b83b3b5e697eba6d52d6e952', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11948040498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
