INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10247915079', 'Desodorante Antitranspirante Rexona Feminino Invisible 150ml', '•O Desodorante Antitranspirante Aerosol Feminino Rexona Invisible possui nova fórmula com 72 horas de proteção contra a transpiração e o mau odor, ativada pelo movimento •A fórmula do Antitranspirante Aerosol Feminino Rexona Invisible é 0% álcool etílico, e possui tecnologia que protege a sua roupa contra manchas brancas e amarelas •Agite antes de usar. Aplicar o Desodorante Feminino Rexona Invisible somente nas axilas a não menos de 15 cm da pele •O novo desodorante feminino Rexona responde diretamente ao seu movimento, mantendo você seca, fresca e protegida como nunca •Este desodorante aerosol não afeta a camada de ozônio, possui lata em alumínio 100% reciclável e é feito com energia elétrica 100% renovável •Antitranspirante que mantém você seca, fresca e protegida a cada novo movimento e por muito mais tempo. Rexona não te abandona. Mais uma vez Rexona se supera e relança sua linha de desodorantes com uma fórmula inovadora, que combina um novo e exclusivo ativo antitranspirante com a tecnologia de fragrâncias encapsuladas. O resultado? O Desodorante Antitranspirante Aerosol Feminino Rexona Invisible garante 72 horas de proteção ativada pelo seu movimento e muito mais confiança para você encarar qualquer desafio. Com o registro de 16 patentes e mais de 300 testes técnicos, está comprovado que essa nova tecnologia antitranspirante entrega um nível de proteção contra o suor como nenhuma outra proposta regular já entregou antes. A nova e exclusiva fórmula de Rexona Invisible trabalha com um sistema de partículas menores e mais estáveis, que formam uma barreira protetora mais resistente e duradoura contra a transpiração e o mau odor, mantendo você seca, fresca e protegida a cada novo movimento e por muito mais tempo. Este desodorante aerosol não afeta a camada de ozônio, possui lata em alumínio 100% reciclável e é feito com energia elétrica 100% renovável. Modo de usar: Agite antes de usar. Aplicar somente nas axilas a não menos de 15 cm da pele. Sua fórmula é 0% álcool etílico, e possui tecnologia que protege a sua roupa contra manchas brancas e amarelas. Por que Rexona não te abandona.', 25.84, 25.84, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-m0oy5oqpb2ha4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10247915079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
