INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42806307944', 'Jogo De Toalha Buddemeyer 4 peças 100% Algodão Grossa Aveludada 430g/m² Geo', '🛁 Jogo de Toalhas Buddemeyer Geo – 4 Peças (Banho + Rosto) 🌿 100% Algodão | Toque Aveludado | Design Sofisticado Transforme seu momento de cuidado diário em uma experiência de puro conforto e elegância com o Jogo de Toalhas Buddemeyer Geo. Composto por 2 toalha de banho (70x135cm) e 2 toalha de rosto (48x80cm), esse conjunto reúne luxo, maciez e alta absorção em cada fio. ✨ Destaques do Produto: ✔️ Toque aveludado e delicado, que envolve a pele com aconchego incomparável ✔️ Design exclusivo em jacquard, com arabescos e efeito rendado de tirar o fôlego ✔️ Super absorvente e volumosa, perfeita para um pós-banho relaxante ✔️ Brilho natural e acabamento premium, com a qualidade reconhecida da Buddemeyer 📦 Conteúdo da Embalagem: 2 Toalha de Banho – 70x135cm 2 Toalha de Rosto – 48x80cm 🌱 Composição: 100% Algodão de alta qualidade, pensado para proporcionar durabilidade e suavidade 🛍️ Ideal para quem busca aliar sofisticação ao dia a dia, seja para uso pessoal, presentear ou compor o enxoval com estilo. Aposte na Buddemeyer e sinta a diferença desde o primeiro toque!', 319.9, 189.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbgzqh36t68yea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356841149%2F42806307944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297754858', 'Kit Cobre Leito Colcha Bouclê King Laise Bordada Micropercal 200 Fios 3 Peças - Branco Neve', 'Kit Cobre Leito Colcha Bouclê King Laise Bordada Micropercal 200 Fios 3 Peças - Branco Neve Transforme seu quarto em um ambiente sofisticado e aconchegante com o nosso Kit Cobre Leito Bouclê. Confeccionado em tecido Micropercal de 200 fios, oferece uma sensação de suavidade incomparável e durabilidade superior. O detalhe em laise bordado traz um toque de elegância, enquanto o matelado ultrasônico uma tecnologia inovadora que utiliza calor em vez de linha garante um acabamento impecável e uniforme. Ideal para quem busca conforto e estilo em um só produto, este kit é a escolha perfeita para renovar a decoração do seu quarto com muito charme e requinte. Tecido: Micropercal 200 fios, toque macio e aveludado. Laise Bordada: Design delicado e sofisticado, bordado a quente para maior durabilidade. Matelado Ultrassônico: Acabamento impecável e toque suave. Exclusividade: Design único e elegante, perfeito para quem busca um toque especial na decoração. Contém na embalagem: 01 Cobre Leito 2,80m x 2,60m 02 Portas Travesseiro 70cm x 50cm Composição: Tecido Superior e Inferior: 100% Poliéster Enchimento: 100% Poliéster As fotos são meramente ilustrativas. As cores podem variar de acordo com cada monitor e não representam todas as peças que compõem a descrição do produto. Fique atento à descrição do produto.', 297.05, 297.05, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-lzrn538f47wm0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23297754858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
