INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23891551040', 'Ferro de Passar a vapor Titanium Ceramic Philco PFV3200V', 'Deslizando sobre as roupas com mais facilidade e tirando vincos, o Ferro de Passar a vapor Titanium Ceramic Philco PFV3200V, ajuda a otimizar seu tempo nas tarefas de cuidado com as roupas! Ele tem base de Nano Ceramic e se move com mais facilidade sobre o tecido, além de ser mais resistente a riscos. Tem função Vapor Extra e jato de Vapor e 93 saídas de vapor, que desamassa a roupa com mais facilidade e faz com que o ferro elétrico possa ser usado na posição vertical, direto no cabide, inclusive pela mobilidade do cabo emborrachado e giratório de 1,60m. Equipado com função antigotejamento, ele evita as indesejáveis gotas de água na roupa mesmo em temperaturas mais baixas. Tudo isso, com um design moderno e detalhes em inox. Ferro de Passar a vapor Titanium Ceramic Philco PFV3200V, praticidade e eficiência para facilitar seus dias! • Base cerâmica • Função anti-gotejamento • Função vapor • Função jato extra de vapor • 93 saídas de vapor • Vapor vertical • Tanque com capacidade para 300ml • Função auto-limpeza • Copo dosador • Cordão emborrachado • Cordão elétrico com 1,60M • Salva-botões • Luz indicadora de funcionamento.', 279.9, 279.9, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/sg-11134201-823ov-mord98xj09otca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F23891551040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209453355', 'Energético Natural SEDE com Cafeína Microencapsulada', 'SEDE é um energético natural e funcional que combina bem-estar, foco e disposição em uma fórmula 99,72% natural, com apenas 55 kcal por lata e adoçado com suco de maçã. Sem conservantes nem aditivos artificiais, com 100mg de cafeína microencapsulada, garante energia limpa, gradual e sustentada. Lata de 250ml.', 10.49, 10.49, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mqxn6j13dqtif6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F58209453355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
