INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11761999505', 'Taça de Vidro Haste Vermelha Margarita para Drink 385ml - Ruvolo', 'Com um toque vibrante e único, a Taça de Vidro Haste Vermelha Margarita 385ml é a opção perfeita para quem busca elegância e estilo ao servir drinks. Sua haste vermelha confere um charme especial, tornando-a um destaque em qualquer ocasião. Ideal para margaritas e outros coquetéis, essa taça oferece 385ml de capacidade, proporcionando um equilíbrio perfeito entre sofisticação e funcionalidade. A Taça de Vidro Haste Vermelha Margarita é uma excelente escolha para transformar seus momentos de celebração em experiências memoráveis. Material: Vidro. Dica de uso e preservação: • Recomendamos que a limpeza da peça seja feita a mão para evitar quebras ou danos. • Limpe a sujeira utilizando uma esponja macia, tire o resíduo de sabão e seque bem. • Não utilize abrasivos ou utensílios pontiagudos. • Evite impactos e não exponha o vidro a mudanças bruscas de temperatura pois poderá causar choque térmico e danificar seu produto. • Para realçar ainda mais o brilho das peças, limpe-as com uma flanela que não solte fiapos, levemente umedecida com álcool.', 34.9, 34.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9zyfv0cnl8993', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F11761999505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
