INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799880868', 'Tinta Spray Tekbond Uso Geral Platina 350ml', 'Características Principais: Marca: Tekbond Cor: Platina Litragem: 350 ml Peso: 250 g Informações adicionais: Tipo de tinta: Acrílica Rendimento: Aproximadamente 1,7 m² a 2,1 m² por embalagem Indicação de uso: Ambientes internos e externos Resistência: Condições climáticas extremas Aplicação: Requer uso de Primer Spray para metais com ou sem oxidação Acabamento: Excelente cobertura e alta durabilidade Aplicação: Ferro, aço, madeira, cerâmica, gesso e outros materiais Secagem: Rápida Modo de uso: Limpe a superfície removendo restos de pintura, ferrugem, gordura e poeira. Proteja áreas que não serão pintadas com papel ou plástico. Utilize Primer Spray em metais, lixando com lixa d¿água 400 após secagem. Agite bem a lata antes e durante a aplicação. Aplique de 2 a 3 demãos, aguardando 4 a 9 minutos entre elas. Tempo de secagem: 30 minutos ao toque, 3 horas para manuseio e 24 horas para resistência total. Armazenamento: Não armazenar acima de 50°C. Mantenha em local ventilado, seco e protegido de fontes de ignição. Armazene a lata em pé. Fornecedor: Atb ind. e com.de adesivos S.A', 25.39, 12.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gd-mpibplktg1dsb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F18799880868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
