INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298923657', 'Disco de Corte 75mm Tipo 41 para Metal e Inox DCV Vonder', 'O Disco de Corte 75 mm DCV Tipo 41 Vonder é indicado para cortes em metais, inclusive aço inox, proporcionando cortes rápidos, precisos e com menor geração de calor e rebarbas. É ideal para uso em cortadores pneumáticos, oferecendo bom desempenho em aplicações profissionais e de manutenção. Possui 2 telas de reforço, grão G46 e rotação máxima de 20.300 rpm. Diferenciais do Produto ✅ Indicado para corte de metais e aço inox ✅ Proporciona cortes rápidos e eficientes ✅ Menor geração de calor durante o corte ✅ Reduz a formação de rebarbas ✅ Tipo 41, ideal para cortes retos ✅ Possui 2 telas de reforço para maior segurança ✅ Utilizado em cortadores pneumáticos ✅ Segue as normas ABNT NBR 15230 e ABNT NBR 16245 Detalhes Técnicos Marca: Vonder Modelo: DCV Tipo de produto: Disco de corte Diâmetro do disco: 75 mm Espessura: 1,4 mm (+/- 1/16") Tipo de disco: Tipo 41 Diâmetro do furo: 10 mm Grão: G46 Número de telas: 2 Rotação máxima: 20.300 rpm Normas: ABNT NBR 15230 e ABNT NBR 16245 Conteúdo da embalagem: 1 Disco de corte Atenção: Não utilizar em serra mármore.', 20.0, 8.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824i5-mek0mz6qza4l8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F22298923657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
