INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40357789551', 'Meia Infantil Menina Rendinha Batizado Bege', 'Meia Infantil Menina Rendinha Batizado Off White As meias de Rendinha da Pequito são um verdadeiro amor nos pés! O detalhe na bainha com renda da um toque de luxo aos pezinhos de nossas pequenas! A Meia Rendinha Batizado da Pequito possui aplique de lacinho e renda. Oferece o conforto e proteção ideal para os pezinhos das nossas meninas. Aconchego para os pezinhos e delicadeza nos detalhes! A Meia Menina Rendinha Batizado Rosa vai encantar você e sua pequena. Seus detalhes em renda são uma verdadeira graça e conferem um toque clássico à meia, é pura meiguice! Produzida com materiais de alta qualidade e dispondo de um acabamento diferenciado, ela se ajusta bem aos pezinhos. Confira também as outras opções que temos disponíveis. A meia tem 3 variações de tamanhos: 16 ao 19 20 ao 22 23 ao 25 Composição: 70% algodão - 28% poliamida - 2% elastano. Meia Infantil Menina Rendinha Batizado Off White - Características Gerais do Produto: • Faixa Etária: Baby - até 2 anos (16 a 22); Pré Infantil - até 6 anos (20 ao 27); Infantil - até 7 anos (23 ao 32) • Gênero: Menina • Material Externo: Textil • Cor: Off White Acompanha o produto: • 1 Par de Meia • 1 Embalagem. Garantia: • Garantia de Fábrica', 27.9, 26.6, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Socks', 'https://cf.shopee.com.br/file/br-11134201-820lc-mqy6qt1you1098', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386057181%2F40357789551', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
