INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893704172', 'CHUMBINHO TECHNOGUN VETOR OLÍMPICO 14,24 GR 250UN. 5.5MM + PORTA CHUMBINHOS', 'Produto de uso exclusivo em práticas esportivas. ESPECIFICAÇÕES TÉCNICAS DO CHUMBINHO: - Marca: Technogun - Calibre: 5.5mm (.22) - Modelo: Vetor Olímpico - Material: Chumbo - Quantidade: 250 unidades cada - Peso: 0,95 gramas - Gramatura: 14,74 grains - Comprimento: 6,9mm ESPECIFICAÇÕES TÉCNICAS DO PORTA CHUMBINHOS: - Marca: Ar15 Sport - Material: E.V.A - Calibre: 5.5mm (.22) - Capacidade: 50 munições - Fixação: Através de velcro - Aplicação: Coronha ou pulso - Dimensões: 6,5mm x 65,0mm x 109,0mm - Peso total: 1 gramas ITENS INCLUSOS: - 01 Lata de Chumbinho Technogun Vetor Olímpico 5.5mm 250un. - 01 Porta Chumbinho Ar15 Sport Calibre 5.5mm Observação: Garantia de 03 meses mediante defeitos de fábrica. INFORMAÇÃO: Os equipamentos, peças e acessórios aqui listados são de uso exclusivo em armas de pressão (gás comprimido ou mola), airsoft, paintball, esferas plásticas (BBS) e estão em conformidade com a legislação brasileira de USO PERMITIDO "É permitido o uso de armas de pressão por ação de gás comprimido ou por ação de mola, com calibre igual ou inferior a seis milímetros (6mm ou 6.0mm), e das que lançam esferas de plástico com tinta, como os lançadores de paintball." Conforme parágrafo único do Art. 11 do DECRETO Nº 11.615, DE 21 DE JULHO DE 2023. A venda desses itens é feita somente para maiores de 18 anos mediante a comprovação de maior idade. Atenção: O envio de Armas de pressão e Airsoft é realizado somente por transportadora. Caso tenham dúvidas entrar em contato.', 100.82, 100.82, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rcdy-m667qsldh2oaa7', 'https://shope.ee/an_redir?origin_link=