INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51110309725', 'Cereal Sucrilhos Original 690g', 'Sucrilhos® original da Kellogg\''s® é feito com milho de verdade, é crocante e delicioso a cada colherada. Contém 4 vitaminas do complexo B, vitamina D e ferro, que podem contribuir para um adequado desempenho físico e energético, quando associados a uma alimentação equilibrada e a prática de atividade física. Desfrute do seu sabor de cereal matinal favorito para vencer com garra e energia! Há diversas opções para compor os lanches, como as frutas que podem fornecer fibras, vitaminas e minerais, o leite ou iogurte que fornecem proteínas e cálcio e os cereais como os pães e biscoitos que fornecem carboidratos, dão energia e são alternativas interessantes e deliciosas para fazer parte deste momento, especialmente no Café da Manhã.', 21.99, 21.99, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/sg-11134201-820mn-mo457489ik923e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F51110309725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
