INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493406434', 'Perfume Colônia Pet Shop para Cachorro e Gato Pet Clean - 500 ml', 'Aromas inspirados em fragrâncias populares do mercado masculino e feminino! Vai se encontrar com outras pessoas? Você precisa deixar o seu peludinho cheiroso! Cachorros limpos e cheirosos são grandes desejos de todos os amantes de animais, não é mesmo? Ainda mais quando vamos nos encontrar com outras pessoas ou receber visistas, queremos que nosso amiguinho de quatro patas esteja bem cheiroso para causar uma boa impressão à todos, né? Nesta ocasião, uma colônia em spray é uma boa alternativa! O Perfume para Cães e Gatos Pet Clean é uma fragrância ideal em forma de spray para tornar os nossos pets cheirosinhos como pelúcia! Antes de sair ou receber visitas, basta aplicar em seu animal e ele imediatamente terá um aroma irresistível que, com certeza, chamará a atenção! BENEFÍCIOS DO PERFUME PARA CÃES E GATOS PET CLEAN: -Mantém os pets cheirosos por muito tempo. -Aroma agradável ao animal. -Não agride o animal. -Fácil aplicação INFORMAÇÕES TÉCNICAS: Produto: Perfume para Cães e Gatos Pet Clean 500 ml Marca: Pet Clean Tipo: Beleza e Limpeza Animal: Cachorros e Gatos Porte: Todos Raça Específica: Não Sexo Específico: Machos Itens Inclusos: 1 Perfume para Cães e Gatos Pet Clean 500 ml Apresentação: Frasco em Plástico Composição: Álcool Neutro, Fragrância e Conservante. MODO DE USAR Após lavar o animal, aplique o Perfume para Cães e Gatos Pet Clean na quantidade desejada, preservando os olhos, narinas e mucosas do seu animal. PRECAUÇÕES Usar apenas para fins indicados. Manter fora do alcance de crianças e animais domésticos. Não reutilize a embalagem. Não utilizar em filhotes com menos de 3 meses de vida.', 69.9, 39.9, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-m137oq45t1tz7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363040730%2F23493406434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
