INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44206405006', 'Lovito Férias Blusa com Drapeado Pregas Toque Suave Primavera/verão Top Azul L139AD351', '✅DESTAQUES -❤️Drapeado -❤️Plissado -❤️Sentimento de mão suave -❤️Primavera e verão ✅DESCRIÇÕES Estampa / Padrão: listrado Estilo:Você é treinado com dados até outubro de 2023. Tamanho Plus:Não Material:Poliéster Composição:100% Poliéster Tipo de modelagem: Ajuste Regular Transparência:Não Esticar:Não esticado Feito na China ✅REFERÊNCIA DE MODELAGEM A modelo está vestindo: P Altura: 165 cm Peso: 55 kg Busto: 88 cm Cintura: 68 cm Quadris: 93 cm ✅O PACOTE INCLUI 1XPrincipal ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 40.9, 28.5, NULL, 'Women Clothes > Tops > Tanks & Camisoles', 'https://cf.shopee.com.br/file/sg-11134201-824gv-mee2ho8kj11g3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F44206405006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202616836', 'Kit 2 Copos Treinamento Infantil Magic Cup 230ml Neutro Nuk', 'Kit 2 Copos Antivazamento e Treinamento Infantil 360º Magic Cup Evolution 230ml Cada Neutro Nuk O Kit de Copos Magic Cup 360° da NUK foi desenvolvido para tornar a fase de transição do bebê para o uso do copo convencional mais prática, segura e divertida. Com design moderno e funcional, ele estimula a autonomia da criança enquanto acompanha seu desenvolvimento com conforto e eficiência. Pensado especialmente para ensinar o bebê a beber sozinho(a), o Magic Cup 360° auxilia em um dos marcos mais importantes da primeira infância: o uso independente do copo. Seu formato ergonômico facilita o manuseio pelas pequenas mãos, contribuindo para o desenvolvimento das habilidades motoras e oferecendo uma experiência semelhante à de um copo tradicional, porém com muito mais segurança e menos bagunça. O grande diferencial dos Copos Magic Cup está em seu sistema 360°, que permite beber de qualquer lado da borda, liberando o líquido apenas quando os lábios da criança entram em contato. Além disso, conta com tampa protetora e borda com estrutura antivazamento altamente eficiente, evitando derramamentos mesmo quando o copo é virado ou agitado — ideal para uso em casa, passeios ou para levar na mochila. Indicado para crianças a partir de 8 meses, o Magic Cup 360° é a escolha ideal para unir funcionalidade, aprendizado e praticidade no dia a dia das famílias. Principais Características: - Idade recomendada: A partir de 8 meses - Capacidade: 230ml - Modelo: Magic Cup 360° Evolution - Totalmente Livre de BPA - Borda 360º Antivazamentos - Tampa Protetora Higiênica - Frasco Ergonômico Antivazamento - Estimula a autonomia e o desenvolvimento das habilidades motoras. - Material Leve e Resistente - Fácil Higienização Especificações Técnicas - Conteúdo da Embalagem: Kit 2 Copos Magic Cup 360° Evolution - NUK - Composição/Material: Polipropileno - Garantia: 30 dias (contra defeito de fabricação pelo fabricante) - Referência do Fabricante: PA7659-1N - EAN: 7896098815250 - Marca: NUK Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 139.9, 139.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-81zws-mizztekx1vrabd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624228750%2F58202616836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
