INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397680627', 'Reservatório Água Radiador Fiesta 1.0/1.6 Ecosport 1.6/2.0 2 Saídas', 'ATENÇÃO TIRE TODAS AS DÚVIDAS ANTES DE EFETUAR A COMPRA! CONFIRME QUANTOS ***BICOS*** TEM O RESERVATÓRIO QUE ESTÁ NO CARRO, SE TEM OU NÃO ***SENSOR***, EVITANDO ASSIM COMPRAR O PRODUTO ERRADO E FICAR MAIS TEMPO COM O VEÍCULO PARADO. TIRE SUAS DÚVIDAS NO CAMPO DE COMENTÁRIOS ANTES DE REALIZAR A COMPRA. DESSA FORMA EVITAMOS O TRANSTORNO DE PEÇAS INCORRETAS / DEVOLUÇÕES. --------------------------- CONTEUDO DA EMBALAGEM: 01 (UM) RESERVATÓRIO EXPANSÃO SEM TAMPA ESSE ANÚNCIO VAI SEM TAMPA --------------------------- ESPECIFICACAO DO PRODUTO: RESERVATÓRIO EXPANSÃO / RADIADOR MARCA:GONEL CODIGO DO PRODUTO: G-1114 QUANTIDADE DE SAÍDAS: 2 SAÍDAS --------------------------- MONTADORA FORD NÃO SERVE EM MODELOS COM 3 SAÍDAS --------------------------- VEICULOS COMPATIVEIS: - FIESTA E FIESTA SEDAN 1.0/1.6 - DE 2003 ATÉ 2013 - ECOSPORT 1.6/2.0 - DE 2003 ATÉ 2012 ******** NÃO SERVE EM MODELOS COM 3 SAÍDAS ******** ******** NÃO SERVE EM MODELOS COM 3 SAÍDAS ******** ******** NÃO SERVE EM MODELOS COM 3 SAÍDAS ******** --------------------------- TAG 256.58K.218.BA --------------------------- - GARANTIA E/OU DEVOLUÇÃO: O PRODUTO É NOVO E COM GARANTIA TOTAL POR NOSSO FORNECEDOR. PARA ISSO GUARDE A NFE QUE EMITIREMOS COM OS DADOS DO USUÁRIO QUE EFETUOU A COMPRA. - NÃO FAZEMOS TROCAS, APENAS DEVOLUÇÕES, QUE SÓ SERÁ POSSÍVEL CASO A EMBALAGEM NÃO TENHA SIDO RASGADA E NEM A PEÇA DANIFICADA. - ESSA GARANTIA NÃO COBRE MAL USO. --------------------------- NÃO NOS RESPONSABILIZAMOS POR DEFEITOS OCORRIDOS POR MÁ INSTALAÇÃO DO PRODUTO. TODO O PRODUTO DEVE SER INSTALADO POR UM PROFISSIONAL QUALIFICADO. AS COMPRAS REALIZADAS EM NOME DE PESSOA JURÍDICA ESTÃO SUJEITAS À COBRANÇA DE ICMS, CONFORME PROTOCOLO ICMS 41, DE 4 DE ABRIL DE 2008. CASO VOCÊ TENHA DÚVIDAS SOBRE O PERCENTUAL A SER APLICADO, CONSULTE A CLÁUSULA SEGUNDA, §1° DO REFERIDO PROTOCOLO. FOTOS MERAMENTE ILUSTRATIVAS --------------------------- SOBRE A EMPRESA SOMOS UMA EMPRESA ESPECIALIZADA NA VENDA DE PEÇAS AUTOMOTIVAS, COM AMPLA EXPERIÊNCIA NO MERCADO E COMPROMISSO COM A SATISFAÇÃO DE NOSSOS CLIENTES. TRABALHAMOS APENAS COM PRODUTOS NOVOS, DE QUALIDADE E PROCEDÊNCIA GARANTIDA, OFERECENDO SEGURANÇA E CONFIABILIDADE EM CADA COMPRA. NOSSO OBJETIVO É PROPORCIONAR UM ATENDIMENTO ÁGIL, TRANSPARENTE E DE EXCELÊNCIA. EM CASO DE DÚVIDAS, ENTRE EM CONTATO COM A NOSSA EQUIPE — SERÁ UM PRAZER TE ATENDER!', 99.0, 68.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra3v-m4j7fdvdhgrf34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418319912%2F18397680627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
