INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799306850', 'Óleo De Semente De Abóbora 1000Mg Com 120 Cápsulas', '• O Aliado Natural para a Saúde Masculina: O Óleo de Semente de Abóbora é um suplemento rico em nutrientes e antioxidantes, reconhecido principalmente por seus benefícios para a saúde da próstata e do sistema urinário masculino. • Saúde da Próstata: Estudos sugerem que o consumo do óleo de semente de abóbora pode auxiliar na manutenção da saúde da próstata e no alívio dos sintomas da Hiperplasia Prostática Benigna (HPB). • Rico em Nutrientes: Fonte de Zinco, Magnésio, Triptofano e gorduras boas (ômega 6 e 9), que contribuem para a saúde do coração e para o bem-estar geral. • Alta Concentração: Cada cápsula softgel contém 1000mg de óleo puro, prensado a frio para preservar todas as suas propriedades. • Palavras-chave: Óleo de Semente de Abóbora, Próstata, HPB, Saúde do Homem, Zinco, Suplemento.', 101.13, 101.13, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd4q-lvvvpudgdbp768', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F21799306850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
