INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698296287', 'Sandália Campesí de Salto Bloco Feminina CE141', 'Produto marca Campesí. Apresentamos a Sandália Campesí de Salto Bloco, um verdadeiro ícone de versatilidade e estilo para a mulher moderna que busca conforto e elegância em cada passo. Com um design minimalista e sofisticado, este modelo é a escolha perfeita para o seu dia a dia e momentos de lazer, garantindo que você se sinta confiante e pode. o destaque fica por conta da fivela metalizada na parte frontal, um detalhe sutil que eleva o visual e demonstra um cuidado impecável com o acabamento. a tira no tornozelo com fechamento por fivela oferece um ajuste seguro e preciso, unindo praticidade e charme. Confeccionada em material sintético de alta qualidade e com um peso de apenas 0,580 kg, a sandália proporciona uma experiência de uso leve e agradável. o salto bloco de 5,50 cm é o segredo para unir a elegância do salto alto com a estabilidade e o conforto que você precisa para longas jornadas. Sinta a diferença de um calçado que não apenas complementa seu estilo, mas também cuida do seu bem-estar. Não perca a oportunidade de ter em seu guarda-roupa uma peça que se adapta a diversas ocasiões, do escritório ao happy hour, sem abrir mão do conforto. Mais que um calçado, a sandália Campesí é um convite a um estilo de vida que celebra a autenticidade e o conforto. Permita-se desfrutar de um item que combina perfeitamente com as suas roupas favoritas, desde vestidos leves a calças de alfaiataria, transformando qualquer look em uma produção impecável. Garanta agora a sua e descubra o poder de um design atemporal que nunca sai de moda. Peso: 0,580 kg Altura do salto: 5,5 cm', 209.9, 199.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-mdka8kudekay2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F18698296287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594157732', 'PAR FAROL COROLLA 2005 A 2008 DEPO', 'OFarol Toyota Corolla 2005 A 2008 Marca Depo é fabricado com a mais alta tecnologia oferecida no mercado de iluminação automotiva. Com a lente extremamente resistente e um ótimo acabamento; os faróis do carro são itens imprescindíveis para trafegar com segurança, pois proporciona um aumentando de visibilidade e auxilia na iluminaçã, garantindo mais segurança em tempo chuvoso e nebuloso. Características: • Produto Novo de Ótima Qualidade; • Lente Lisa em Acrílico; • Máscara Cromada. Opções Disponíveis: • Direito (Passageiro); • Esquerdo (Motorista) Especificações Técnicas: • Foco Duplo; • Regulagem de Foco Manual; • Encaixe de Lâmpada na Baixa HB4; • Encaixe de Lâmpada na Alta HB3; • Suporta Xenon e Lâmpadas até 55 watts; • Não Acompanha Lâmpadas; Compatível com os Modelos: • Toyota Corrola 2003; • Toyota Corrola 2004; • Toyota Corrola 2005; • Toyota Corrola 2006; • Toyota Corrola 2007; • Toyota Corrola 2008; mportante: • Garantia de 3 meses; • Não nos responsabilizamos por instalação mal realizada; • A instalação deve ser feita por um profissional especializado.', 1476.87, 1255.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rasg-mb5ad5i6sbxy27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442439073%2F23594157732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
