INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699028623', 'Kit 10 Lâmpada Led Mini Dicroica Gu10 Mr11 3,5w Bivolt Luz Branca/Amarela', '💡 Destaque sua Iluminação com Eficiência e Estilo! 💡 Conheça as especificações excepcionais deste produto: 🔆 POTÊNCIA: 3,5W: Oferece uma iluminação eficiente e econômica. 🔌 CORRENTE: 44mA(127V) - 33mA(220V): Eficiência energética para diferentes voltagens. 💡 LUMENS: 200 LM: Proporciona uma iluminação brilhante e funcional. 🌐 ANGULO DE ABERTURA: 36°: Direcione a luz com precisão para realçar áreas específicas. 🔌 FATOR DE POTÊNCIA: >0,4: Contribui para uma operação mais eficiente. 🌈 COR: BRANCO FRIO (6500K) | BRANCO QUENTE (3000K): Escolha entre diferentes tonalidades para criar a atmosfera desejada. 💡 VIDA ÚTIL: 25.000 Horas (L70): Desfrute de uma iluminação duradoura. 🎨 IRC (ÍNDICE DE REPRODUÇÃO DE COR): >80: Garante uma reprodução de cores vívida e realista. 🔒 IP: IP20: Adequado para uso em ambientes internos. 🏋️ PESO: 19g: Leve e fácil de instalar. 🔧 BASE: GU10: Compatível com uma variedade de luminárias. ⚪ COR DO MATERIAL: Branco | Amarelo: Design versátil que se adapta a diferentes estilos. Destaque sua decoração e ilumine seu espaço com eficiência, aproveitando a versatilidade deste produto. 💡✨🏡', 90.0, 59.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lmxgc38m2lx84f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F18699028623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
