INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10574218643', 'Clips niquelado NR 10/0 com 79 unidades ACC', 'Clips niquelado 10/0 - com 20 unidades - ACC O clipes para papel é um artigo indispensável em um escritório. Produzido em aço niquelado, resistente a oxidação. Detalhes: - Resistente a oxidação. - Qualidade superior. - Flexível e resistente (não quebra fácil). - Sem rebarbas. - Alta durabilidade.', 64.2, 64.2, NULL, 'Stationery > School & Office Equipment > Clips, Pins & Tacks', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-lnhb2g7m7aki4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F10574218643', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11265193137', 'Bloco de notas super adesivas Post-it refil Verde Limeade 76x76mm 90 folhas 3M', 'Bloco de notas super adesivas Post-it refil verde limeade 76x76mm 90 folhas - 3M O Bloco Adesivo Amarelo Post-it® foi inventado por um pesquisador da 3M em 1980 e, desde então, conquistou o mundo! A inovação não parou por aí e outros tamanhos, formatos e cores vieram para facilitar ainda mais o nosso dia a dia. O Refil do bloco adesivo Post-it® da 3M, é especialmente produzido para ser utilizado nos Suportes Post-it® e tem um formato que lembra uma sanfona . Esse formato especial permite que ao puxar uma folha adesiva, você sempre tenha outra sempre à mão, retirando uma folha por vez de forma fácil e prática. Suas folhas são reposicionáveis, ou seja, possuem adesivo de qualidade 3M, que permite que sejam retirados e recolocados, sem danificar papéis ou outras superfícies, sem deixar resíduos do adesivo e sem perder a eficiência na fixação. Traga mais cor ao seu dia a dia e personalize sua mesa de trabalho ou anotações com blocos adesivos na azul aqua. Você anota todos os seus compromissos e lembretes, classificando-os por cor. São 90 folhas adesivas por bloco. Possui 2x mais adesão do que o bloco original Post-it® amarelo. Post-it® é perfeito para levar para qualquer lugar e chamar a atenção para as atividades na área de trabalho, na escola ou em casa. Detalhes: - Tamanho: 76 x 76mm - Ideal para anotar compromissos, tarefas, recados e tudo mais que você precisar - Reciclável, adesivo com base vegetal - Contém um bloco com 90 folhas. - O refil para suportes sistema puxa fácil Post-it são ótimas para retirada de uma nota por vez com apenas uma mão - Organização garantida sempre com o bloco refil e suporte de nota Post-it - Todos os blocos de notas adesivas Post-it são recicláveis. Detalhes do App: O Post-it App traz a simplicidade das Notas Adesivas Post-it para o seu smartphone ou tablet. Se você usa Notas Adesivas Post-it para colaboração ou para a tomada de notas pessoais, o App melhora sua produtividade e organiza suas ideias. Basta capturar as notas com a câmera, ou criar notas diretamente no seu dispositivo. Organize, refine e ajuste suas ideias no layout do App. Em seguida, compartilhe com amigos e colegas de trabalho, ou exporte para seus aplicativos favoritos e serviços de nuvem incluindo PowerPoint, Excel, PDF, Dropbox, entre outros. Os recursos do App Post-it: - Capture mais de 200 notas individuais Post-it de uma vez com sua câmera. - Desenhe, apague, digite e mude a cor das suas notas usando as ferramentas de edição. - Organize seu caminho: Agrupe suas ideias por pensamento ou simplesmente organize-as em uma grade. - Combine seus arquivos: Colete e combine ideias em várias sessões. - Compartilhe: Suporta PowerPoint, Excel, PDF, Dropbox, entre outras.', 27.28, 27.28, NULL, 'Stationery > Notebooks & Papers > Memo & Sticky Notes', 'https://cf.shopee.com.br/file/sg-11134201-820mb-mnczacj1tfd453', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F11265193137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098914244', 'Bengala Ortopédica Tubo Único', 'A Bengala Ortopédica Tubo Único foi desenvolvida para auxiliar pessoas com mobilidade reduzida, proporcionando apoio para prevenir quedas. Possui apoio de mão em formato tipo T para reduzir desconfortos, altura fixa e tubo único que diminui os ruídos durante a caminhada. Conta com ponteira articulada que oferece um movimento mais natural ao caminhar e base com textura antiderrapante.', 49.2, 49.2, NULL, 'Health > Medical Supplies > Injury & Disability Support', 'https://cf.shopee.com.br/file/sg-11134201-824ip-mefui0ukxam94a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264016428%2F22098914244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
