INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48059346407', 'Sandália Rasteirinha Feminina Vizzano Bico Quadrado Confortável Leve Plana Moda Verão', 'A sandália rasteira Vizzano une sofisticação e praticidade em um design minimalista e atemporal. O modelo apresenta bico quadrado e tira larga com acabamento tramado, que adiciona textura e um toque artesanal ao visual. Com palmilha lisa e solado flat, oferece leveza e conforto para o uso diário, sem abrir mão do estilo. Perfeita para combinar com vestidos, saias, jeans ou peças de alfaiataria leve, essa rasteira é a escolha ideal para quem busca um calçado moderno, feminino e fácil de usar. Tabela de Medidas: Tamanho 34: 22,5cm Tamanho 35: 23,5cm Tamanho 36: 24cm Tamanho 37: 24,5cm Tamanho 38: 25cm Tamanho 39: 26cm -- Com nosso ENVIO EXPRESS, você não precisa esperar muito para receber a sua rasteirinha! -- -- GARANTIA E NOTA FISCAL: Conte com nossa garantia de fábrica de 30 dias e nota fiscal para ter total tranquilidade e um produto de qualidade em suas mãos!! --', 99.9, 78.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-820le-mqni4lnpv8xve7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F344415614%2F48059346407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257384729', 'NOITE DOS MORTOS-VIVOS - EDIÇÃO COMEMORATIVA DE 50 ANOS', 'Atenção: para maior segurança dos leitores, esse livro clássico de zumbis recebeu um tiro nos miolos que perfurou de verdade todas as suas páginas. A NOITE DOS MORTOS VIVOS - EDIÇÃO COMEMORATIVA DE 50 ANOS ressurge das tumbas em alto estilo. Uma edição comemorativa da DarkSide® Books em homenagem aos 50 anos do filme que iniciou a epidemia zumbi. O livro é uma adaptação de duas histórias do mestre George Romero (In Memoriam) e do roteirista John Russo: A Noite dos Mortos Vivos e sua sequência, a Volta dos Mortos-Vivos, numa versão inédita no cinema. São dois romances no mesmo volume! A edição comemorativa tem capa dura e ilustrações exclusivas de Danilo Beyruth (Bando de Dois, Astronauta).Se hoje os zumbis estão em alta é porque, em 1968, G', 109.9, 92.32, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-82633-mm4t492a9ouc7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58257384729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
