INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697488052', 'O filho de Netuno - Série Os heróis do Olimpo Vol. 2, por Rick Riordan - Intrínseca', 'O filho de Netuno - Série Os heróis do Olimpo Vol. 2, por Rick Riordan - Intrínseca Descrição do Livro: A vida de Percy Jackson é assim mesmo: uma grande bagunça de deuses e monstros que, na maioria das vezes, acaba em problemas. Filho de Poseidon, o deus do mar, um belo dia Percy desperta sem memória e acaba em um acampamento de heróis que não reconhece. Agarrado à lembrança de uma garota, só tem uma certeza: os dias de jornadas e batalhas não terminaram. Percy e seus novos colegas semideuses vão enfrentar os misteriosos desígnios da Profecia dos Sete. Se falharem, as consequências, é claro, serão desastrosas. Com início no “outro” acampamento meio-sangue e se estendendo para além das terras dos deuses, esta sequência da série Os heróis do Olimpo apresenta novos semideuses e criaturas incríveis, além de trazer de volta alguns monstros bastante conhecidos. Best-seller da Veja Sobre o Autor: Rick Riordan, considerado o “contador de histórias dos deuses”, é autor best-seller do New York Times, premiado pela YALSA e pela American Library Association, com mais de 7 milhões de livros vendidos no Brasil. Além das séries Percy Jackson e os olimpianos, Os heróis do Olimpo e As provações de Apolo, inspira¬das na mitologia greco-romana, Riordan assina as séries As crônicas dos Kane, que visita deuses e mitos do Egito Antigo, e Magnus Chase e os deuses de Asgard, sobre mitologia nórdica. Pela Intrínseca, também publicou A filha das profundezas e O sol e a estrela: Uma aventura de Nico di Angelo, escrito em parceria com Mark Oshiro. O sucesso chegou também à televisão e ao cinema: Percy Jackson e os olimpianos vai ganhar uma série produzida pelo Disney e As crônicas dos Kane será adaptada para filmes pela Netflix. Detalhes do livro: Tradutor: Raquel Zampil Número de Páginas: 432 Gênero: Jovens e Adolescentes Dimensões do livro: 16 x 23 x 2,2 Peso do livro (Kg): 0,57 Tipo de capa: Livro brochura (paperback) Data de lançamento: 27/04/2012 Idioma do livro: Português Traduzido do: Inglês', 79.9, 63.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luw6ipy0mq1x14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F23697488052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699689375', 'Lavadora de Alta Pressão e Aspirador 2 em 1 Vonder LAV 1580 Com Acessórios', 'Lavadora De Pressão e Aspirador 2 Em 1 LAV 1580 Com Acessórios Vonder A Lavadora + Aspirador é ideal para limpezas gerais de pisos, carpetes, móveis, veículos e muito mais. Compacta e potente, possui alça telescópica e rodas, facilitando o transporte e armazenamento. Função Lavadora: Conta com suporte para pistola e acessórios, além de bico ajustável para jato leque ou concentrado. Com potência de 1.500 W, oferece pressão máxima de 1.885 lbf/pol² (130 bar) e vazão de 312 litros/hora, garantindo eficiência na remoção de sujeiras. Função Aspirador: Potência de 800 W e reservatório removível de 1,5 L com filtro HEPA, capaz de aspirar tanto sólidos quanto líquidos. Também possui função soprar, aumentando sua versatilidade. Itens que Acompanham o Produto 1 Pistola com gatilho 1 Lança 1 Bico ajustável (jato leque ou concentrado) 1 Bico turbo 1 Mangueira de alta pressão de 5 m 1 Mangueira de aspiração 1 Bocal escova multiuso 1 Bocal para cantos Detalhes Técnicos do Produto Modelo: LAV 1580 Potência da lavadora: 1.500 W Potência do aspirador: 800 W Capacidade do reservatório: 1,5 L Material do pistão: Aço inox Sistema de desligamento: Automático (Stop Total) Vazão máxima: 312 L/h - 5,2 L/min Pressão máxima de saída de água: 1.885 lbf/pol² - 130 bar - 13 MPa Pressão nominal de saída de água: 1.230 lbf/pol² - 85 bar - 8,5 MPa Vácuo: 16 kPa Comprimento da mangueira de alta pressão: 5 m Comprimento do cordão elétrico: 5 m Aspiração: Sólidos e líquidos Peso aproximado: 8,9 kg Normas atendidas: IEC 60335-1, IEC 60335-2-2 e IEC 60335-2-79 Por que Escolher este Produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 899.99, 899.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj5nqspbdt6u16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F18699689375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
