INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799358097', 'Cômoda Gaveteiro Infantil New Classic Branco Com Pés Madeira - Reller', 'Cômoda Gaveteiro Infantil New Classic Branco Com Pés Madeira - Reller Cômoda Gaveteiro Infantil New Classic Branco com Pés Madeira Reller Quando chega o momento de comprar os móveis para o bebê, procuramos modelos que atendam a todas as nossas expectativas e necessidades. Com esse pensamento, apresentamos a você a Cômoda Gaveteiro Infantil New Classic com Pés Amadeirados, fabricada pela Reller. Este lindo produto foi projetado para lhe trazer muito espaço para guardar roupas e acessórios em suas 3 gavetas, o que facilitará a vida da mamãe na hora de deixar todos os itens do bebê organizados. Confira mais informações a seguir! Características Técnicas: - Desenvolvido em MDF - Sistema de pintura utiliza tinta atóxica, que não faz mal a saúde do bebê - Pintura e acabamento em U.V na cor Branco Acetinado - Possui 03 Gavetas - Corrediças Telescópicas deslizam livres de enrosco - Maior organização e praticidade - Puxadores embutidos - Pés amadeirados desenvolvidos em madeira maciça, estilo retrô - Lindo design Dimensões: Altura: 91 cm Largura: 91 cm Profundidade: 46 cm Obs: Não realizamos a montagem, porém acompanha manual de instruções.', 556.71, 556.71, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxi-lypa1bi66ouyf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F18799358097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698954022', 'Pingadeira de Óleo 20L com Funil FORTG', 'Loja do Mecânico - O que você precisa, nós temos! Pingadeira de óleo com estrutura fabricada em material resistente proporcionando eficiência e durabilidade, possui aberturas para funis que facilitam a entrada do óleo e tripé. Indicada para todos os postos de serviços que oferecem troca de óleo. - Especificações Técnicas: :: Capacidade: 20L - Conteúdo da Embalagem: :: 1 Pingadeira de Óleo :: Coador de Óleo na Bacia :: 6 Funis com Formatos Diferentes :: 1 Torneira para Escoamento do Óleo - Garantia: 3 Meses - 7890028225751 Ref.: FORTG-CB147F Marca.: FORTG', 452.99, 452.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkt-lll3ivkirajh6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F21698954022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18298678954', 'Furadeira Profissional 110/127V Potência 900W 60hz Mandril 13mm 3000rpm 45000bpm - Deko', 'Furadeira leve e portátil com uma excelente relação impacto-peso para oferecer melhor desempenho, possui dois modos de função, preparados para diferentes locais de trabalho, é absolutamente uma ferramenta perfeita para profissionais e iniciantes. - Especificações Técnicas: :: Tensão/Frequência Nominal: 127V~60Hz :: Potência de entrada: 900W :: Velocidade sem carga: 0-3000 rpm :: Taxa de Impacto: 0-45000 bpm :: Tamanho do mandril de metal: 1/2'''' (13mm) :: Isolamento Duplo :: Máx. Capacidade de Perfuração: - Alvenaria: 13mm - Metal: 13mm - Madeira: 25mm - Conteúdo da Embalagem: :: 1 Furadeira de Impacto :: 1 Empunhadura Auxiliar :: 1 Limitador de Profundidade :: 1 Chave de Mandril - Garantia: 1 Ano - 7890028569541 Ref.: DEKO-DKID13G90 Marca.: DEKO', 249.99, 249.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvec-ljbjlamw435y4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F18298678954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394456408', 'Boia Crocodilo', 'A Boia Crocodilo garante mil brincadeiras nos dias quentes de verão! Com aparência que imita o animal, ela vai incentivar a imaginação e a criatividade da garotada na piscina. Produzida em PVC extremamente durável é resistente contra objetos perfurantes. Caso um acidente aconteça, a Boia acompanha um kit reparo que vai permitir que você mesmo conserte sem precisar fazer muito esforço. A Boia Crocodilo conta com duas câmaras de ar independentes e uma alça para que a criança possa se segurar, garantindo mais segurança durante seu uso. Conta ainda, com duas câmaras de ar independentes. Atenção! Este não é um equipamento salva-vidas. Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto.', 72.0, 72.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824i1-mf8ijdr5b9xr34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F22394456408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198948130', 'Mesa Portátil para Cadeira de Praia', 'A Mesa Portátil para Cadeira Mor traz mais praticidade aos seus momentos de lazer. Com quatro compartimentos de tamanhos diferentes, é perfeita para manter seu protetor solar, celular ou latinhas de bebida sempre por perto. Versátil, possui encaixe nos modelos de Cadeira Alta Mor, Cadeira Alta Conforto Mor, Cadeira Reclinável Boreal Mor, Cadeira Reclinável 4 posições Mor, Cadeira Reclinável 8 Posições Mor, Cadeira Master Mor e Cadeira Master Plus Mor.Perfeita para ser utilizada em casa, na praia, no camping ou no clube, é uma opção diferenciada de presente ou mesmo de brinde para distribuir no Verão. Disponível na cor azul é produzida em polipropileno resistente e vai te acompanhar por muitas temporadas!', 33.0, 33.0, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gm-mfbbgmy4oc999d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23198948130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198947899', 'Cesto com Prendedores Standard 36 Peças', 'Um kit completo para auxiliar suas atividades na lavanderia de casa. Este é o Cesto de Prendedores Standard. Com trinta e seis peças, ele possui três opções de cores de prendedores em polipropileno e arame em aço. Ideais para peças leves, não marcam suas roupas e vem em peças sortidas nas cores rosa, verde e azul. Acompanha simpático cestinho com alças para manter seus prendedores sempre à mão. Uma boa ideia para presentear em chás de panela!', 25.0, 25.0, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-820mu-mnlqiqzs3zt41f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23198947899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598316548', 'Sala de jantar tampo em Mdf 6 Cadeiras grafite com imbuia', 'Sala de jantar Aster 180 Tampo em MDF Canto Reto com 6 Cadeiras Liz Moderna grafite com imbuia Quando o assunto e jantar em casa, voce nao precisa se preocupar com nada alem do cardapio, certo? Entao, para que seus convidados se sintam em casa e ainda com aquele bom gosto, adquira o Conjunto de Mesa de Aster, um conjunto completo com tudo o que voce precisa para o evento perfeito: 6 cadeiras confortaveis, com detalhes de costuras alem de um puxador para dar um toque especial de charme; tampo muito bem dimensionado e design um inovador e chamativo. Alem do visual moderno, a combinacao de cores tambem resulta em um movel louvavel que sera palco de belos momentos. Caracteristicas: Material: MDF Garantia do Fabricante: 3 meses Informacoes Importantes: Nao contem vidro. Os objetos que ambientam as fotos nao acompanham o produto. Nao disponibilizamos a montagem do produto. O produto acompanha manual de montagem. Nao nos responsabilizamos por danos no produto causados por montagem de qualquer outra forma que nao seja a descrita no manual. Verifique as dimensoes do produto e certifique-se que o percurso que ele fara ate o local de uso permite sua passagem. A Moderna Mobilia reserva o direito de alterar as especificacoes tecnicas sem previo aviso. As medidas contidas no site podem sofrer variacoes de acordo com a montagem, tipo de costura etc. As tonalidades das cores podem sofrer alteracao de acordo com a configuracao de cada monitor.', 1599.9, 1599.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-lxx24ctzx93cf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23598316548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799420491', 'Secadora Brastemp Suspensa 10 kg BSI10BB', 'A Secadora Suspensa Brastemp 10Kg - BSI10BB é a escolha ideal para quem procura um eletrodoméstico prático e funcional para o seu dia a dia. Com um design moderno e elegante, essa secadora é a opção perfeita para quem deseja secar roupas com facilidade e rapidez. Secagem no tempo ideal que garante roupas mais fáceis de passar. Ciclo desodorizar com jato de ar que suaviza odores indesejáveis. Ciclo Edredom seca todo tipo de roupa, até o edredom Caracteristicas: Função Passe Fácil: Secagem no tempo ideal que garante roupas mais fáceis de passar, facilitando as tarefas no dia a dia. Função Ciclo Edredom: Seca todo tipo de roupa sem preocupação e sem esforço, até seu edredom*. *Edredom de solteiro. Pode ser necessário utilizar o ciclo edredom mais de uma vez. Função desodorizar: Perfeito para suavizar odores indesejáveis. Jato de ar que revitaliza suas roupas sem precisar lavar ou secar. Programa Certo: Girou secou: você escolhe o ciclo de secagem em apenas 1 botão. Filtro de Fiapos: Sua roupa seca e livre de fiapos Potência: 2200W Dimensão Altura: 90 cm Largura: 64 cm Profundidade: 67 cm Peso: 43 kg Garantia: 12 meses', 2999.9, 2880.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-825zp-mmgemhg5wd8l63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561901020%2F23799420491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
