INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28568938881', '[Novo] AMUSE Fondue Balm, 3.2g', 'Balma DE FONDUE, 3,2g O bálsamo labial colorido anti-envelhecimento que torna os lábios firmes e volumizantes proporcionam antienvelhecimento nos lábios, Hidratante duradouro de 24 horas e teste clínico concluído sobre irritação em tipos de pele sensível. Este bálsamo labial colorido compacto é feito com design claro de AMUSE. As tonalidades rosa, rosa, bege, coral e mlbb são divididas em muitos tons quentes e frescos diferentes para permitir uma ampla gama de escolhas para todos os tipos de tons pessoais e preferência. O produto de preenchimento que não resulta em quaisquer células mortas da pele dos lábios e rugas como fondue macio fornece derretimento doce nos lábios e deslizamento suave para dar adesão fina e firme. Fornece melhoria da elasticidade dos lábios e melhoria da aspereza e anti-envelhecimento. Contém 11 tipos de ácidos hialurônicos, colágeno e pantenol para hidratação de 24 horas e teste de irritação concluído em tipos de pele sensível.', 97.86, 97.86, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7rfhc-m33chyybp8n083', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F28568938881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
