INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54462353779', 'SKIN1004 Centella Tea Trica Mild Peeling Gel, 125ml', '✨ SKIN1004 Centella Tea-Trica Mild Peeling Gel 125ml ✨ 💖 Product Description Reveal smoother and clearer-looking skin with SKIN1004 Centella Tea-Trica Mild Peeling Gel 💚✨ This gentle peeling gel is formulated with Madagascar Centella Asiatica Extract and the Tea-Trica Complex to help remove dead skin cells, excess sebum, and impurities while soothing sensitive skin 🌿💧 The mild exfoliating formula helps refine skin texture without harsh scrubbing, leaving the skin feeling soft, fresh, and balanced. 🌟 Key Benefits ✔️ Gently removes dead skin cells ✨ ✔️ Helps unclog pores and remove excess sebum 💧 ✔️ Improves rough and uneven skin texture 🌿 ✔️ Soothes and calms sensitive skin 💕 ✔️ Leaves skin soft, smooth, and refreshed ✔️ Mild exfoliation suitable for regular use 🧴 Main Ingredients 💚 Madagascar Centella Asiatica Extract 💚 Tea Tree Leaf Water 💚 Tea Tree Extract 💚 PHA (Polyhydroxy Acid) 💚 Panthenol 💚 Hyaluronic Acid 📝 How to Use After cleansing, apply an appropriate amount to dry skin. Gently massage in circular motions, avoiding the eye and lip areas. Rinse thoroughly with lukewarm water. Use 1–2 times per week for best results ✨ 📦 Product Details Brand: SKIN1004 Product Name: Centella Tea-Trica Mild Peeling Gel Volume: 125ml Skin Type: All Skin Types Country of Origin: Korea 🇰🇷', 127.01, 121.0, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134207-824g8-mplvinnzlk3v3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F54462353779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
