INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799674367', 'Loção Corporal Deo Hidratante Paixão Tentadora Ameixa Rubi 400ml', 'A Loção Hidratante com ação desodorante vai garantir a hidratação da pele por 24 horas. Sua fórmula possui óleo de amêndoas e a fragrância é composta por óleo de amêndoas e a fragrância notas de frutas como morango e melão são misturadas a notas de violeta e rosa, harmonizadas pelo adocicado da baunilha. De uso diário, é recomendado para todos os tipos de pele.', 25.99, 25.99, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rd6w-m76yui28z7nt2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F18799674367', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
