INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394373254', 'Tênis Feminino Branco Sola Tratotada Ramarim 2575201-4', 'Tênis Feminino Branco Sintético – Forro Bactericida e Solado Tratorado Antiderrapante Descrição O tênis feminino branco é um clássico que nunca sai de moda. Produzido em material sintético resistente, ele combina praticidade e estilo em um só calçado. O forro bactericida garante mais higiene e frescor para os pés, enquanto o solado tratorado antiderrapante proporciona segurança e firmeza ao caminhar. Versátil e moderno, é ideal para o dia a dia e composições fashion. Detalhes do Produto Material: Sintético de alta qualidade Forro: Bactericida, que oferece mais higiene e proteção Solado: Tratorado em borracha antiderrapante Fechamento: Cadarço ajustável Palmilha: Macia e anatômica para maior conforto Cor: Branco clássico Estilo: Urbano, casual e atemporal Sugestão de Moda O tênis branco é peça-chave no guarda-roupa feminino. Combine com jeans de diferentes cortes, saias midi ou até vestidos leves para criar um contraste moderno e estiloso. Também funciona em looks monocromáticos, trazendo sofisticação ao visual casual. Sugestão de Uso Ideal para o dia a dia, trabalho casual, faculdade, passeios e viagens. Confortável e versátil, é perfeito para quem deseja unir estilo e praticidade. Cuidados e Limpeza Limpar com pano úmido e sabão neutro Não utilizar máquina de lavar ou secar Secar sempre à sombra em local ventilado Guardar em local seco e arejado, protegido da luz solar direta', 199.9, 192.8, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824ik-me8wkk2ns3k398', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1011144984%2F23394373254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204595132', 'Boca Rosa Hidra Lábios Marrom Translúcido - Gloss Labial 3g', 'O Gloss Labial Boca Rosa Hidra Lábios é um produto inovador que proporciona hidratação intensa e brilho translúcido aos lábios. Com sua fórmula leve e sedosa, este gloss desliza suavemente sobre os lábios, proporcionando um acabamento natural e um toque sutil de cor. Enriquecido com ativos premium como Esqualano, Manteiga de Karité e Vitamina E, este gloss labial nutre, revitaliza e protege os lábios ressecados, deixando-os macios, hidratados e com um aspecto saudável. Sua fórmula vegana e livre de fragrância é dermatologicamente testada e não comedogênica. Com excelente espalhabilidade, garante uma aplicação uniforme e fácil para um resultado surpreendente. Como usar: Com movimentos suaves, espalhe o gloss de maneira uniforme, cobrindo toda a superfície labial. Sinta a textura sedosa e leve se misturando aos seus lábios, proporcionando uma hidratação profunda e um brilho natural. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 44.9, 44.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-82610-mka3zeg7cao303', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204595132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262855425', 'Lola from Rio A Fórmula Brilho Lamelar - Primer Capilar 200ml', 'Primer capilar para cabelos danificados e opacos. Lola from Rio A Fórmula Brilho Lamelar confere um acabamento luminoso digno de salão. O Primer Capilar Lola from Rio A Fórmula Brilho Lamelar reduz drasticamente o frizz e proporciona um toque sedoso, mantendo o movimento natural. Uma escolha ideal para quem busca praticidade, pois agiliza a secagem (inclusive ao natural) e blinda o cabelo contra o calor de ferramentas térmicas e agressores externos. Como Usar: Aplique cerca de 3 pumps na palma da mão e espalhe nos cabelos úmidos, do comprimento às pontas. Finalize como preferir. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 36.9, 36.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-824in-mpnz291o5wjx55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58262855425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099348964', 'L''Amour Fiorucci Eau de Cologne - Perfume Feminino 90ml', 'L''Amour é um perfume Fiorucci feminino floral oriental. Aroma para mulheres apaixonadas, que deixam um rastro por onde passam graças à sua personalidade cativante. O perfume Fiorucci L''Amour mostra o lado bom dos sentimentos amorosos com a harmonia entre as notas mandarina, bergamota, pimenta rosa, gardênia e algodão doce. Tudo isso com uma base de sândalo e baunilha. Uma verdade aliança entre delicadeza e sensualidade. Experimente também Lumière, outro sucesso de Fiorucci. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 68.9, 68.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8261v-mkilupg7a9zb13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23099348964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
