INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497083407', 'Kit Absorvente Protetor Masculino Tena Men Active Fit 10 Unidades + Cueca Descartável Tena Pants Men P/M 16 Unidades', 'Kit contém:Absorvente Protetor Masculino Tena Men Active Fit 10 Unidades +Cueca Descartável Tena Pants Men P/M 16 Unidades TENA Pants MEN é uma roupa íntima descartável que veste como cueca, desenvolvida especialmente para homens com incontinência urinária moderada que buscam conforto, discrição, segurança contra vazamentos e manter o cuidado com a pele. Possui neutralizador de odor e uma zona de absorção segura, formato anatômico que se ajusta perfeitamente ao corpo proporcionando conforto, facilidade de uso e discrição. A segurança deve-se especialmente à uma zona de absorção frontal que absorve rapidamente a urina, mantendo-a longe da pele e assim, deixando-a seca, auxiliando a reduzir o risco de irritações ou infecções cutâneas. TENA Pants MEN é ideal para homens ativos, discreto como uma cueca, com controle de odor e alta absorção.', 135.19, 135.19, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7qvds-li8x44ufe70t92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F21497083407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47453256400', 'Loção Hidratante NIVEA Firmador Q10 + Vitamina C Pele Seca 200ml', 'O que é? NIVEA Loção Hidratante Firmador Q10 + Vitamina C Pele Seca é uma loção hidratante que conta com a poderosa combinação de Q10 e Vitamina C em sua fórmula. Para que serve? Indicado especialmente para pele seca, este hidratante firmador previne a flacidez e melhora a elasticidade da pele em apenas 10 dias de uso. Sua textura leve e de rápida absorção permite uma hidratação profunda por até 48 horas. Os antioxidantes presentes na fórmula trabalham juntos para melhorar visivelmente a firmeza da pele. Dermatologicamente testado e com ingredientes naturais. NIVEA Loção Hidratante Firmador Q10 + Vitamina C Pele Seca é o cuidado diário que sua pele merece. Experimente e comprove os resultados incríveis! Benefícios e diferenciais: - Firma visivelmente a pele e melhora sua elasticidade. - Previne a flacidez. - Hidrata intensamente por 48 horas. - Possui textura leve. - Contém vitamina C na composição.', 36.48, 36.48, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-81zu9-mid1jv36ap6r4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F47453256400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398370841', 'Faixa Mercedes Benz 1113 1114 Padrão 1987 Adesivo Prata', 'Adesivo Genérico._x000D_ As faixas decorativas além de determinar, em muitos casos, o modelo do veículo, também personalizam o seu carro e protegem a pintura. Os adesivos são produzidos em vinil automotivo autocolante importado, dispensando a utilização de produtos para a fixação. Produto já com verniz para maior durabilidade!_x000D_ _x000D_ Kit Faixa Caminhão Mercedes Benz 1113 1114 Padrão 1987 Adesivo Prata + Adesivos Etiquetas Advertência e Aprovado do Para-brisa - _x000D_ _x000D_ CARACTERÍSTICAS:_x000D_ 1 Par de Faixas Laterais (portas)/ Fabricado em Vinil Transparente/ Dimensões: 105,4 x 84,2 cm 1 Par de Faixas (para-lama)/ Fabricado em Vinil Transparente/ Dimensões: 88,9 x 10,4 cm_x000D_ 17 Adesivos Etiquetas de Advertência_x000D_ 5 Adesivos Aprovados de Para-brisa feitos no Vinil Transparente_x000D_ _x000D_ Observações:_x000D_ Material autocolante._x000D_ Resistente à chuva e raios UV._x000D_ Embalagem segura para o transporte._x000D_ Vinil importado._x000D_ _x000D_ Instruções Para Aplicação:_x000D_ 1 - Limpe e remova qualquer impureza na área de aplicação do produto._x000D_ 2 - Limpe as mãos e remova o protetor do liner._x000D_ Procure ter o mínimo de contato com a face adesiva._x000D_ 3 - Centralize o produto no local da aplicação. Após esse posicionamento,_x000D_ pressione o produto gradativamente, sempre do centro para as bordas._x000D_ Procure retirar todas as bolhas._x000D_ 4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,_x000D_ pois isso danificará o produto._x000D_ _x000D_ OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo._x000D_ Recomendamos que a aplicação seja feita por um profissional._x000D_ _x000D_ Garantia de 1 ano.', 105.0, 95.55, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reqn-m83uo9g7gm2101', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F23398370841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46853243375', 'Hidratante Labial NIVEA Morango Shine 4,8g', 'O que é? NIVEA Hidratante Labial Morango Shine é um produto essencial para cuidar e proteger os lábios durante 24 horas. Para que serve? Sua fórmula contém óleos naturais que proporcionam hidratação intensa, deixando os lábios sempre macios. Além disso, possui um delicioso aroma de morango e pigmentos brilhantes que realçam o sorriso. Ele serve para hidratar e proteger os lábios, garantindo uma aplicação uniforme e sem necessidade de espelho. Sua embalagem é reciclável, contribuindo para a preservação do meio ambiente. Com óleos de abacate e jojoba em sua composição, NIVEA Hidratante Labial Morango Shine proporciona benefícios extras para a saúde dos lábios. Benefícios e diferenciais: - Hidratação prolongada - Aroma de morango e pigmentos brilhantes - Dermatologicamente testado - Livre de óleos minerais - Aplicação uniforme sem precisar de espelho', 31.16, 31.16, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-81ztv-mid41icslj4673', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F46853243375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11848714362', 'Kit c/ Shampoo + Condicionador Pantene Brilho Extremo 400 ml', 'Shampoo Brilho Extremo limpa seus cabelos eliminando a oleosidade, resíduos e substâncias acumuladas. Sua exclusiva fórmula translúcida deixa o cabelo livre de sal. Desenvolvida com a tecnologia Pro-V do Pantene Institute, é leve e absorvida instantaneamente pelo cabelo. A partir do primeiro uso você sentirá seus fios mais macios, soltos, com extra brilho e um movimento incrível. Dica Pantene: Use sempre água morna para lavar o cabelo e massageie suavemente com as pontas dos dedos para não machucar o couro cabeludo. Para uma hidratação mais completa e melhores resultados, use a linha completa Pantene Brilho Extremo.', 75.09, 71.38, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/cd596b48a45a87100e651055af05a84a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11848714362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212836154', 'Gel Dental Malvatrikids Kids Extrato Natural com Flúor Sabor Morango Anticárie 85g Ganhe 15g', 'Gel Dental Infantil Malvatrikids Extrato Natural Com Flúor Sabor Morango – Embalagem Promocional 85g Cuide do sorriso do seu filho com a pureza e a eficácia que ele merece desde o início com o Gel Den', 25.49, 25.49, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-824hx-mpnpz85ir09a25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F58212836154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093606691', 'Kit 2 Protetor Solar Anthelios Airlicium+ FPS80 Antioleosidade Cor 5.0 40g', 'O protetor solar La Roche-Posay Anthelios Airlicium FPS 80 oferece muito alta proteção contra os raios UVA e UVB, prevenindo os danos causados pelo sol. Com tecnologia Airlicium, controla a oleosidade e o brilho ao longo do dia, proporcionando um acabamento seco e confortável. Desenvolvido especialmente para peles oleosas, reduz a produção de oleosidade em até uma semana de uso. Com cobertura suave e antioxidantes, protege e cuida da pele ao mesmo tempo. Ideal para quem busca proteção avançada com controle de brilho.', 179.98, 179.98, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-823p5-mon5p8yk89vl89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23093606691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
