INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798255460', '[Venda em combo] Gaabor Aspirador de pó portátil GVCW-M15A + Ferro de passar a vapor portátil HM-M01A 2 em 1 top clean', 'Aspirador de Pó Portátil Gaabor 16.000Pa (GVCW-M15A) Poder e praticidade para limpeza rápida! 🌀 16.000Pa de Sucção - Elimina pó, sujeira e partículas com eficiência 🔄 Sistema Tripla Filtragem - Retém poeira fina sem refluxo 🛠 Escova Giratória 90° - Acessa cantos difíceis com facilidade 🗑️ Depósito 1,5L Removível - Esvaziar e limpar é simples 🔋 Leve e Compacto - Apenas 1,4kg, ideal para uso diário Especificações: Potência: 1000W Dimensões: 15x15x52cm Inclui: Aspirador + Manual Ferro a Vapor Portátil Gaabor 1200W Passa roupas em segundos, sem complicação! 💨 Vapor Rápido (14ml/min) - 6 orifícios para distribuição uniforme ⚡ Pré-aquecimento em 30s - Praticidade para o dia a dia 🔄 Cabo Giratório 180° - Manuseio confortável 🌡 Alta Temperatura (140°C) - Esteriliza e remove vincos 💧 Tanque 120ml - Autonomia para várias peças Destaques: Placa cerâmica nano (antiaderente) Desligamento automático Peso: 735g (ultraportátil) Acessórios Inclusos: Base protetora Copo medidor Por Que Escolher Gaabor? ✔ Tecnologia Profissional - Resultados superiores em casa ✔ Design Inteligente - Produtos ergonômicos e fáceis de armazenar ✔ Segurança Garantida - Proteções integradas em todos os modelos ⚠ Importante: Todos os produtos possuem tomada padrão brasileiro Não utilize adaptadores - risco de danos 🔥 Promoção de Lançamento: Compre qualquer 2 itens e ganhe frete grátis! #Gaabor #AspiradorDePó #FerroAVapor #CasaLimpa #DOMUSSTORE', 679.0, 358.0, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbdgs7x4w7axd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1541348350%2F21798255460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
