INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693477205', 'Doce De Leite Tradicional Linea 210g - 2 unidades', 'Linea Doce de Leite Tradicional possui uma cremosidade que vem do cozimento. Sem adição de açúcares, é adoçado com sucralose, o adoçante derivado da cana de açúcar que contribui para a redução de sódio e calorias. Possui baixo teor de sódio, contém apenas 50kcal por colher, e pode ser utilizado para o preparo de doces ou sobremesas. 1 Kit Composto por: Doce De Leite Tradicional Linea 210g - 2 unidades INGREDIENTES leite integral, cloreto de sódio, edulcorantes: sorbitol e sucralose, conservante sorbato de potássio, regulador de acidez bicarbonato de sódio, espessante pectina e estabilizante citrato de sódio. CONTÉM LEITE. PODE CONTER NOZES. CONTÉM LACTOSE.', 83.98, 75.58, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Jam & Spread', 'https://cf.shopee.com.br/file/sg-11134201-7rdxx-m1eijty27l325a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23693477205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699038060', 'True Collagen - 390g Limonada Suíça - True Source', 'True Collagen é fonte de proteína hipoalergênica com peptídeo bioativo do colágeno hidrolisado Verisol e enriquecido com os mais nobres nutrientes. Esse produto é para quem busca a beleza e a saúde de dentro para fora, pois uma pele radiante é resultado de um intestino saudável. No True Collagen contém vitamina C, silício orgânico Exsynutriment, ácido hialurônico, zinco, biotina, além de outros nutrientes essenciais para a saúde de sua pele, unhas e cabelo. Tudo para manter a sua beleza radiante e seu intestino saudável. Produto livre de corantes e adoçantes artificiais. Limpo, leve, saudável e nutritivo assim como a True Source. Como Tomar Diluir uma dose (14g) de True Collagen em água ou bebida de sua preferência. Consumir logo após o preparo uma vez ao dia antes de dormir ou conforme prescrição do nutricionista. Ingredientes Colágeno Hidrolisado (peptídeos bioativos de colágeno), Peptídeos bioativos de colágeno (Verisol), Polpa de Limão em pó, Ácido Ascórbico (Vitamina C), Bisglicinato de Zinco (Zinco Quelato), Hialuronato de Sódio (Ácido Hialurônico), DL Alfa Acetato de Tocoferol (Vitamina E), Ácido Pantotênico (Vitamina B5), Palmitato de Retinol (Vitamina A), Selenito de Sódio (Selênio), Biotina (Vitamina B7), Colecalciferol (Vitamina D3), Edulcorantes naturais (Eritritol, Stévia e Taumatina), Aromatizantes Naturais, Regulador de acidez Ácido cítrico. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. ALÉRGICOS: CONTÉM DERIVADOS DE SOJA. ...', 175.28, 175.28, NULL, 'Health > Food Supplement > Beauty Supplements', 'https://cf.shopee.com.br/file/sg-11134201-82585-mfwnk29x7itpf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22699038060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257595352', 'Camiseta Infantil Menino Manga Longa Botões Elian Marrom', 'Escolha certa para um visual que combina charme e conforto, a Camiseta Elian é perfeita para completar o guarda-roupa infantil. Feita em meia malha, ela possui mangas longas com punhos e recorte com sobreposição na gola, trazendo detalhes em botões no peitilho. Versátil para o dia a dia, ela combina facilmente com diversas calças. Aposte nesse look que é ideal para passeios e momentos especiais em família!Detalhes da peça: • Feita em meia malha • Possui mangas longas • Recorte com sobreposição na gola • Ideal para passeios, momentos em família e dia a dia', 79.9, 55.93, NULL, 'Baby & Kids Fashion > Boy Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-825b2-mr1tqwfpxzpd7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58257595352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994947806', 'Sorveteira Expressa EOS 1 Litro 4 em 1 Digital All Black ESO04P 110V', '🍨 Sorveteira Expressa EOS 1 Litro 4 em 1 Digital All Black ESO04P ❄️ Prepare sobremesas incríveis de forma rápida e prática com a Sorveteira Expressa EOS ESO04P. Moderna, compacta e sofisticada, ela possui compressor embutido e funções automáticas para criar sorvetes, smoothies, sorbets e iogurtes com textura perfeita. ✨ Destaques do Produto: ✅ Capacidade de 1 litro ✅ Sistema 4 em 1: Sorvete, Sorbet, Smoothie e Iogurte ✅ Compressor embutido sem necessidade de pré-resfriamento ✅ 6 modos automáticos inteligentes ✅ Função Manter Gelado por até 1 hora ✅ Painel Touch Digital moderno ✅ Componentes removíveis para fácil limpeza ✅ Design sofisticado em Black Piano ✅ Ideal para receitas mais saudáveis e personalizadas 📏 Medidas (LxAxP/cm): 35,5 x 22,7 x 26 cm 🏡 Perfeita para quem busca praticidade, tecnologia e sobremesas frescas e cremosas no dia a dia.', 1218.65, 1218.65, NULL, 'Home Appliances > Kitchen Appliances > Specialty Cookware', 'https://cf.shopee.com.br/file/sg-11134201-820lu-mnagyqt51nup8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F22994947806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
