INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397747008', 'Kit 5 Potes Porta Mantimentos Grandes Redondos Plasútil', 'Kit 5 Potes Porta Mantimentos Grandes Redondos Plasútil Dimensao: (Diâmetro x Alt): 23,2x26,0 cm - A linha Clic é composta por produtos tradicionais e versáteis. - Os porta mantimentos possuem tampa com fechamento rosca e são atóxicos e livres de bisfenol-A (BPA FREE). - Fabricado em plástico polipropileno (PP). - Com eles é possível organizar sua cozinha e despensa com os mantimentos mais usados no seu dia-a-dia, trazendo segurança no armazenamento e praticidade no preparo das refeições. - Além de funcionais, podem ser usados para fins decorativos em prateleiras ou armários. - Composto por potes de: 1 x 720 ml: 12,0 x 10,3 cm. 1 x 1,8 L: 15,1 x 15,3 cm. 1 x 3,2 L: 17,5 x 19,3 cm. 1 x 4,5 L: 19,8 x 21,7 cm. 1 x 7,6 L: 23,2 x 25,7 cm. - Os maiores possuem tampa com pegadores na parte central para facilitar a abertura. - Cor da tampa: vermelho..', 99.9, 99.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-lzgf7m3lxcsm18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F22397747008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
