INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40429004790', 'Baggio Drip Coffee Aroma Chocolate Avelã - Caixa com 10 Sachês 10g', 'O Baggio Drip Coffee Aroma de caramelo entrega o mesmo equilíbrio de sabores agora na praticidade do sachê individual. O café aromatizado Chocolate com Avelã tem sabor equilibrado e intensidade média, perfeitamente equilibrados com textura encorpada e aveludada, e aftertaste prolongado, tornando a experiência de beber café ainda mais prazerosa. Você sentirá um delicioso aroma de nozes e notas de chocolate que deixam um sabor duradouro na boca. O equilíbrio entre o doce do chocolate ao leite e o sabor tostado da avelã oferecem um sabor único e marcante. Cada caixa contém 10 sachês individuais. Aroma: Chocolate com Avelã Notas: Nozes e castanhas tostadas, chocolate ao leite Harmoniza com: Sobremesas e finalizações Bebida: Mole | Qualidade: Pontuação acima de 85 | Café Especial', 25.9, 25.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-820l7-mlnhhmtkmsxz99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1321479779%2F40429004790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893588015', 'Po Bronzeador Dopamine Angel Glow Ruby Rose Hbf1400', 'Descrição: O Po Bronzeador Dopamine Angel Glow Ruby Rose Hbf1400 possui uma fórmula leve e ultra-fina que proporciona um acabamento suave, com brilho sutil e natural. Sua textura aveludada e de fácil aplicação garante um efeito bronzeado perfeito, realçando os contornos do rosto com um toque luminoso, sem deixar a pele pesada ou oleosa. Ideal para um look iluminado e de longa duração, perfeito para todas as ocasiões. MODO DE USAR: 1 - Aplique o Pó Bronzeador nas áreas que deseja realçar e bronzear, como maçãs do rosto, têmporas, testa e queixo, usando um pincel de contorno. 2 - Para um efeito mais intenso, adicione camadas conforme necessário. 3 - Pode ser usado sozinho para um bronzeado natural ou combinado com outros produtos de maquiagem para um acabamento mais completo. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 1 unidades. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 19.99, 19.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-7rau4-mb3uexxuix5v7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F23893588015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
