INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40854927519', 'KIT C/2 COAT SPRAY SELAGEM BLINDAGEM ANTIFRIZZ TRESEMMÉ 180ML', 'ESSE KIT CONTÉM: 2 COAT SPRAY SELAGEM BLINDAGEM ANTIFRIZZ TRESEMMÉ 180ML Finalizador que blinda os fios contra a umidade e o frizz por até 3 dias. Sua fórmula com Queratina Hidrolisada e Ácido Hialurônico fortalece, hidrata e alinha a fibra capilar, deixando os cabelos mais macios, resistentes e protegidos desde a primeira aplicação. Benefícios: Controle do frizz prolongado Hidratação e brilho Reconstrução e fortalecimento Proteção térmica e UV Modo de uso:Aplique no cabelo úmido, do comprimento às pontas, sem enxágue. Para melhor alinhamento, finalize com secador. Indicado para todos os tipos de cabelo.', 99.8, 95.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rau3-mb48am8cvl9y8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F40854927519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19477230824', 'Pinote - Estrela', 'Pinote - Estrela Com esse brinquedo a criançada vai ter que mostrar toda sua habilidade. Em sequência os jogadores vão colocando os objetos na cela para o PINOTE carregar. Mas de repente, ele dá um pinote e derruba tudo. Só quem não deixar o PINOTE saltar é que será o ''domador'' vitorioso! Não requer pilhas. Para 2 ou mais jogadores.', 119.99, 119.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7qveu-lezs7a2uwzam28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19477230824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794323014', 'Condensador Ar Condicionado Palio Siena Strada Sistema BEHR *', 'Bem-vindo à loja oficial da GM AR PEÇAS E ACESSORIOS! Especificações: - Produto Novo - Material de Alta Qualidade - Tecnologia: ALUMÍNIO BRASADO - Medidas do Condensador: Altura(mm): 420 l Largura(mm): 354,6 l Espessura(mm): 12 OBS: SISTEMA BEHR - LARGURA DA COLMEIA MAIOR QUE O MODELO DENSO Aplicação: - Fiat Palio 1.0 l 8V 2009 a 2014 - Palio 1.4 l 8V 2010 a 2014 - Palio 1.6 l 16V 2010 a 2014 - Palio 1.8 l 8V 2009 a 2010 - Fiat Siena 1.0 l 8V 2008 a 2014 - Siena 1.4 l 8V 2008 a 2012 - Siena 1.6 l 16V 2010 a 2012 - Siena 1.8 l 8V 2008 a 2010 - Fiat Strada 1.4 l 8V 2010 a 2013 - Strada 1.6 l 16V 2012 a 2014 - Strada 1.8 l 16V 2010 a 2013 - Strada 1.8 l 8V 2008 a 2012 PRODUTO A PRONTA ENTREGA ***ENVIO IMEDIATO*** Nossa empresa fica consolidada no estado do Paraná e atuamos no ramo de distribuição de peças com sede em Londrina. Somos especializados em tudo o que é relacionado à ar condicionado de veículos de passeios, máquinas agrícolas e Pesados, contamos também com todas as ferramentas necessárias para manutenção e instalação. Hoje oferecemos ao mercado de peças de reposição, produtos de alta performance e durabilidade, aliadas com toda qualidade exigida pelas montadoras. IMPORTANTE • Recomendamos que a montagem seja feita de forma prática e eficaz, com auxílio de um profissional, evitando assim possíveis danos na peça ou em demais componentes do sistema. • Não nos responsabilizamos pela instalação indevida ou por mau uso da peça, causando assim a perda da GARANTIA. • Prazo de entrega, a GM AR PEÇAS E ACESSORIOS! garante despacho no mesmo dia para pedidos efetuados até as 13 horas. Para compras efetuadas após este horário, finais de semana e feriados serão enviadas no próximo dia útil. • Imagens meramente ilustrativas. E para finalizar, estamos aqui para melhor atender nosso cliente e, portanto, quaisquer eventuais dúvidas estamos à disposição no campo de resposta para lhe instruir. Nosso horário de atendimento: De SEGUNDA a SEXTA das 8:00 as 18:00.', 447.35, 447.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-mdgjfc8s13d6c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609542568%2F22794323014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
