INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297684146', 'Desodorante Aerosol Dove Invisible Dry 0% Alcool 250ml Leve mais Pague menos', 'O Desodorante Aerosol Dove Invisible Dry foi desenvolvido para não deixar manchas brancas em até 100 cores de tecido, mantendo sua roupa intacta. Fabricado com alta tecnologia, este antitranspirante eficaz oferece proteção duradoura e confiável. Controlando a transpiração nas axilas por até 48 horas, nosso antitranspirante que não mancha dá uma sensação de frescor com um delicado perfume floral. Com nosso exclusivo ¼ de creme hidratante enriquecido com óleo protetor, a fórmula deste desodorante antitranspirante sem perfume cuida da sua pele, ajuda a pele a se recuperar da irritação e deixa você com axilas macias e confortáveis.', 31.25, 31.25, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rd4p-lvavwiqg4fmh14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F19297684146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397505582', 'Locao Hidratante Facial Cerave 52ml', 'O CeraVe é uma loção hidratante de uso diário que utiliza a tecnologia patenteada MVE de liberação prolongada de ativos que ajudam a repor as ceramidas e proporcionar hidratação controlada e duradoura para a pele do rosto.', 106.39, 106.39, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-lvaqv094jn1de9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22397505582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193245490', 'Anzol Super Chinu Strong BlackNickel - Marine', 'O Anzol Super Chinu Strong BlackNickel é um anzol da marca Marine Sports, feito de aço carbono com revestimento em Teflon e acabamento em BlackNickel para maior durabilidade contra a corrosão. Ele é pequeno e robusto, super resistente e com ponta super afiada quimicamente. Ele é indicado para pesca de peixes pequenos e médios, como tilápia, pacu, sargo, porquinho, etc. O anzol chinu é bom para iscas naturais, como minhocas, massas, milho, ração, etc. Você também pode usar iscas vivas, como camarões e lambaris. Este anzol é comercializado nos tamanhos: O Anzol Super Chinu Strong Nº 1: Comprimento Aproximado: 13.12mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 2: Comprimento Aproximado: 14.57mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 3: Comprimento Aproximado: 16.07mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 4: Comprimento Aproximado: 18.19mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 5: Comprimento Aproximado: 18.74mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 6: Comprimento Aproximado: 20.47mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 7: Comprimento Aproximado: 21.97mm | Quantidade: 50 pcs O Anzol Super Chinu Strong Nº 8: Comprimento Aproximado: 23.88mm | Quantidade: 30 pcs O Anzol Super Chinu Strong Nº 9: Comprimento Aproximado: 25.66mm | Quantidade: 30 pcs O Anzol Super Chinu Strong Nº 10: Comprimento Aproximado: 27.90mm | Quantidade: 30 pcs Esse equipamento conta com 1 Fisga, sendo localizada na parte interna do anzol. ATENÇÃO: ESCOLHA O TAMANHO DO ANZOL DESEJADA ANTES DE FINALIZAR A COMPRA, SEGUINDO OS PADRÕES DESEJADO!! Não perca tempo adquira já o seu Anzol Super Chinu Strong BlackNickel aqui na Dispropil! Especificações Técnicas: - Marca: Marine - Modelo: Anzol Super Chinu Strong BlackNickel - Material: Aço Carbono, Acabamento em BlackNickel e Teflon - Compatibilidade: Carretilha e Molinete - Fisga Interna - Validade indeterminada itens inclusos: - 01 Anzol Super Chinu Strong BlackNickel', 25.9, 25.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-lz7wjv0i714kf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F22193245490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797736097', 'Dews 5mg/ml Solucao Oftalmica 10ml', 'DEWS® é indicado para melhora da irritação, ardor e secura dos olhos, que podem ser causadas pela exposição ao vento, sol, calor e ar seco, e também como protetor contra irritações oculares. É Também indicado como lubrificante e re-umidificante durante o uso de lentes de contato para aliviar o ressecamento, irritação, desconforto e coceira nos olhos. PARA MAIS INFORMAÇÕES CONTINUE LENDO A BULA.', 57.66, 57.66, NULL, 'Health > Personal Care > Eye Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-lyinriwkgxiv84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F20797736097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
