INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498547269', 'Colchão Light D23 – Solteiro (78x188x12) - Ortobom', 'Colchão Light D23 Solteiro (78x188x12) O Colchão Light D23 Liso Ortobom é ideal para quem busca conforto simples e eficiente no dia a dia. Confeccionado 100% em Espuma D23 Pró Aditivada de Alta Performance, oferece suporte para até 70 kg por pessoa, garantindo descanso confiável e confortável. O revestimento em tecido plano resistente com tratamento antiácaro e antialérgico proporciona durabilidade e noites de sono mais saudáveis. O Colchão Light D23 Ortobom é uma escolha prática e de qualidade, perfeita para quem valoriza conforto, resistência e durabilidade.', 384.9, 338.71, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mk8ew6v9o0zm2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F22498547269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493866188', 'Cozinha Compacta Luna Kappesberg 3 Peças Canela/Azul Profundo 192,5cm', 'Para quem gosta de beleza sem abrir mão de praticidade, a Cozinha Compacta c/ tampo CB1255 da Kappesberg é a escolha certa. Compacto e muito funcional, o kit reúne tudo que você precisa, trazendo facilidade e organização ao seu dia. Produzido em chapas MDP de 12 e 15mm, o que garante robustez, firmeza e qualidade, ela conta com até sete camadas de pintura na cor canela, em pintura touch, com a textura dos veios da madeira, remetendo aos tons da natureza e trazendo qualidade à sua cozinha, combinando com todos os espaços. Com pés em polipropileno e puxadores em alumínio na cor bronze, que garantem um acabamento lindo, o kit é conjugado, contando com amplo espaço interno, entre prateleiras e gavetas, ideais para organizar louças e mantimentos, deixando suas tarefas mais práticas e sua cozinha sempre em ordem. E com módulo para forno e microondas, você terá o espaço perfeito para seus eletrodomésticos, assim como o nicho superior, que facilita o acesso a itens usados diariamente. Já o tampo, garante um acabamento perfeito e mais facilidade, completando o design do produto. Medidas: • 212 cm de altura • 192,5 cm de largura • 52 cm de profundidade Itens inclusos: • Sete (7) portas tradicionais (portas de bater) • Três (3) gavetas internas (corrediças metálicas) • Cinco (5) prateleiras • Pés em polipropileno Código do produto: CB1255-CNAZP Informações importantes: • As imagens são ilustrativas. • A Kappesberg não disponibiliza serviço de montagem (recomendamos a contratação de um profissional qualificado). • O manual de montagem acompanha o produto. • Obs: Acompanha tampo de 120cm. • 3 meses de garantia para defeitos de fabricação.', 1673.02, 1359.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rau9-majs8jmgrnuef1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22493866188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
