INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47801448094', 'Protetor Solar Bebê Creme FPS70 Corpo Rosto Nutriex 120ml', 'O Protetor Solar Bebê Creme FPS 70 Corpo & Rosto da Nutriex traz proteção elevada para a pele delicada dos pequenos, com fórmula desenvolvida especialmente para uso infantil, textura suave de fácil aplicação e ação segura tanto no corpo quanto no rosto. Desenvolvido para que a rotina ao sol seja tranquila, divertida e com o máximo de cuidado. Sobre o produto: - Frasco de 120 ml. - Fator de proteção solar 70 (FPS 70). - Proteção UVA/UVB para pele infantil. - Fórmula resistente à água e suor. - Textura leve de fácil espalhabilidade, sem deixar sensação esbranquiçada. - Hipoalergênico. - Dermatologicamente testado. - Com Ativos como vitamina E. - Livre de conservantes. - Livre de parabenos e corantes. - Livre de óleos. - Rápida absorção. Indicado para: - Bebês (acima de 6 meses) e crianças. - Uso corporal e facial. - Para todos os tipos de pele infantil. Modo de uso: - Agite antes de usar. - Aplique generosamente sobre a pele seca ou ligeiramente úmida, no corpo e rosto da criança, cerca de 15 a 30 minutos antes da exposição ao sol. - Reaplique sempre após nadar, suar excessivamente, secar-se com toalha ou a cada duas horas de exposição contínua. Precauções: - Uso externo. - Evite o contato com os olhos; em caso de contato, enxágue abundantemente com água. - Suspenda o uso em caso de irritação ou sensibilização — procure orientação médica. - Armazene o produto em local fresco, seco, longe da luz direta e fontes de calor. Com alta proteção (FPS 70), textura amigável para crianças, fórmula resistente à água, suor e ideal para uso no corpo e rosto dos pequenos, o Protetor Solar Bebê Creme da Nutriex é a escolha inteligente para quem deseja aliar segurança, praticidade e cuidado diário na proteção da pele infantil. Surgiu alguma dúvida? Entre em contato com a gente! Boas compras :)', 74.36, 59.49, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-821dz-mh285y6fsky55c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F47801448094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42053382229', 'Sabonete Óleo De Banho Pitaya Dia Dia Corpo Labotrat 200ml', 'Pele macia, perfumada e intensamente hidratada em um só banho!O Sabonete Óleo de Banho Pitaya Dia a Dia Labotrat 200ml combina o poder nutritivo dos óleos com a suavidade de um sabonete líquido, promovendo uma limpeza delicada enquanto hidrata profundamente e envolve seu corpo com uma fragrância doce e marcante de Pitaya. Sobre o produto: - Sabonete Óleo De Banho Pitaya 200ml. - Marca: Labotrat. - Livre de Parabenos - Não testado em animais. - Uso corporal. - Ativos naturais. - 83% dos Lipídeos Restauradores. - Limpa delicadamente. - Hidrata profundamente. - Perfuma a pele com uma fragrância suave e duradoura. - Proporciona brilho saudável e aspecto nutrido. - Sensação de frescor pós-banho. - Não resseca a pele. - Espuma Cremosa. Indicado para: - Todos os tipos de pele. Como usar: - Durante o banho, aplique o produto diretamente sobre a pele úmida ou com o auxílio de uma esponja. - Massageie suavemente até formar espuma e enxágue em seguida. - Pode ser usado diariamente. Com o Sabonete Óleo de Banho Pitaya Labotrat, você transforma o banho em um verdadeiro ritual de beleza e hidratação. Sua fórmula rica e sua fragrância irresistível deixam sua pele com aparência saudável, toque macio e perfume encantador.Garanta já o seu e sinta na pele o cuidado que você merece! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 69.98, 55.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdx7-mbnwg1arubnxdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F42053382229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
